export default "HS256\\\", tmpdir)\\n            mock_auth_service = AuthService(mock_settings_service)\\n\\n            # Create token with different secret\\n            wrong_token = jwt.encode(\\n                {\\\"sub\\\": \\\"9cd4172c-0190-4124-a749-671d23e3c6dd\\\", \\\"type\\\": \\\"access\\\"},\\n                \\\"different-secret-key\\\",\\n                algorithm=\\\"HS256\\\",\\n            )\\n\\n            mock_db = AsyncMock()\\n\\n            with patch(\\\"langflow.services.auth.utils.get_auth_service\\\", return_value=mock_auth_service):\\n                with pytest.raises(HTTPException) as exc_info:\\n                    await get_current_user_from_access_token(wrong_token, mock_db)\\n\\n                assert exc_info.value.status_code == 401\\n\\n    @pytest.mark.asyncio\\n    async def test_expired_token_raises_401(self):\\n        \\\"\\\"\\\"Expired token should raise 401.\\\"\\\"\\\"\\n        from langflow.services.auth.service import AuthService\\n        from langflow.services.auth.utils import create_token, get_current_user_from_access_token\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_settings_service = self._create_mock_settings_service(\\\"HS256\\\", tmpdir)\\n            mock_auth_service = AuthService(mock_settings_service)\\n            mock_db = AsyncMock()\\n\\n            with patch(\\\"langflow.services.auth.utils.get_auth_service\\\", return_value=mock_auth_service):\\n                # Create token that's already expired\\n                token = create_token(\\n                    data={\\\"sub\\\": \\\"9cd4172c-0190-4124-a749-671d23e3c6dd\\\", \\\"type\\\": \\\"access\\\"},\\n                    expires_delta=timedelta(seconds=-10),  # Negative = already expired\\n                )\\n\\n                with pytest.raises(HTTPException) as exc_info:\\n                    await get_current_user_from_access_token(token, mock_db)\\n\\n                assert exc_info.value.status_code == 401\\n                # PyJWT library raises InvalidTokenError for expired tokens before our custom check\\n                assert \\\"expired\\\" in exc_info.value.detail.lower() or \\\"invalid token\\\" in exc_info.value.detail.lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_token_without_user_id_raises_401(self):\\n        \\\"\\\"\\\"Token without user ID should raise 401.\\\"\\\"\\\"\\n        from langflow.services.auth.service import AuthService\\n        from langflow.services.auth.utils import get_current_user_from_access_token\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_settings_service = self._create_mock_settings_service(\\\"HS256\\\", tmpdir)\\n            mock_auth_service = AuthService(mock_settings_service)\\n\\n            # Create token without 'sub' claim\\n            token = jwt.encode(\\n                {\\\"type\\\": \\\"access\\\"},\\n                mock_settings_service.auth_settings.SECRET_KEY.get_secret_value(),\\n                algorithm=\\\"HS256\\\",\\n            )\\n\\n            mock_db = AsyncMock()\\n\\n            with patch(\\\"langflow.services.auth.utils.get_auth_service\\\", return_value=mock_auth_service):\\n                with pytest.raises(HTTPException) as exc_info:\\n                    await get_current_user_from_access_token(token, mock_db)\\n\\n                assert exc_info.value.status_code == 401\\n                assert \\\"Invalid token\\\" in exc_info.value.detail or \\\"Expected access token\\\" in exc_info.value.detail\\n\\n    @pytest.mark.asyncio\\n    async def test_token_without_type_raises_401(self):\\n        \\\"\\\"\\\"Token without type should raise 401.\\\"\\\"\\\"\\n        from langflow.services.auth.service import AuthService\\n        from langflow.services.auth.utils import get_current_user_from_access_token\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_settings_service = self._create_mock_settings_service(\\\"HS256\\\", tmpdir)\\n            mock_auth_service = AuthService(mock_settings_service)\\n\\n            # Create token without 'type' claim\\n            token = jwt.encode(\\n                {\\\"sub\\\": \\\"9cd4172c-0190-4124-a749-671d23e3c6dd\\\"},\\n                mock_settings_service.auth_settings.SECRET_KEY.get_secret_value(),\\n                algorithm=\\\"HS256\\\",\\n            )\\n\\n            mock_db = AsyncMock()\\n\\n            with patch(\\\"langflow.services.auth.utils.get_auth_service\\\", return_value=mock_auth_service):\\n                with pytest.raises(HTTPException) as exc_info:\\n                    await get_current_user_from_access_token(token, mock_db)\\n\\n                assert exc_info.value.status_code == 401\\n                assert (\\n                    \\\"invalid\\\" in exc_info.value.detail.lower()\\n                    or \\\"expected access token\\\" in exc_info.value.detail.lower()\\n                )\\n\\n    @pytest.mark.asyncio\\n    async def test_user_not_found_raises_403(self):\\n        \\\"\\\"\\\"Token for non-existent user should raise 403 (InvalidCredentialsError).\\\"\\\"\\\"\\n        from uuid import uuid4\\n\\n        from langflow.services.auth.service import AuthService\\n        from langflow.services.auth.utils import create_token, get_current_user_from_access_token\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_settings_service = self._create_mock_settings_service(\\\"HS256\\\", tmpdir)\\n            mock_auth_service = AuthService(mock_settings_service)\\n            mock_db = AsyncMock()\\n\\n            # Use a valid UUID format\\n            user_id = str(uuid4())\\n\\n            # Create async function that returns None\\n            async def mock_get_user_by_id(*args, **kwargs):  # noqa: ARG001\\n                return None\\n\\n            with (\\n                patch(\\\"langflow.services.auth.utils.get_auth_service\\\", return_value=mock_auth_service),\\n                patch(\\\"langflow.services.auth.service.get_user_by_id\\\", side_effect=mock_get_user_by_id),\\n            ):\\n                token = create_token(\\n                    data={\\\"sub\\\": user_id, \\\"type\\\": \\\"access\\\"},\\n                    expires_delta=timedelta(hours=1),\\n                )\\n\\n                with pytest.raises(HTTPException) as exc_info:\\n                    await get_current_user_from_access_token(token, mock_db)\\n\\n                assert exc_info.value.status_code == 403\\n                assert \\\"User not found\\\" in exc_info.value.detail or \\\"inactive\\\" in exc_info.value.detail.lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_inactive_user_raises_401(self):\\n        \\\"\\\"\\\"Token for inactive user should raise 401.\\\"\\\"\\\"\\n        from uuid import uuid4\\n\\n        from langflow.services.auth.service import AuthService\\n        from langflow.services.auth.utils import create_token, get_current_user_from_access_token\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_settings_service = self._create_mock_settings_service(\\\"HS256\\\", tmpdir)\\n            mock_auth_service = AuthService(mock_settings_service)\\n\\n            # Use a valid UUID format\\n            user_id = str(uuid4())\\n\\n            mock_user = MagicMock()\\n            mock_user.id = user_id\\n            mock_user.is_active = False\\n\\n            mock_db = AsyncMock()\\n\\n            # Create async function that returns mock_user\\n            async def mock_get_user_by_id(*args, **kwargs):  # noqa: ARG001\\n                return mock_user\\n\\n            with (\\n                patch(\\\"langflow.services.auth.utils.get_auth_service\\\", return_value=mock_auth_service),\\n                patch(\\\"langflow.services.auth.service.get_user_by_id\\\", side_effect=mock_get_user_by_id),\\n            ):\\n                token = create_token(\\n                    data={\\\"sub\\\": user_id, \\\"type\\\": \\\"access\\\"},\\n                    expires_delta=timedelta(hours=1),\\n                )\\n\\n                with pytest.raises(HTTPException) as exc_info:\\n                    await get_current_user_from_access_token(token, mock_db)\\n\\n                assert exc_info.value.status_code == 401\\n                assert \\\"inactive\\\" in exc_info.value.detail.lower()\\n\\n\\nclass TestRefreshTokenVerification:\\n    \\\"\\\"\\\"Test refresh token verification with different algorithms.\\\"\\\"\\\"\\n\\n    def _create_mock_settings_service(self, algorithm, tmpdir):\\n        \\\"\\\"\\\"Helper to create mock settings service.\\\"\\\"\\\"\\n        from lfx.services.settings.auth import AuthSettings\\n\\n        settings = AuthSettings(CONFIG_DIR=tmpdir, ALGORITHM=algorithm)\\n\\n        mock_service = MagicMock()\\n        mock_service.auth_settings = settings\\n        return mock_service\\n\\n    @pytest.mark.asyncio\\n    async def test_refresh_token_rs256_success(self):\\n        \\\"\\\"\\\"Valid RS256 refresh token should create new tokens.\\\"\\\"\\\"\\n        from langflow.services.auth.service import AuthService\\n        from langflow.services.auth.utils import create_refresh_token, create_token\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_settings_service = self._create_mock_settings_service(\\\"RS256\\\", tmpdir)\\n            mock_auth_service = AuthService(mock_settings_service)\\n\\n            mock_user = MagicMock()\\n            mock_user.id = \\\"9cd4172c-0190-4124-a749-671d23e3c6dd\\\"\\n            mock_user.is_active = True\\n\\n            mock_db = AsyncMock()\\n\\n            # Create async function that returns mock_user\\n            async def mock_get_user_by_id(*args, **kwargs):  # noqa: ARG001\\n                return mock_user\\n\\n            with (\\n                patch(\\\"langflow.services.auth.utils.get_auth_service\\\", return_value=mock_auth_service),\\n                patch(\\\"langflow.services.auth.service.get_user_by_id\\\", side_effect=mock_get_user_by_id),\\n            ):\\n                # Create refresh token\\n                refresh_token = create_token(\\n                    data={\\\"sub\\\": \\\"9cd4172c-0190-4124-a749-671d23e3c6dd\\\", \\\"type\\\": \\\"refresh\\\"},\\n                    expires_delta=timedelta(days=7),\\n                )\\n\\n                # Use refresh token to get new tokens\\n                new_tokens = await create_refresh_token(refresh_token, mock_db)\\n\\n                assert \\\"access_token\\\" in new_tokens\\n                assert \\\"refresh_token\\\" in new_tokens\\n                assert new_tokens.get(\\\"token_type\\\") == \\\"bearer\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_refresh_token_wrong_type_raises_401(self):\\n        \\\"\\\"\\\"Access token used as refresh token should raise 401.\\\"\\\"\\\"\\n        from langflow.services.auth.service import AuthService\\n        from langflow.services.auth.utils import create_refresh_token, create_token\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_settings_service = self._create_mock_settings_service(\\\"HS256\\\", tmpdir)\\n            mock_auth_service = AuthService(mock_settings_service)\\n            mock_db = AsyncMock()\\n\\n            with patch(\\\"langflow.services.auth.utils.get_auth_service\\\", return_value=mock_auth_service):\\n                # Create access token (not refresh)\\n                access_token = create_token(\\n                    data={\\\"sub\\\": \\\"9cd4172c-0190-4124-a749-671d23e3c6dd\\\", \\\"type\\\": \\\"access\\\"},\\n                    expires_delta=timedelta(hours=1),\\n                )\\n\\n                with pytest.raises(HTTPException) as exc_info:\\n                    await create_refresh_token(access_token, mock_db)\\n\\n                assert exc_info.value.status_code == 401\\n                assert \\\"Invalid refresh token\\\" in exc_info.value.detail\\n\\n\\nclass TestAlgorithmMismatch:\\n    \\\"\\\"\\\"Test scenarios where algorithm configuration changes.\\\"\\\"\\\"\\n\\n    def test_hs256_token_fails_with_rs256_verification(self):\\n        \\\"\\\"\\\"Token created with HS256 should fail RS256 verification.\\\"\\\"\\\"\\n        from lfx.services.settings.auth import AuthSettings\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            # Create token with HS256\\n            hs256_settings = AuthSettings(CONFIG_DIR=tmpdir, ALGORITHM=\\\"HS256\\\")\\n            token = jwt.encode(\\n                {\\\"sub\\\": \\\"9cd4172c-0190-4124-a749-671d23e3c6dd\\\", \\\"type\\\": \\\"access\\\"},\\n                hs256_settings.SECRET_KEY.get_secret_value(),\\n                algorithm=\\\"HS256\\\",\\n            )\\n\\n        with tempfile.TemporaryDirectory() as tmpdir2:\\n            # Try to verify with RS256\\n            rs256_settings = AuthSettings(CONFIG_DIR=tmpdir2, ALGORITHM=\\\"RS256\\\")\\n\\n            with pytest.raises(InvalidTokenError):\\n                jwt.decode(token, rs256_settings.PUBLIC_KEY, algorithms=[\\\"RS256\\\"])\\n\\n    def test_rs256_token_fails_with_hs256_verification(self):\\n        \\\"\\\"\\\"Token created with RS256 should fail HS256 verification.\\\"\\\"\\\"\\n        from lfx.services.settings.auth import AuthSettings\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            # Create token with RS256\\n            rs256_settings = AuthSettings(CONFIG_DIR=tmpdir, ALGORITHM=\\\"RS256\\\")\\n            token = jwt.encode(\\n                {\\\"sub\\\": \\\"9cd4172c-0190-4124-a749-671d23e3c6dd\\\", \\\"type\\\": \\\"access\\\"},\\n                rs256_settings.PRIVATE_KEY.get_secret_value(),\\n                algorithm=\\\"RS256\\\",\\n            )\\n\\n        with tempfile.TemporaryDirectory() as tmpdir2:\\n            # Try to verify with HS256\\n            hs256_settings = AuthSettings(CONFIG_DIR=tmpdir2, ALGORITHM=\\\"HS256\\\")\\n\\n            with pytest.raises(InvalidTokenError):\\n                jwt.decode(\\n                    token,\\n                    hs256_settings.SECRET_KEY.get_secret_value(),\\n                    algorithms=[\\\"HS256\\\"],\\n                )\\n\\n\\nclass TestKeyPersistence:\\n    \\\"\\\"\\\"Test key persistence and file permissions.\\\"\\\"\\\"\\n\\n    def test_secret_key_file_created(self):\\n        \\\"\\\"\\\"Secret key should be saved to file.\\\"\\\"\\\"\\n        from lfx.services.settings.auth import AuthSettings\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            AuthSettings(CONFIG_DIR=tmpdir, ALGORITHM=\\\"HS256\\\")\\n\\n            secret_key_path = Path(tmpdir) / \\\"secret_key\\\"\\n            assert secret_key_path.exists()\\n\\n    def test_rsa_key_files_created(self):\\n        \\\"\\\"\\\"RSA keys should be saved to files.\\\"\\\"\\\"\\n        from lfx.services.settings.auth import AuthSettings\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            AuthSettings(CONFIG_DIR=tmpdir, ALGORITHM=\\\"RS256\\\")\\n\\n            private_key_path = Path(tmpdir) / \\\"private_key.pem\\\"\\n            public_key_path = Path(tmpdir) / \\\"public_key.pem\\\"\\n\\n            assert private_key_path.exists()\\n            assert public_key_path.exists()\\n\\n    def test_keys_reloaded_on_restart(self):\\n        \\\"\\\"\\\"Keys should be consistent across settings reloads.\\\"\\\"\\\"\\n        from lfx.services.settings.auth import AuthSettings\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            # First load\\n            settings1 = AuthSettings(CONFIG_DIR=tmpdir, ALGORITHM=\\\"RS256\\\")\\n            private1 = settings1.PRIVATE_KEY.get_secret_value()\\n            public1 = settings1.PUBLIC_KEY\\n\\n            # Simulate restart\\n            settings2 = AuthSettings(CONFIG_DIR=tmpdir, ALGORITHM=\\\"RS256\\\")\\n            private2 = settings2.PRIVATE_KEY.get_secret_value()\\n            public2 = settings2.PUBLIC_KEY\\n\\n            assert private1 == private2\\n            assert public1 == public2\\n\\n\\nclass TestEdgeCases:\\n    \\\"\\\"\\\"Test edge cases and boundary conditions.\\\"\\\"\\\"\\n\\n    def test_empty_config_dir_string(self):\\n        \\\"\\\"\\\"Empty CONFIG_DIR string should work (in-memory keys).\\\"\\\"\\\"\\n        from lfx.services.settings.auth import AuthSettings\\n\\n        settings = AuthSettings(CONFIG_DIR=\\\"\\\", ALGORITHM=\\\"RS256\\\")\\n        assert settings.PRIVATE_KEY.get_secret_value() is not None\\n        assert settings.PUBLIC_KEY is not None\\n\\n    @pytest.mark.asyncio\\n    async def test_token_with_extra_claims(self):\\n        \\\"\\\"\\\"Token with extra claims should still work.\\\"\\\"\\\"\\n        from langflow.services.auth.service import AuthService\\n        from langflow.services.auth.utils import get_current_user_from_access_token\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            from lfx.services.settings.auth import AuthSettings\\n\\n            settings = AuthSettings(CONFIG_DIR=tmpdir, ALGORITHM=\\\"HS256\\\")\\n\\n            token = jwt.encode(\\n                {\\n                    \\\"sub\\\": \\\"9cd4172c-0190-4124-a749-671d23e3c6dd\\\",\\n                    \\\"type\\\": \\\"access\\\",\\n                    \\\"extra_claim\\\": \\\"some-value\\\",\\n                    \\\"another\\\": 123,\\n                },\\n                settings.SECRET_KEY.get_secret_value(),\\n                algorithm=\\\"HS256\\\",\\n            )\\n\\n            mock_settings_service = MagicMock()\\n            mock_settings_service.auth_settings = settings\\n            mock_auth_service = AuthService(mock_settings_service)\\n\\n            mock_user = MagicMock()\\n            mock_user.id = \\\"9cd4172c-0190-4124-a749-671d23e3c6dd\\\"\\n            mock_user.is_active = True\\n\\n            mock_db = AsyncMock()\\n\\n            # Create async function that returns mock_user\\n            async def mock_get_user_by_id(*args, **kwargs):  # noqa: ARG001\\n                return mock_user\\n\\n            with (\\n                patch(\\\"langflow.services.auth.utils.get_auth_service\\\", return_value=mock_auth_service),\\n                patch(\\\"langflow.services.auth.service.get_user_by_id\\\", side_effect=mock_get_user_by_id),\\n            ):\\n                user = await get_current_user_from_access_token(token, mock_db)\\n                assert user == mock_user\\n\\n    def test_very_long_user_id(self):\\n        \\\"\\\"\\\"Very long user ID should work.\\\"\\\"\\\"\\n        from langflow.services.auth.service import AuthService\\n        from langflow.services.auth.utils import create_token\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            from lfx.services.settings.auth import AuthSettings\\n\\n            settings = AuthSettings(CONFIG_DIR=tmpdir, ALGORITHM=\\\"HS256\\\")\\n\\n            mock_settings_service = MagicMock()\\n            mock_settings_service.auth_settings = settings\\n            mock_auth_service = AuthService(mock_settings_service)\\n\\n            long_user_id = \\\"a\\\" * 1000\\n\\n            with patch(\\\"langflow.services.auth.utils.get_auth_service\\\", return_value=mock_auth_service):\\n                token = create_token(\\n                    data={\\\"sub\\\": long_user_id, \\\"type\\\": \\\"access\\\"},\\n                    expires_delta=timedelta(hours=1),\\n                )\\n\\n                claims = jwt.decode(token, options={\\\"verify_signature\\\": False})\\n                assert claims[\\\"sub\\\"] == long_user_id\\n\\n\\nclass TestJWTKeyHelpers:\\n    \\\"\\\"\\\"Test JWT key helper functions.\\\"\\\"\\\"\\n\\n    def _create_mock_settings_service(self, algorithm, tmpdir):\\n        \\\"\\\"\\\"Helper to create mock settings service.\\\"\\\"\\\"\\n        from lfx.services.settings.auth import AuthSettings\\n\\n        settings = AuthSettings(CONFIG_DIR=tmpdir, ALGORITHM=algorithm)\\n\\n        mock_service = MagicMock()\\n        mock_service.auth_settings = settings\\n        return mock_service\\n\\n    def test_get_jwt_verification_key_hs256_returns_secret_key(self):\\n        \\\"\\\"\\\"HS256 should return secret key for verification.\\\"\\\"\\\"\\n        from langflow.services.auth.utils import get_jwt_verification_key\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_service = self._create_mock_settings_service(\\\"HS256\\\", tmpdir)\\n\\n            key = get_jwt_verification_key(mock_service)\\n\\n            assert key == mock_service.auth_settings.SECRET_KEY.get_secret_value()\\n            assert len(key) >= 32\\n\\n    def test_get_jwt_verification_key_rs256_returns_public_key(self):\\n        \\\"\\\"\\\"RS256 should return public key for verification.\\\"\\\"\\\"\\n        from langflow.services.auth.utils import get_jwt_verification_key\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_service = self._create_mock_settings_service(\\\"RS256\\\", tmpdir)\\n\\n            key = get_jwt_verification_key(mock_service)\\n\\n            assert key == mock_service.auth_settings.PUBLIC_KEY\\n            assert \\\"-----BEGIN PUBLIC KEY-----\\\" in key\\n\\n    def test_get_jwt_verification_key_rs512_returns_public_key(self):\\n        \\\"\\\"\\\"RS512 should return public key for verification.\\\"\\\"\\\"\\n        from langflow.services.auth.utils import get_jwt_verification_key\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_service = self._create_mock_settings_service(\\\"RS512\\\", tmpdir)\\n\\n            key = get_jwt_verification_key(mock_service)\\n\\n            assert key == mock_service.auth_settings.PUBLIC_KEY\\n            assert \\\"-----BEGIN PUBLIC KEY-----\\\" in key\\n\\n    def test_get_jwt_verification_key_missing_public_key_raises_error(self):\\n        \\\"\\\"\\\"Missing public key for asymmetric algorithm should raise JWTKeyError.\\\"\\\"\\\"\\n        from langflow.services.auth.utils import JWTKeyError, get_jwt_verification_key\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_service = self._create_mock_settings_service(\\\"RS256\\\", tmpdir)\\n            object.__setattr__(mock_service.auth_settings, \\\"PUBLIC_KEY\\\", \\\"\\\")\\n\\n            with pytest.raises(JWTKeyError) as exc_info:\\n                get_jwt_verification_key(mock_service)\\n\\n            assert exc_info.value.status_code == 401\\n            assert \\\"Public key not configured\\\" in exc_info.value.detail\\n\\n    def test_get_jwt_verification_key_missing_secret_key_raises_error(self):\\n        \\\"\\\"\\\"Missing secret key for HS256 should raise JWTKeyError.\\\"\\\"\\\"\\n        from langflow.services.auth.utils import JWTKeyError, get_jwt_verification_key\\n        from lfx.services.settings.auth import JWTAlgorithm\\n\\n        mock_auth_settings = MagicMock()\\n        mock_auth_settings.ALGORITHM = JWTAlgorithm.HS256\\n        mock_auth_settings.SECRET_KEY = MagicMock()\\n        mock_auth_settings.SECRET_KEY.get_secret_value.return_value = None\\n\\n        mock_service = MagicMock()\\n        mock_service.auth_settings = mock_auth_settings\\n\\n        with pytest.raises(JWTKeyError) as exc_info:\\n            get_jwt_verification_key(mock_service)\\n\\n        assert exc_info.value.status_code == 401\\n        assert \\\"Secret key not configured\\\" in exc_info.value.detail\\n\\n    def test_get_jwt_signing_key_hs256_returns_secret_key(self):\\n        \\\"\\\"\\\"HS256 should return secret key for signing.\\\"\\\"\\\"\\n        from langflow.services.auth.utils import get_jwt_signing_key\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_service = self._create_mock_settings_service(\\\"HS256\\\", tmpdir)\\n\\n            key = get_jwt_signing_key(mock_service)\\n\\n            assert key == mock_service.auth_settings.SECRET_KEY.get_secret_value()\\n\\n    def test_get_jwt_signing_key_rs256_returns_private_key(self):\\n        \\\"\\\"\\\"RS256 should return private key for signing.\\\"\\\"\\\"\\n        from langflow.services.auth.utils import get_jwt_signing_key\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_service = self._create_mock_settings_service(\\\"RS256\\\", tmpdir)\\n\\n            key = get_jwt_signing_key(mock_service)\\n\\n            assert key == mock_service.auth_settings.PRIVATE_KEY.get_secret_value()\\n            assert \\\"-----BEGIN PRIVATE KEY-----\\\" in key\\n\\n    def test_get_jwt_signing_key_rs512_returns_private_key(self):\\n        \\\"\\\"\\\"RS512 should return private key for signing.\\\"\\\"\\\"\\n        from langflow.services.auth.utils import get_jwt_signing_key\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_service = self._create_mock_settings_service(\\\"RS512\\\", tmpdir)\\n\\n            key = get_jwt_signing_key(mock_service)\\n\\n            assert key == mock_service.auth_settings.PRIVATE_KEY.get_secret_value()\\n            assert \\\"-----BEGIN PRIVATE KEY-----\\\" in key\\n\\n    def test_verification_and_signing_keys_work_together_hs256(self):\\n        \\\"\\\"\\\"Verification and signing keys should work together for HS256.\\\"\\\"\\\"\\n        from langflow.services.auth.utils import get_jwt_signing_key, get_jwt_verification_key\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_service = self._create_mock_settings_service(\\\"HS256\\\", tmpdir)\\n\\n            signing_key = get_jwt_signing_key(mock_service)\\n            verification_key = get_jwt_verification_key(mock_service)\\n\\n            # For symmetric algorithms, both keys are the same\\n            assert signing_key == verification_key\\n\\n            # Sign and verify a token\\n            payload = {\\\"sub\\\": \\\"test-user\\\", \\\"type\\\": \\\"access\\\"}\\n            token = jwt.encode(payload, signing_key, algorithm=\\\"HS256\\\")\\n            decoded = jwt.decode(token, verification_key, algorithms=[\\\"HS256\\\"])\\n\\n            assert decoded[\\\"sub\\\"] == \\\"test-user\\\"\\n\\n    def test_verification_and_signing_keys_work_together_rs256(self):\\n        \\\"\\\"\\\"Verification and signing keys should work together for RS256.\\\"\\\"\\\"\\n        from langflow.services.auth.utils import get_jwt_signing_key, get_jwt_verification_key\\n\\n        with tempfile.TemporaryDirectory() as tmpdir:\\n            mock_service = self._create_mock_settings_service(\\\"RS256\\\", tmpdir)\\n\\n            signing_key = get_jwt_signing_key(mock_service)\\n            verification_key = get_jwt_verification_key(mock_service)\\n\\n            # For asymmetric algorithms, keys are different\\n            assert signing_key != verification_key\\n\\n            # Sign and verify a token\\n            payload = {\\\"sub\\\": \\\"test-user\\\", \\\"type\\\": \\\"access\\\"}\\n            token = jwt.encode(payload, signing_key, algorithm=\\\"RS256\\\")\\n            decoded = jwt.decode(token, verification_key, algorithms=[\\\"RS256\\\"])\\n\\n            assert decoded[\\\"sub\\\"] == \\\"test-user\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_auth_settings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c181039b934238d50efce50beee5071bd633cde227e97285e7baf400bbba1089\",\"content\":\"from pathlib import Path\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom lfx.services.settings.auth import AuthSettings\\nfrom lfx.services.settings.constants import (\\n    DEFAULT_SUPERUSER,\\n    DEFAULT_SUPERUSER_PASSWORD,\\n    SHORT_SECRET_KEY_WARNING,\\n)\\nfrom pydantic import SecretStr, ValidationError\\n\\n\\n@pytest.mark.parametrize(\\\"auto_login\\\", [True, False])\\ndef test_superuser_password_is_secretstr(auto_login, tmp_path: Path):\\n    cfg_dir = tmp_path.as_posix()\\n    settings = AuthSettings(CONFIG_DIR=cfg_dir, AUTO_LOGIN=auto_login)\\n    assert isinstance(settings.SUPERUSER_PASSWORD, SecretStr)\\n\\n\\ndef test_auto_login_true_preserves_configured_credentials_and_scrubs_password(tmp_path: Path):\\n    cfg_dir = tmp_path.as_posix()\\n    settings = AuthSettings(\\n        CONFIG_DIR=cfg_dir,\\n        AUTO_LOGIN=True,\\n        SUPERUSER=\\\"custom\\\",\\n        SUPERUSER_PASSWORD=SecretStr(\\\"_changed\\\"),\\n    )\\n    assert settings.SUPERUSER == \\\"custom\\\"\\n    assert isinstance(settings.SUPERUSER_PASSWORD, SecretStr)\\n    assert settings.SUPERUSER_PASSWORD.get_secret_value() == \\\"_changed\\\"\\n\\n    # reset_credentials preserves the username and scrubs the password even in AUTO_LOGIN mode.\\n    settings.reset_credentials()\\n    assert settings.SUPERUSER == \\\"custom\\\"\\n    assert settings.SUPERUSER_PASSWORD.get_secret_value() == \\\"\\\"\\n\\n\\ndef test_default_superuser_password_is_empty(tmp_path: Path, monkeypatch: pytest.MonkeyPatch):\\n    # conftest load_dotenv() can inject a developer .env (e.g. LANGFLOW_SUPERUSER=admin);\\n    # this test asserts AuthSettings defaults, so clear any process overrides.\\n    monkeypatch.delenv(\\\"LANGFLOW_SUPERUSER\\\", raising=False)\\n    monkeypatch.delenv(\\\"LANGFLOW_SUPERUSER_PASSWORD\\\", raising=False)\\n\\n    cfg_dir = tmp_path.as_posix()\\n    settings = AuthSettings(CONFIG_DIR=cfg_dir)\\n    assert settings.SUPERUSER == DEFAULT_SUPERUSER\\n    assert settings.SUPERUSER_PASSWORD.get_secret_value() == \\\"\\\"\\n    assert DEFAULT_SUPERUSER_PASSWORD.get_secret_value() == \\\"\\\"\\n\\n\\ndef test_short_secret_key_logs_upgrade_warning(tmp_path: Path):\\n    with patch(\\\"lfx.services.settings.auth.logger\\\") as mock_logger:\\n        AuthSettings(CONFIG_DIR=tmp_path.as_posix(), SECRET_KEY=SecretStr(\\\"shortkey123\\\"))\\n\\n    mock_logger.warning.assert_called_once_with(SHORT_SECRET_KEY_WARNING)\\n\\n\\ndef test_generated_secret_key_does_not_log_upgrade_warning(tmp_path: Path):\\n    with patch(\\\"lfx.services.settings.auth.logger\\\") as mock_logger:\\n        settings = AuthSettings(CONFIG_DIR=tmp_path.as_posix())\\n\\n    assert len(settings.SECRET_KEY.get_secret_value()) >= 32\\n    mock_logger.warning.assert_not_called()\\n\\n\\ndef test_auto_login_false_preserves_username_and_scrubs_password_on_reset(tmp_path: Path):\\n    cfg_dir = tmp_path.as_posix()\\n    settings = AuthSettings(\\n        CONFIG_DIR=cfg_dir,\\n        AUTO_LOGIN=False,\\n        SUPERUSER=\\\"admin\\\",\\n        SUPERUSER_PASSWORD=SecretStr(\\\"strongpass\\\"),\\n    )\\n    # Values preserved at init\\n    assert settings.SUPERUSER == \\\"admin\\\"\\n    assert settings.SUPERUSER_PASSWORD.get_secret_value() == \\\"strongpass\\\"\\n\\n    # After reset, username preserved, password scrubbed\\n    settings.reset_credentials()\\n    assert settings.SUPERUSER == \\\"admin\\\"\\n    assert settings.SUPERUSER_PASSWORD.get_secret_value() == \\\"\\\"\\n\\n\\n# ============================================================================\\n# API_KEY_SOURCE Settings Tests\\n# ============================================================================\\n\\n\\nclass TestApiKeySourceSettings:\\n    \\\"\\\"\\\"Tests for API_KEY_SOURCE configuration setting.\\\"\\\"\\\"\\n\\n    def test_api_key_source_default_is_db(self, tmp_path: Path):\\n        \\\"\\\"\\\"Default API_KEY_SOURCE should be 'db' for backward compatibility.\\\"\\\"\\\"\\n        cfg_dir = tmp_path.as_posix()\\n        settings = AuthSettings(CONFIG_DIR=cfg_dir)\\n        assert settings.API_KEY_SOURCE == \\\"db\\\"\\n\\n    def test_api_key_source_accepts_db(self, tmp_path: Path):\\n        \\\"\\\"\\\"API_KEY_SOURCE should accept 'db' value.\\\"\\\"\\\"\\n        cfg_dir = tmp_path.as_posix()\\n        settings = AuthSettings(CONFIG_DIR=cfg_dir, API_KEY_SOURCE=\\\"db\\\")\\n        assert settings.API_KEY_SOURCE == \\\"db\\\"\\n\\n    def test_api_key_source_accepts_env(self, tmp_path: Path):\\n        \\\"\\\"\\\"API_KEY_SOURCE should accept 'env' value.\\\"\\\"\\\"\\n        cfg_dir = tmp_path.as_posix()\\n        settings = AuthSettings(CONFIG_DIR=cfg_dir, API_KEY_SOURCE=\\\"env\\\")\\n        assert settings.API_KEY_SOURCE == \\\"env\\\"\\n\\n    def test_api_key_source_rejects_invalid_value(self, tmp_path: Path):\\n        \\\"\\\"\\\"API_KEY_SOURCE should reject invalid values.\\\"\\\"\\\"\\n        cfg_dir = tmp_path.as_posix()\\n        with pytest.raises(ValidationError) as exc_info:\\n            AuthSettings(CONFIG_DIR=cfg_dir, API_KEY_SOURCE=\\\"invalid\\\")\\n        assert \\\"API_KEY_SOURCE\\\" in str(exc_info.value)\\n\\n    def test_api_key_source_rejects_empty_string(self, tmp_path: Path):\\n        \\\"\\\"\\\"API_KEY_SOURCE should reject empty string.\\\"\\\"\\\"\\n        cfg_dir = tmp_path.as_posix()\\n        with pytest.raises(ValidationError):\\n            AuthSettings(CONFIG_DIR=cfg_dir, API_KEY_SOURCE=\\\"\\\")\\n\\n\\nclass TestApiKeySourceEnvironmentVariables:\\n    \\\"\\\"\\\"Tests for API_KEY_SOURCE loaded from environment variables.\\\"\\\"\\\"\\n\\n    def test_api_key_source_from_env_var(self, tmp_path: Path, monkeypatch):\\n        \\\"\\\"\\\"API_KEY_SOURCE should be loaded from LANGFLOW_API_KEY_SOURCE env var.\\\"\\\"\\\"\\n        cfg_dir = tmp_path.as_posix()\\n        monkeypatch.setenv(\\\"LANGFLOW_API_KEY_SOURCE\\\", \\\"env\\\")\\n        settings = AuthSettings(CONFIG_DIR=cfg_dir)\\n        assert settings.API_KEY_SOURCE == \\\"env\\\"\\n\\n    def test_explicit_value_overrides_env_var(self, tmp_path: Path, monkeypatch):\\n        \\\"\\\"\\\"Explicit parameter should override environment variable.\\\"\\\"\\\"\\n        cfg_dir = tmp_path.as_posix()\\n        monkeypatch.setenv(\\\"LANGFLOW_API_KEY_SOURCE\\\", \\\"env\\\")\\n        settings = AuthSettings(CONFIG_DIR=cfg_dir, API_KEY_SOURCE=\\\"db\\\")\\n        assert settings.API_KEY_SOURCE == \\\"db\\\"\\n\\n    def test_invalid_api_key_source_from_env_var(self, tmp_path: Path, monkeypatch):\\n        \\\"\\\"\\\"Invalid API_KEY_SOURCE from env var should raise ValidationError.\\\"\\\"\\\"\\n        cfg_dir = tmp_path.as_posix()\\n        monkeypatch.setenv(\\\"LANGFLOW_API_KEY_SOURCE\\\", \\\"invalid\\\")\\n        with pytest.raises(ValidationError):\\n            AuthSettings(CONFIG_DIR=cfg_dir)\\n\\n\\nclass TestSsoRedirectUrlSettings:\\n    def test_sso_redirect_url_is_declared_with_description(self, tmp_path: Path):\\n        settings = AuthSettings(CONFIG_DIR=tmp_path.as_posix())\\n\\n        assert settings.SSO_REDIRECT_URL is None\\n        assert AuthSettings.model_fields[\\\"SSO_REDIRECT_URL\\\"].description\\n\\n    def test_sso_redirect_url_loads_relative_path_from_environment(self, tmp_path: Path, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_SSO_REDIRECT_URL\\\", \\\"/api/v1/sso/callback\\\")\\n\\n        settings = AuthSettings(CONFIG_DIR=tmp_path.as_posix())\\n\\n        assert settings.SSO_REDIRECT_URL == \\\"/api/v1/sso/callback\\\"\\n\\n    @pytest.mark.parametrize(\\\"blank_url\\\", [\\\"\\\", \\\"   \\\", \\\"\\\\t\\\\r\\\\n\\\"])\\n    def test_sso_redirect_url_normalizes_blank_values_to_none(self, blank_url: str, tmp_path: Path):\\n        settings = AuthSettings(CONFIG_DIR=tmp_path.as_posix(), SSO_REDIRECT_URL=blank_url)\\n\\n        assert settings.SSO_REDIRECT_URL is None\\n\\n    @pytest.mark.parametrize(\\n        \\\"control_character_url\\\",\\n        [\\n            \\\"/api/v1/sso/\\\\x00callback\\\",\\n            \\\"/api/v1/sso/callback\\\\nnext\\\",\\n            \\\"/api/v1/sso/\\\\x7fcallback\\\",\\n            \\\"\\\\t/api/v1/sso/callback\\\",\\n        ],\\n    )\\n    def test_sso_redirect_url_rejects_control_characters(self, control_character_url: str, tmp_path: Path):\\n        with pytest.raises(ValidationError, match=\\\"control characters\\\"):\\n            AuthSettings(CONFIG_DIR=tmp_path.as_posix(), SSO_REDIRECT_URL=control_character_url)\\n\\n    @pytest.mark.parametrize(\\n        \\\"off_origin_url\\\",\\n        [\\n            \\\"https://attacker.example/sso\\\",\\n            \\\"//attacker.example/sso\\\",\\n            \\\"///attacker.example/sso\\\",\\n            \\\"\\\\\\\\\\\\\\\\attacker.example\\\\\\\\sso\\\",\\n        ],\\n    )\\n    def test_sso_redirect_url_rejects_absolute_off_origin_url(self, off_origin_url: str, tmp_path: Path):\\n        with pytest.raises(ValidationError, match=\\\"SSO_REDIRECT_URL\\\"):\\n            AuthSettings(CONFIG_DIR=tmp_path.as_posix(), SSO_REDIRECT_URL=off_origin_url)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_authz_models.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7d72ba21c4b9d6dc72a471ce8fb0ffc8160a1d53b0528f911864970dd27f20ad\",\"content\":\"\\\"\\\"\\\"Tests for authorization plugin models against a real database.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timedelta, timezone\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.auth import (\\n    AuthzAuditLog,\\n    AuthzEditLock,\\n    AuthzRole,\\n    AuthzRoleAssignment,\\n    AuthzRoleAssignmentGrant,\\n    AuthzShare,\\n    AuthzTeam,\\n    AuthzTeamMember,\\n    CasbinRule,\\n    SharePermissionLevel,\\n    ShareScope,\\n)\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.user.model import User\\nfrom sqlmodel import select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n_TEST_PASSWORD = \\\"hashed\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n\\n@pytest.fixture(name=\\\"authz_db_engine\\\")\\ndef authz_db_engine():\\n    from sqlalchemy.ext.asyncio import create_async_engine\\n\\n    engine = create_async_engine(\\\"sqlite+aiosqlite:///:memory:\\\", echo=False)\\n    yield engine\\n    engine.sync_engine.dispose()\\n\\n\\n@pytest.fixture(name=\\\"authz_async_session\\\")\\nasync def authz_async_session(authz_db_engine):\\n    from sqlmodel import SQLModel\\n\\n    async with authz_db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.create_all)\\n    async with AsyncSession(authz_db_engine, expire_on_commit=False) as session:\\n        yield session\\n    async with authz_db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.drop_all)\\n    await authz_db_engine.dispose()\\n\\n\\n@pytest.mark.anyio\\nasync def test_create_casbin_rule_and_authz_role(authz_async_session: AsyncSession):\\n    user = User(username=\\\"authz_user\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add(user)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n\\n    rule = CasbinRule(ptype=\\\"p\\\", v0=\\\"role:viewer\\\", v1=\\\"*\\\", v2=\\\"flow:*\\\", v3=\\\"read\\\")\\n    role = AuthzRole(name=\\\"viewer\\\", is_system=True, permissions=[\\\"flow:read\\\"], created_by=user.id)\\n    team = AuthzTeam(team_name=\\\"Atlas\\\", adom_name=\\\"AtlasPlanners\\\")\\n\\n    authz_async_session.add(rule)\\n    authz_async_session.add(role)\\n    authz_async_session.add(team)\\n    await authz_async_session.commit()\\n\\n    stored_rule = (await authz_async_session.exec(select(CasbinRule).where(CasbinRule.ptype == \\\"p\\\"))).first()\\n    stored_role = (await authz_async_session.exec(select(AuthzRole).where(AuthzRole.name == \\\"viewer\\\"))).first()\\n    assert stored_rule is not None\\n    assert stored_rule.v3 == \\\"read\\\"\\n    assert stored_role is not None\\n    assert stored_role.permissions == [\\\"flow:read\\\"]\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_role_assignment_persists(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"AuthzRoleAssignment persists with FK references to user and role.\\\"\\\"\\\"\\n    user = User(username=\\\"assignee\\\", password=_TEST_PASSWORD)\\n    assigner = User(username=\\\"assigner\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add_all([user, assigner])\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n    await authz_async_session.refresh(assigner)\\n\\n    role = AuthzRole(name=\\\"editor\\\", permissions=[\\\"flow:write\\\"])\\n    authz_async_session.add(role)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(role)\\n\\n    assignment = AuthzRoleAssignment(\\n        user_id=user.id,\\n        role_id=role.id,\\n        domain_type=\\\"global\\\",\\n        assigned_by=assigner.id,\\n    )\\n    authz_async_session.add(assignment)\\n    await authz_async_session.commit()\\n\\n    stored = (\\n        await authz_async_session.exec(select(AuthzRoleAssignment).where(AuthzRoleAssignment.user_id == user.id))\\n    ).first()\\n    assert stored is not None\\n    assert stored.role_id == role.id\\n    assert stored.assigned_by == assigner.id\\n    assert stored.domain_type == \\\"global\\\"\\n    assert stored.domain_id is None\\n\\n\\n@pytest.mark.anyio\\nasync def test_role_assignment_grants_preserve_independent_manual_and_idp_sources(\\n    authz_async_session: AsyncSession,\\n):\\n    user = User(username=\\\"sourced_assignee\\\", password=_TEST_PASSWORD)\\n    actor = User(username=\\\"sourced_actor\\\", password=_TEST_PASSWORD)\\n    role = AuthzRole(name=\\\"sourced_editor\\\", permissions=[\\\"flow:write\\\"])\\n    authz_async_session.add_all([user, actor, role])\\n    await authz_async_session.commit()\\n\\n    assignment = AuthzRoleAssignment(user_id=user.id, role_id=role.id)\\n    authz_async_session.add(assignment)\\n    await authz_async_session.flush()\\n    authz_async_session.add_all(\\n        [\\n            AuthzRoleAssignmentGrant(\\n                assignment_id=assignment.id,\\n                source_kind=\\\"manual\\\",\\n                administrative_actor=actor.id,\\n            ),\\n            AuthzRoleAssignmentGrant(\\n                assignment_id=assignment.id,\\n                source_kind=\\\"idp\\\",\\n                provider_id=\\\"customer-idp\\\",\\n                external_group=\\\"corp_dev\\\",\\n            ),\\n        ]\\n    )\\n    await authz_async_session.commit()\\n\\n    grants = (\\n        await authz_async_session.exec(\\n            select(AuthzRoleAssignmentGrant).where(AuthzRoleAssignmentGrant.assignment_id == assignment.id)\\n        )\\n    ).all()\\n    assert {(grant.source_kind, grant.provider_id, grant.external_group) for grant in grants} == {\\n        (\\\"manual\\\", None, None),\\n        (\\\"idp\\\", \\\"customer-idp\\\", \\\"corp_dev\\\"),\\n    }\\n\\n\\n@pytest.mark.anyio\\nasync def test_deleting_assignment_removes_its_grants_on_sqlite(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"Revoking an assignment must not leave orphan provenance rows.\\n\\n    SQLite ignores ``ON DELETE CASCADE`` unless ``PRAGMA foreign_keys=ON`` is\\n    issued on every connection, which Langflow never does, so the cascade has\\n    to come from the ORM relationship rather than from the database.\\n    \\\"\\\"\\\"\\n    user = User(username=\\\"cascade_assignee\\\", password=_TEST_PASSWORD)\\n    role = AuthzRole(name=\\\"cascade_role\\\", permissions=[\\\"flow:write\\\"])\\n    authz_async_session.add_all([user, role])\\n    await authz_async_session.commit()\\n\\n    assignment = AuthzRoleAssignment(user_id=user.id, role_id=role.id)\\n    authz_async_session.add(assignment)\\n    await authz_async_session.flush()\\n    assignment_id = assignment.id\\n    authz_async_session.add_all(\\n        [\\n            AuthzRoleAssignmentGrant(assignment_id=assignment_id, source_kind=\\\"manual\\\"),\\n            AuthzRoleAssignmentGrant(\\n                assignment_id=assignment_id,\\n                source_kind=\\\"idp\\\",\\n                provider_id=\\\"cascade-idp\\\",\\n                external_group=\\\"cascade_group\\\",\\n            ),\\n        ]\\n    )\\n    await authz_async_session.commit()\\n\\n    await authz_async_session.delete(assignment)\\n    await authz_async_session.commit()\\n\\n    surviving = (\\n        await authz_async_session.exec(select(AuthzRoleAssignment).where(AuthzRoleAssignment.id == assignment_id))\\n    ).all()\\n    orphans = (\\n        await authz_async_session.exec(\\n            select(AuthzRoleAssignmentGrant).where(AuthzRoleAssignmentGrant.assignment_id == assignment_id)\\n        )\\n    ).all()\\n    assert surviving == []\\n    assert orphans == []\\n\\n\\n@pytest.mark.anyio\\nasync def test_role_assignment_grant_rejects_duplicate_manual_source(authz_async_session: AsyncSession):\\n    from sqlalchemy.exc import IntegrityError\\n\\n    user = User(username=\\\"duplicate_source_user\\\", password=_TEST_PASSWORD)\\n    role = AuthzRole(name=\\\"duplicate_source_role\\\", permissions=[])\\n    authz_async_session.add_all([user, role])\\n    await authz_async_session.commit()\\n    assignment = AuthzRoleAssignment(user_id=user.id, role_id=role.id)\\n    authz_async_session.add(assignment)\\n    await authz_async_session.flush()\\n    authz_async_session.add(AuthzRoleAssignmentGrant(assignment_id=assignment.id, source_kind=\\\"manual\\\"))\\n    await authz_async_session.commit()\\n    authz_async_session.add(AuthzRoleAssignmentGrant(assignment_id=assignment.id, source_kind=\\\"manual\\\"))\\n    with pytest.raises(IntegrityError):\\n        await authz_async_session.commit()\\n    await authz_async_session.rollback()\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_role_assignment_blocks_duplicate_global(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"Two global assignments with the same (user_id, role_id) must conflict.\\n\\n    Regression for PR #13153 review: the original UNIQUE(user_id, role_id,\\n    domain_type, domain_id) constraint did not catch this because NULL != NULL\\n    in SQL. The replacement is a partial unique index keyed on\\n    (user_id, role_id, domain_type) with a WHERE on the global+NULL case.\\n    \\\"\\\"\\\"\\n    from sqlalchemy.exc import IntegrityError\\n\\n    user = User(username=\\\"dupe_assignee\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add(user)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n\\n    role = AuthzRole(name=\\\"dupe_editor\\\", permissions=[\\\"flow:write\\\"])\\n    authz_async_session.add(role)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(role)\\n\\n    authz_async_session.add(AuthzRoleAssignment(user_id=user.id, role_id=role.id, domain_type=\\\"global\\\"))\\n    await authz_async_session.commit()\\n\\n    authz_async_session.add(AuthzRoleAssignment(user_id=user.id, role_id=role.id, domain_type=\\\"global\\\"))\\n    with pytest.raises(IntegrityError) as excinfo:\\n        await authz_async_session.commit()\\n    # Assert the *specific* constraint fires (the partial unique index over\\n    # user_id+role_id+domain_type, WHERE domain_id IS NULL) \u2014 otherwise a\\n    # generic NOT NULL or random regression could mask the missing partial\\n    # index. SQLite reports column names rather than the constraint name; we\\n    # inspect only the failure clause before ``[SQL: ...]`` (which echoes every\\n    # column in the INSERT and would otherwise smuggle ``domain_id`` in).\\n    failure_clause = str(excinfo.value).lower().split(\\\"[sql:\\\")[0]\\n    assert \\\"unique constraint failed\\\" in failure_clause\\n    assert \\\"domain_type\\\" in failure_clause\\n    # Unscoped index does not cover domain_id; its absence distinguishes it\\n    # from the scoped index (which also lists ``domain_id``).\\n    assert \\\"domain_id\\\" not in failure_clause\\n    await authz_async_session.rollback()\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_role_assignment_blocks_duplicate_non_global_with_null_domain_id(\\n    authz_async_session: AsyncSession,\\n):\\n    \\\"\\\"\\\"A row with ``domain_type='org' AND domain_id IS NULL`` must still be uniquely constrained.\\n\\n    Regression for PR #13153 review: the previous ``uq_authz_role_assignment_global``\\n    partial index filtered on ``domain_type = 'global'`` AND ``domain_id IS NULL``,\\n    so duplicates with any other ``domain_type`` value plus NULL ``domain_id`` slipped\\n    past. The widened ``uq_authz_role_assignment_unscoped`` index filters on\\n    ``domain_id IS NULL`` only, covering every ill-formed combination.\\n    \\\"\\\"\\\"\\n    from sqlalchemy.exc import IntegrityError\\n\\n    user = User(username=\\\"org_dupe_assignee\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add(user)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n\\n    role = AuthzRole(name=\\\"org_editor\\\", permissions=[\\\"flow:write\\\"])\\n    authz_async_session.add(role)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(role)\\n\\n    authz_async_session.add(AuthzRoleAssignment(user_id=user.id, role_id=role.id, domain_type=\\\"org\\\"))\\n    await authz_async_session.commit()\\n\\n    authz_async_session.add(AuthzRoleAssignment(user_id=user.id, role_id=role.id, domain_type=\\\"org\\\"))\\n    with pytest.raises(IntegrityError) as excinfo:\\n        await authz_async_session.commit()\\n    failure_clause = str(excinfo.value).lower().split(\\\"[sql:\\\")[0]\\n    assert \\\"unique constraint failed\\\" in failure_clause\\n    assert \\\"domain_type\\\" in failure_clause\\n    # Widened (unscoped) partial index \u2014 domain_id is NOT part of the constraint key.\\n    assert \\\"domain_id\\\" not in failure_clause\\n    await authz_async_session.rollback()\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_role_assignment_blocks_duplicate_scoped(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"Scoped (non-NULL domain_id) duplicates must also conflict via the second partial index.\\\"\\\"\\\"\\n    from uuid import uuid4\\n\\n    from sqlalchemy.exc import IntegrityError\\n\\n    user = User(username=\\\"scoped_assignee\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add(user)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n\\n    role = AuthzRole(name=\\\"scoped_editor\\\", permissions=[\\\"flow:write\\\"])\\n    authz_async_session.add(role)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(role)\\n\\n    workspace_id = uuid4()\\n    authz_async_session.add(\\n        AuthzRoleAssignment(user_id=user.id, role_id=role.id, domain_type=\\\"workspace\\\", domain_id=workspace_id)\\n    )\\n    await authz_async_session.commit()\\n\\n    authz_async_session.add(\\n        AuthzRoleAssignment(user_id=user.id, role_id=role.id, domain_type=\\\"workspace\\\", domain_id=workspace_id)\\n    )\\n    with pytest.raises(IntegrityError) as excinfo:\\n        await authz_async_session.commit()\\n    failure_clause = str(excinfo.value).lower().split(\\\"[sql:\\\")[0]\\n    assert \\\"unique constraint failed\\\" in failure_clause\\n    # The scoped index covers domain_id \u2014 its presence distinguishes it from the unscoped one.\\n    assert \\\"domain_id\\\" in failure_clause\\n    await authz_async_session.rollback()\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_role_assignment_allows_distinct_workspaces(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"Same (user, role) assigned to two different workspaces is legitimate and must persist.\\\"\\\"\\\"\\n    from uuid import uuid4\\n\\n    user = User(username=\\\"multi_workspace\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add(user)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n\\n    role = AuthzRole(name=\\\"multi_editor\\\", permissions=[\\\"flow:write\\\"])\\n    authz_async_session.add(role)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(role)\\n\\n    authz_async_session.add(\\n        AuthzRoleAssignment(user_id=user.id, role_id=role.id, domain_type=\\\"workspace\\\", domain_id=uuid4())\\n    )\\n    authz_async_session.add(\\n        AuthzRoleAssignment(user_id=user.id, role_id=role.id, domain_type=\\\"workspace\\\", domain_id=uuid4())\\n    )\\n    await authz_async_session.commit()\\n\\n    rows = (\\n        await authz_async_session.exec(select(AuthzRoleAssignment).where(AuthzRoleAssignment.user_id == user.id))\\n    ).all()\\n    assert len(rows) == 2\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_team_persists(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"AuthzTeam round-trips through the database with default flags.\\\"\\\"\\\"\\n    team = AuthzTeam(team_name=\\\"Platform\\\", adom_name=\\\"platform-adom\\\", description=\\\"Platform team\\\")\\n    authz_async_session.add(team)\\n    await authz_async_session.commit()\\n\\n    stored = (await authz_async_session.exec(select(AuthzTeam).where(AuthzTeam.adom_name == \\\"platform-adom\\\"))).first()\\n    assert stored is not None\\n    assert stored.team_name == \\\"Platform\\\"\\n    assert stored.is_active is True\\n    assert stored.description == \\\"Platform team\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_team_member_persists(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"AuthzTeamMember persists with FK references to team and user.\\\"\\\"\\\"\\n    user = User(username=\\\"team_member\\\", password=_TEST_PASSWORD)\\n    team = AuthzTeam(team_name=\\\"Ops\\\", adom_name=\\\"ops-adom\\\")\\n    authz_async_session.add_all([user, team])\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n    await authz_async_session.refresh(team)\\n\\n    member = AuthzTeamMember(team_id=team.id, user_id=user.id, source=\\\"sso\\\")\\n    authz_async_session.add(member)\\n    await authz_async_session.commit()\\n\\n    stored = (await authz_async_session.exec(select(AuthzTeamMember).where(AuthzTeamMember.team_id == team.id))).first()\\n    assert stored is not None\\n    assert stored.user_id == user.id\\n    assert stored.source == \\\"sso\\\"\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_share_persists(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"AuthzShare persists with the expected scope and permission level.\\\"\\\"\\\"\\n    user = User(username=\\\"sharer\\\", password=_TEST_PASSWORD)\\n    target = User(username=\\\"share_target\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add_all([user, target])\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n    await authz_async_session.refresh(target)\\n\\n    flow = Flow(name=\\\"shared-flow\\\", data={\\\"nodes\\\": []}, user_id=user.id)\\n    authz_async_session.add(flow)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(flow)\\n\\n    share = AuthzShare(\\n        resource_type=\\\"flow\\\",\\n        resource_id=flow.id,\\n        scope=ShareScope.USER.value,\\n        target_id=target.id,\\n        permission_level=SharePermissionLevel.WRITE.value,\\n        created_by=user.id,\\n    )\\n    authz_async_session.add(share)\\n    await authz_async_session.commit()\\n\\n    stored = (await authz_async_session.exec(select(AuthzShare).where(AuthzShare.resource_id == flow.id))).first()\\n    assert stored is not None\\n    assert stored.scope == ShareScope.USER.value\\n    assert stored.permission_level == SharePermissionLevel.WRITE.value\\n    assert stored.target_id == target.id\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_share_blocks_duplicate_targeted(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"Two USER shares with the same (resource, scope, target_id) must conflict.\\n\\n    Covered by the ``uq_authz_share_targeted`` partial unique index\\n    (WHERE target_id IS NOT NULL).\\n    \\\"\\\"\\\"\\n    from sqlalchemy.exc import IntegrityError\\n\\n    user = User(username=\\\"dupe_sharer\\\", password=_TEST_PASSWORD)\\n    target = User(username=\\\"dupe_target\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add_all([user, target])\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n    await authz_async_session.refresh(target)\\n\\n    flow = Flow(name=\\\"dupe-shared-flow\\\", data={\\\"nodes\\\": []}, user_id=user.id)\\n    authz_async_session.add(flow)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(flow)\\n\\n    authz_async_session.add(\\n        AuthzShare(\\n            resource_type=\\\"flow\\\",\\n            resource_id=flow.id,\\n            scope=ShareScope.USER.value,\\n            target_id=target.id,\\n            permission_level=SharePermissionLevel.READ.value,\\n            created_by=user.id,\\n        )\\n    )\\n    await authz_async_session.commit()\\n\\n    authz_async_session.add(\\n        AuthzShare(\\n            resource_type=\\\"flow\\\",\\n            resource_id=flow.id,\\n            scope=ShareScope.USER.value,\\n            target_id=target.id,\\n            permission_level=SharePermissionLevel.WRITE.value,\\n            created_by=user.id,\\n        )\\n    )\\n    with pytest.raises(IntegrityError) as excinfo:\\n        await authz_async_session.commit()\\n    failure_clause = str(excinfo.value).lower().split(\\\"[sql:\\\")[0]\\n    assert \\\"unique constraint failed\\\" in failure_clause\\n    # targeted index covers target_id; untargeted does not\\n    assert \\\"target_id\\\" in failure_clause\\n    await authz_async_session.rollback()\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_share_blocks_duplicate_untargeted(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"Two PUBLIC shares on the same resource must conflict despite NULL target_id.\\n\\n    Regression for PR #13153 review: the original\\n    UNIQUE(resource_type, resource_id, scope, target_id) constraint did not\\n    catch this because NULL != NULL in SQL. Covered by the\\n    ``uq_authz_share_untargeted`` partial unique index (WHERE target_id IS NULL).\\n    \\\"\\\"\\\"\\n    from sqlalchemy.exc import IntegrityError\\n\\n    user = User(username=\\\"public_sharer\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add(user)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n\\n    flow = Flow(name=\\\"public-flow\\\", data={\\\"nodes\\\": []}, user_id=user.id)\\n    authz_async_session.add(flow)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(flow)\\n\\n    authz_async_session.add(\\n        AuthzShare(\\n            resource_type=\\\"flow\\\",\\n            resource_id=flow.id,\\n            scope=ShareScope.PUBLIC.value,\\n            permission_level=SharePermissionLevel.READ.value,\\n            created_by=user.id,\\n        )\\n    )\\n    await authz_async_session.commit()\\n\\n    authz_async_session.add(\\n        AuthzShare(\\n            resource_type=\\\"flow\\\",\\n            resource_id=flow.id,\\n            scope=ShareScope.PUBLIC.value,\\n            permission_level=SharePermissionLevel.WRITE.value,\\n            created_by=user.id,\\n        )\\n    )\\n    with pytest.raises(IntegrityError) as excinfo:\\n        await authz_async_session.commit()\\n    failure_clause = str(excinfo.value).lower().split(\\\"[sql:\\\")[0]\\n    assert \\\"unique constraint failed\\\" in failure_clause\\n    # The untargeted index covers (resource_type, resource_id, scope) \u2014 no target_id column.\\n    assert \\\"target_id\\\" not in failure_clause\\n    assert \\\"scope\\\" in failure_clause\\n    await authz_async_session.rollback()\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_share_allows_distinct_targets(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"Same (resource, scope) shared with two different users must persist.\\\"\\\"\\\"\\n    user = User(username=\\\"multi_share_owner\\\", password=_TEST_PASSWORD)\\n    alice = User(username=\\\"alice_target\\\", password=_TEST_PASSWORD)\\n    bob = User(username=\\\"bob_target\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add_all([user, alice, bob])\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n    await authz_async_session.refresh(alice)\\n    await authz_async_session.refresh(bob)\\n\\n    flow = Flow(name=\\\"multi-share-flow\\\", data={\\\"nodes\\\": []}, user_id=user.id)\\n    authz_async_session.add(flow)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(flow)\\n\\n    authz_async_session.add(\\n        AuthzShare(\\n            resource_type=\\\"flow\\\",\\n            resource_id=flow.id,\\n            scope=ShareScope.USER.value,\\n            target_id=alice.id,\\n            permission_level=SharePermissionLevel.READ.value,\\n            created_by=user.id,\\n        )\\n    )\\n    authz_async_session.add(\\n        AuthzShare(\\n            resource_type=\\\"flow\\\",\\n            resource_id=flow.id,\\n            scope=ShareScope.USER.value,\\n            target_id=bob.id,\\n            permission_level=SharePermissionLevel.READ.value,\\n            created_by=user.id,\\n        )\\n    )\\n    await authz_async_session.commit()\\n\\n    rows = (await authz_async_session.exec(select(AuthzShare).where(AuthzShare.resource_id == flow.id))).all()\\n    assert len(rows) == 2\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_share_rejects_unknown_scope(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"``scope`` must be one of the documented enum values \u2014 ``ck_authz_share_scope_enum``.\\\"\\\"\\\"\\n    from sqlalchemy.exc import IntegrityError\\n\\n    user = User(username=\\\"invalid_scope_sharer\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add(user)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n\\n    flow = Flow(name=\\\"invalid-scope-flow\\\", data={\\\"nodes\\\": []}, user_id=user.id)\\n    authz_async_session.add(flow)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(flow)\\n\\n    authz_async_session.add(\\n        AuthzShare(\\n            resource_type=\\\"flow\\\",\\n            resource_id=flow.id,\\n            scope=\\\"PRIVATE\\\",  # typo that the lowercase enum doesn't cover\\n            target_id=None,\\n            permission_level=SharePermissionLevel.READ.value,\\n            created_by=user.id,\\n        )\\n    )\\n    with pytest.raises(IntegrityError) as excinfo:\\n        await authz_async_session.commit()\\n    assert \\\"ck_authz_share_scope_enum\\\" in str(excinfo.value).lower()\\n    await authz_async_session.rollback()\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_share_rejects_targeted_with_null_target(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"USER/TEAM scopes require a non-NULL target_id \u2014 ``ck_authz_share_scope_target_consistency``.\\\"\\\"\\\"\\n    from sqlalchemy.exc import IntegrityError\\n\\n    user = User(username=\\\"mismatched_share_sharer\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add(user)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n\\n    flow = Flow(name=\\\"mismatched-share-flow\\\", data={\\\"nodes\\\": []}, user_id=user.id)\\n    authz_async_session.add(flow)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(flow)\\n\\n    authz_async_session.add(\\n        AuthzShare(\\n            resource_type=\\\"flow\\\",\\n            resource_id=flow.id,\\n            scope=ShareScope.USER.value,\\n            target_id=None,  # USER without a target is invalid\\n            permission_level=SharePermissionLevel.READ.value,\\n            created_by=user.id,\\n        )\\n    )\\n    with pytest.raises(IntegrityError) as excinfo:\\n        await authz_async_session.commit()\\n    assert \\\"ck_authz_share_scope_target_consistency\\\" in str(excinfo.value).lower()\\n    await authz_async_session.rollback()\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_share_rejects_untargeted_with_target(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"PRIVATE/PUBLIC scopes forbid target_id \u2014 ``ck_authz_share_scope_target_consistency``.\\\"\\\"\\\"\\n    from sqlalchemy.exc import IntegrityError\\n\\n    user = User(username=\\\"public_with_target_sharer\\\", password=_TEST_PASSWORD)\\n    target = User(username=\\\"public_with_target_recipient\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add_all([user, target])\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n    await authz_async_session.refresh(target)\\n\\n    flow = Flow(name=\\\"public-with-target-flow\\\", data={\\\"nodes\\\": []}, user_id=user.id)\\n    authz_async_session.add(flow)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(flow)\\n\\n    authz_async_session.add(\\n        AuthzShare(\\n            resource_type=\\\"flow\\\",\\n            resource_id=flow.id,\\n            scope=ShareScope.PUBLIC.value,\\n            target_id=target.id,  # PUBLIC with a target is invalid\\n            permission_level=SharePermissionLevel.READ.value,\\n            created_by=user.id,\\n        )\\n    )\\n    with pytest.raises(IntegrityError) as excinfo:\\n        await authz_async_session.commit()\\n    assert \\\"ck_authz_share_scope_target_consistency\\\" in str(excinfo.value).lower()\\n    await authz_async_session.rollback()\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_edit_lock_persists(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"AuthzEditLock persists with an expiry timestamp tied to a flow + user.\\\"\\\"\\\"\\n    user = User(username=\\\"lock_holder\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add(user)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n\\n    flow = Flow(name=\\\"locked-flow\\\", data={\\\"nodes\\\": []}, user_id=user.id)\\n    authz_async_session.add(flow)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(flow)\\n\\n    expires = datetime.now(timezone.utc) + timedelta(minutes=15)\\n    lock = AuthzEditLock(flow_id=flow.id, holder_user_id=user.id, expires_at=expires)\\n    authz_async_session.add(lock)\\n    await authz_async_session.commit()\\n\\n    stored = (await authz_async_session.exec(select(AuthzEditLock).where(AuthzEditLock.flow_id == flow.id))).first()\\n    assert stored is not None\\n    assert stored.holder_user_id == user.id\\n    assert stored.expires_at == expires\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_audit_log_persists(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"AuthzAuditLog round-trips with JSON details and an indexed timestamp.\\\"\\\"\\\"\\n    user = User(username=\\\"audit_subject\\\", password=_TEST_PASSWORD)\\n    authz_async_session.add(user)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(user)\\n\\n    flow = Flow(name=\\\"audited-flow\\\", data={\\\"nodes\\\": []}, user_id=user.id)\\n    authz_async_session.add(flow)\\n    await authz_async_session.commit()\\n    await authz_async_session.refresh(flow)\\n\\n    actor_id = uuid4()\\n    entry = AuthzAuditLog(\\n        user_id=user.id,\\n        actor_type=\\\"api_key\\\",\\n        actor_id=actor_id,\\n        action=\\\"flow:write\\\",\\n        resource_type=\\\"flow\\\",\\n        resource_id=flow.id,\\n        result=\\\"allow\\\",\\n        details={\\\"ip\\\": \\\"127.0.0.1\\\"},\\n    )\\n    authz_async_session.add(entry)\\n    await authz_async_session.commit()\\n\\n    stored = (await authz_async_session.exec(select(AuthzAuditLog).where(AuthzAuditLog.user_id == user.id))).first()\\n    assert stored is not None\\n    assert stored.action == \\\"flow:write\\\"\\n    assert stored.result == \\\"allow\\\"\\n    assert stored.details == {\\\"ip\\\": \\\"127.0.0.1\\\"}\\n    assert stored.actor_type == \\\"api_key\\\"\\n    assert stored.actor_id == actor_id\\n    assert stored.timestamp is not None\\n\\n\\n@pytest.mark.anyio\\nasync def test_authz_audit_log_accepts_skipped_reconciliation(authz_async_session: AsyncSession):\\n    \\\"\\\"\\\"Skipped reconciliation is a first-class, queryable audit outcome.\\\"\\\"\\\"\\n    entry = AuthzAuditLog(\\n        action=\\\"directory_membership:reconcile\\\",\\n        resource_type=\\\"user\\\",\\n        result=\\\"skip\\\",\\n        details={\\\"reason\\\": \\\"overage\\\"},\\n    )\\n    authz_async_session.add(entry)\\n    await authz_async_session.commit()\\n\\n    stored = (await authz_async_session.exec(select(AuthzAuditLog).where(AuthzAuditLog.id == entry.id))).first()\\n    assert stored is not None\\n    assert stored.result == \\\"skip\\\"\\n    assert stored.details == {\\\"reason\\\": \\\"overage\\\"}\\n\\n\\ndef test_authz_audit_actor_identity_has_no_fk_and_composite_timestamp_index():\\n    \\\"\\\"\\\"Credential attribution survives API-key deletion and supports actor history scans.\\\"\\\"\\\"\\n    table = AuthzAuditLog.__table__\\n\\n    assert table.c.actor_id.foreign_keys == set()\\n    assert (\\\"actor_id\\\", \\\"timestamp\\\") in {tuple(column.name for column in index.columns) for index in table.indexes}\\n    assert (\\\"actor_type\\\", \\\"timestamp\\\") in {tuple(column.name for column in index.columns) for index in table.indexes}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_build_component_index.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3a31dec0e79d8ed8b8cc09b0f35e9dcf858b93a3bcbe3baa482bc97388f58567\",\"content\":\"\\\"\\\"\\\"Tests for the build_component_index.py script.\\\"\\\"\\\"\\n\\nimport hashlib\\nfrom pathlib import Path\\nfrom unittest.mock import patch\\n\\nimport orjson\\nimport pytest\\n\\n\\nclass TestBuildComponentIndexScript:\\n    \\\"\\\"\\\"Tests for the build_component_index.py script.\\\"\\\"\\\"\\n\\n    def test_build_script_creates_valid_structure(self):\\n        \\\"\\\"\\\"Test that the build script creates a valid index structure.\\\"\\\"\\\"\\n        import importlib.util\\n        import sys\\n\\n        # Get path to build script\\n        script_path = Path(__file__).parent.parent.parent.parent / \\\"scripts\\\" / \\\"build_component_index.py\\\"\\n\\n        if not script_path.exists():\\n            pytest.skip(\\\"build_component_index.py script not found\\\")\\n\\n        # Load the module\\n        spec = importlib.util.spec_from_file_location(\\\"build_component_index\\\", script_path)\\n        build_module = importlib.util.module_from_spec(spec)\\n        sys.modules[\\\"build_component_index\\\"] = build_module\\n\\n        with patch(\\\"asyncio.run\\\") as mock_run:\\n            # Mock component data\\n            mock_run.return_value = {\\n                \\\"components\\\": {\\n                    \\\"TestCategory\\\": {\\n                        \\\"TestComponent\\\": {\\n                            \\\"display_name\\\": \\\"Test Component\\\",\\n                            \\\"description\\\": \\\"A test component\\\",\\n                            \\\"template\\\": {\\\"code\\\": {\\\"type\\\": \\\"code\\\"}},\\n                        }\\n                    }\\n                }\\n            }\\n\\n            spec.loader.exec_module(build_module)\\n            index = build_module.build_component_index()\\n\\n        assert index is not None\\n        assert \\\"version\\\" in index\\n        assert \\\"entries\\\" in index\\n        assert \\\"sha256\\\" in index\\n        assert isinstance(index[\\\"entries\\\"], list)\\n\\n    def test_build_script_minifies_json(self, tmp_path):\\n        \\\"\\\"\\\"Test that the build script always minifies JSON output.\\\"\\\"\\\"\\n        import importlib.util\\n        import sys\\n\\n        script_path = Path(__file__).parent.parent.parent.parent / \\\"scripts\\\" / \\\"build_component_index.py\\\"\\n\\n        if not script_path.exists():\\n            pytest.skip(\\\"build_component_index.py script not found\\\")\\n\\n        spec = importlib.util.spec_from_file_location(\\\"build_component_index\\\", script_path)\\n        build_module = importlib.util.module_from_spec(spec)\\n        sys.modules[\\\"build_component_index\\\"] = build_module\\n\\n        with (\\n            patch(\\\"asyncio.run\\\") as mock_run,\\n            patch(\\\"importlib.metadata.version\\\", return_value=\\\"1.0.0.test\\\"),\\n        ):\\n            mock_run.return_value = {\\n                \\\"components\\\": {\\n                    \\\"TestCategory\\\": {\\n                        \\\"TestComponent\\\": {\\n                            \\\"display_name\\\": \\\"Test\\\",\\n                            \\\"template\\\": {},\\n                        }\\n                    }\\n                }\\n            }\\n\\n            spec.loader.exec_module(build_module)\\n            index = build_module.build_component_index()\\n\\n            # Write using the build module's logic\\n            json_bytes = orjson.dumps(index, option=orjson.OPT_SORT_KEYS)\\n            test_file = tmp_path / \\\"test_index.json\\\"\\n            test_file.write_text(json_bytes.decode(\\\"utf-8\\\"), encoding=\\\"utf-8\\\")\\n\\n            # Verify it's minified (single line)\\n            content = test_file.read_text()\\n            lines = content.strip().split(\\\"\\\\n\\\")\\n            assert len(lines) == 1, \\\"JSON should be minified to a single line\\\"\\n\\n    def test_build_script_sha256_integrity(self):\\n        \\\"\\\"\\\"Test that SHA256 hash is correctly calculated.\\\"\\\"\\\"\\n        import importlib.util\\n        import sys\\n\\n        script_path = Path(__file__).parent.parent.parent.parent / \\\"scripts\\\" / \\\"build_component_index.py\\\"\\n\\n        if not script_path.exists():\\n            pytest.skip(\\\"build_component_index.py script not found\\\")\\n\\n        spec = importlib.util.spec_from_file_location(\\\"build_component_index\\\", script_path)\\n        build_module = importlib.util.module_from_spec(spec)\\n        sys.modules[\\\"build_component_index\\\"] = build_module\\n\\n        with (\\n            patch(\\\"asyncio.run\\\") as mock_run,\\n            patch(\\\"importlib.metadata.version\\\", return_value=\\\"1.0.0.test\\\"),\\n        ):\\n            mock_run.return_value = {\\\"components\\\": {\\\"TestCategory\\\": {\\\"TestComponent\\\": {\\\"template\\\": {}}}}}\\n\\n            spec.loader.exec_module(build_module)\\n            index = build_module.build_component_index()\\n\\n            # Verify hash\\n            index_without_hash = {\\\"version\\\": index[\\\"version\\\"], \\\"entries\\\": index[\\\"entries\\\"]}\\n            payload = orjson.dumps(index_without_hash, option=orjson.OPT_SORT_KEYS)\\n            expected_hash = hashlib.sha256(payload).hexdigest()\\n\\n            assert index[\\\"sha256\\\"] == expected_hash\\n\\n    def test_build_script_handles_import_errors(self):\\n        \\\"\\\"\\\"Test that build script handles import errors gracefully.\\\"\\\"\\\"\\n        import importlib.util\\n        import sys\\n\\n        script_path = Path(__file__).parent.parent.parent.parent / \\\"scripts\\\" / \\\"build_component_index.py\\\"\\n\\n        if not script_path.exists():\\n            pytest.skip(\\\"build_component_index.py script not found\\\")\\n\\n        spec = importlib.util.spec_from_file_location(\\\"build_component_index\\\", script_path)\\n        build_module = importlib.util.module_from_spec(spec)\\n        sys.modules[\\\"build_component_index\\\"] = build_module\\n\\n        with patch(\\\"asyncio.run\\\", side_effect=ImportError(\\\"Cannot import\\\")):\\n            spec.loader.exec_module(build_module)\\n            index = build_module.build_component_index()\\n\\n            assert index is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_build_error_session_id.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3f10e2b0e05bf9b4facfa0ac5e63ebc102ce8b6e6f0ed80c8a9ef3905ae6d3cf\",\"content\":\"\\\"\\\"\\\"Tests for error event session_id propagation during flow builds.\\n\\nBug: When build_graph_and_get_order() fails (e.g., OPENAI_API_KEY variable\\nnot found on initial load), the ErrorMessage is created without session_id.\\nThe frontend's updateMessage() requires session_id to route the error to\\nthe correct chat cache \u2014 without it, the error is silently dropped and\\nnever appears in the Playground chat.\\n\\nThis only happens on initial load because the error occurs before the graph\\nis built (build_graph_and_get_order fails), so graph.session_id is not\\navailable. When a key is set then removed, the error occurs during vertex\\nbuild (after the graph is built), where graph.session_id IS available.\\n\\\"\\\"\\\"\\n\\nimport uuid\\n\\nfrom lfx.schema.message import ErrorMessage\\n\\n\\nclass TestBuildErrorSessionIdPropagation:\\n    \\\"\\\"\\\"Tests that error events include session_id for frontend chat routing.\\\"\\\"\\\"\\n\\n    def test_should_include_session_id_in_error_event_when_graph_build_fails(\\n        self,\\n    ):\\n        \\\"\\\"\\\"ErrorMessage for graph build failures must include session_id.\\n\\n        GIVEN: A flow build where build_graph_and_get_order() fails\\n               (e.g., OPENAI_API_KEY variable not found on initial load)\\n        WHEN:  ErrorMessage is created for the error event (build.py line 497)\\n        THEN:  The error event data must contain a non-empty session_id\\n               so the frontend can route it to the correct chat cache\\n\\n        This test exercises the EXACT error path from the bug report:\\n        build.py line 494-502 creates ErrorMessage WITHOUT session_id,\\n        causing the frontend to silently drop the error message.\\n        \\\"\\\"\\\"\\n        # Arrange \u2014 simulate the exact scenario from build.py line 494-502\\n        flow_id = uuid.uuid4()\\n        session_id = str(flow_id)  # Default session = flow_id (build.py line 223)\\n        exception = Exception(\\\"OPENAI_API_KEY variable not found.\\\")\\n\\n        # Act \u2014 create ErrorMessage the same way build.py line 497-501 does\\n        # Fix: session_id=inputs.session is now passed\\n        error_message = ErrorMessage(\\n            flow_id=flow_id,\\n            exception=exception,\\n            session_id=session_id,\\n        )\\n        error_data = error_message.data\\n\\n        # Assert \u2014 session_id must be present and non-empty for frontend routing\\n        # The frontend's updateMessage() checks:\\n        #   if (!flowId || !sessionId) { return; }  // silently drops!\\n        assert error_data.get(\\\"session_id\\\"), (\\n            f\\\"ErrorMessage.data missing session_id (got '{error_data.get('session_id')}'). \\\"\\n            f\\\"Without session_id, the frontend's updateMessage() silently drops \\\"\\n            f\\\"the error and it never appears in the Playground chat. \\\"\\n            f\\\"The ErrorMessage at build.py line 497 must include \\\"\\n            f\\\"session_id=inputs.session so the error routes correctly.\\\"\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_build_timer.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"36bbd376f6502653809f3b1f42588562ce094cab65cd3126e1423e53f59dc41c\",\"content\":\"\\\"\\\"\\\"Tests for build timer accuracy with client_request_time.\\\"\\\"\\\"\\n\\nimport time\\n\\nimport pytest\\nfrom lfx.schema.schema import InputValueRequest\\n\\n\\nclass TestClientRequestTimeHandling:\\n    \\\"\\\"\\\"Test suite for client_request_time handling in build operations.\\\"\\\"\\\"\\n\\n    def test_input_value_request_client_request_time_is_optional(self):\\n        \\\"\\\"\\\"Test that client_request_time is optional in InputValueRequest.\\\"\\\"\\\"\\n        # Should work without client_request_time\\n        request = InputValueRequest(input_value=\\\"test\\\")\\n        assert request.client_request_time is None\\n\\n        # Should work with client_request_time\\n        request_with_time = InputValueRequest(input_value=\\\"test\\\", client_request_time=1234567890)\\n        assert request_with_time.client_request_time == 1234567890\\n\\n    def test_input_value_request_client_request_time_is_nullable(self):\\n        \\\"\\\"\\\"Test that client_request_time can be explicitly set to None.\\\"\\\"\\\"\\n        request = InputValueRequest(input_value=\\\"test\\\", client_request_time=None)\\n        assert request.client_request_time is None\\n\\n    def test_input_value_request_with_valid_timestamp(self):\\n        \\\"\\\"\\\"Test InputValueRequest with a valid timestamp in milliseconds.\\\"\\\"\\\"\\n        timestamp = int(time.time() * 1000)\\n        request = InputValueRequest(input_value=\\\"test\\\", client_request_time=timestamp)\\n\\n        assert request.client_request_time == timestamp\\n        assert isinstance(request.client_request_time, int)\\n\\n    def test_duration_calculation_without_client_request_time(self):\\n        \\\"\\\"\\\"Test that duration is calculated using perf_counter when client_request_time is None.\\\"\\\"\\\"\\n        # Simulate the backend logic\\n        start_time = time.perf_counter()\\n        time.sleep(0.1)  # Simulate some work\\n        timedelta = time.perf_counter() - start_time\\n\\n        # Verify duration is around 0.1 seconds (100ms)\\n        assert 0.09 < timedelta < 0.15, f\\\"Expected ~0.1s, got {timedelta}s\\\"\\n\\n    def test_duration_calculation_with_client_request_time(self):\\n        \\\"\\\"\\\"Test that duration is calculated from client timestamp when provided.\\\"\\\"\\\"\\n        # Simulate client timestamp from 200ms ago\\n        client_start_ms = int((time.time() - 0.2) * 1000)\\n        inputs = InputValueRequest(input_value=\\\"test\\\", client_request_time=client_start_ms)\\n\\n        # Simulate backend calculation\\n        if inputs and inputs.client_request_time:\\n            client_start_seconds = inputs.client_request_time / 1000\\n            current_time_seconds = time.time()\\n            timedelta = current_time_seconds - client_start_seconds\\n\\n            # Should be around 200ms\\n            assert 0.15 < timedelta < 0.25, f\\\"Expected ~0.2s, got {timedelta}s\\\"\\n\\n    def test_duration_calculation_fallback_to_perf_counter(self):\\n        \\\"\\\"\\\"Test that when client_request_time is None, fallback to perf_counter works.\\\"\\\"\\\"\\n        inputs = InputValueRequest(input_value=\\\"test\\\", client_request_time=None)\\n        start_time = time.perf_counter()\\n\\n        # Simulate some processing\\n        time.sleep(0.05)\\n\\n        # Simulate backend logic\\n        timedelta = time.perf_counter() - start_time\\n\\n        # Client time is None, so we should not override timedelta\\n        if inputs and inputs.client_request_time:\\n            # This block should NOT execute\\n            pytest.fail(\\\"Should not use client_request_time when it's None\\\")\\n\\n        # Verify we're using perf_counter duration\\n        assert 0.04 < timedelta < 0.1, f\\\"Expected ~0.05s from perf_counter, got {timedelta}s\\\"\\n\\n    def test_client_request_time_includes_network_latency(self):\\n        \\\"\\\"\\\"Test that client_request_time captures full end-to-end duration including latency.\\\"\\\"\\\"\\n        # Client sends request at T0\\n        client_start_ms = int(time.time() * 1000)\\n\\n        # Simulate network latency + processing\\n        time.sleep(0.1)  # 100ms network latency\\n        backend_start = time.perf_counter()\\n        time.sleep(0.05)  # 50ms processing\\n        backend_end = time.perf_counter()\\n\\n        # Backend calculation with perf_counter only\\n        perf_duration = backend_end - backend_start\\n\\n        # Backend calculation with client timestamp\\n        client_duration = time.time() - (client_start_ms / 1000)\\n\\n        # Client duration should include both network and processing\\n        assert client_duration > perf_duration, (\\n            f\\\"Client duration ({client_duration}s) should be greater than perf_counter duration ({perf_duration}s)\\\"\\n        )\\n        assert 0.14 < client_duration < 0.2, f\\\"Expected ~0.15s total, got {client_duration}s\\\"\\n        assert 0.04 < perf_duration < 0.1, f\\\"Expected ~0.05s processing, got {perf_duration}s\\\"\\n\\n\\nclass TestBuildTimerBackwardCompatibility:\\n    \\\"\\\"\\\"Test backward compatibility when client_request_time is not provided.\\\"\\\"\\\"\\n\\n    def test_missing_client_request_time_field(self):\\n        \\\"\\\"\\\"Test that requests without client_request_time field work correctly.\\\"\\\"\\\"\\n        # Old API calls might not include this field at all\\n        request_dict = {\\\"input_value\\\": \\\"test\\\", \\\"session\\\": \\\"session123\\\"}\\n        request = InputValueRequest(**request_dict)\\n\\n        assert request.input_value == \\\"test\\\"\\n        assert request.session == \\\"session123\\\"\\n        assert request.client_request_time is None\\n\\n    def test_empty_inputs_object(self):\\n        \\\"\\\"\\\"Test handling when inputs is None.\\\"\\\"\\\"\\n        inputs = None\\n\\n        # Simulate backend logic\\n        start_time = time.perf_counter()\\n        time.sleep(0.05)\\n        timedelta = time.perf_counter() - start_time\\n\\n        # Should not crash when inputs is None\\n        if inputs and inputs.client_request_time:\\n            pytest.fail(\\\"Should not enter this block when inputs is None\\\")\\n\\n        assert 0.04 < timedelta < 0.1\\n\\n    def test_inputs_without_client_request_time(self):\\n        \\\"\\\"\\\"Test that inputs object without client_request_time uses perf_counter.\\\"\\\"\\\"\\n        inputs = InputValueRequest(input_value=\\\"test\\\")\\n        assert inputs.client_request_time is None\\n\\n        start_time = time.perf_counter()\\n        time.sleep(0.05)\\n        timedelta = time.perf_counter() - start_time\\n\\n        # Should use perf_counter duration\\n        if inputs and inputs.client_request_time:\\n            pytest.fail(\\\"Should not use client_request_time when it's None\\\")\\n\\n        assert 0.04 < timedelta < 0.1\\n\\n\\nclass TestDurationFormatting:\\n    \\\"\\\"\\\"Test duration formatting with different time values.\\\"\\\"\\\"\\n\\n    def test_format_elapsed_time_from_client_timestamp(self):\\n        \\\"\\\"\\\"Test that duration formatting works with client timestamps.\\\"\\\"\\\"\\n        from langflow.api.utils import format_elapsed_time\\n\\n        # Test milliseconds (< 1 second)\\n        duration_ms = 0.5  # 500ms\\n        formatted = format_elapsed_time(duration_ms)\\n        assert \\\"ms\\\" in formatted or \\\"second\\\" in formatted\\n\\n        # Test seconds\\n        duration_s = 2.5\\n        formatted = format_elapsed_time(duration_s)\\n        assert \\\"second\\\" in formatted\\n\\n        # Test minutes\\n        duration_m = 75.0  # 1 minute 15 seconds\\n        formatted = format_elapsed_time(duration_m)\\n        assert formatted  # Should return some formatted string\\n\\n    def test_negative_duration_handling(self):\\n        \\\"\\\"\\\"Test handling of negative durations (clock skew).\\\"\\\"\\\"\\n        # This could happen if client clock is ahead of server clock\\n        client_future_ms = int((time.time() + 10) * 1000)  # 10 seconds in future\\n        inputs = InputValueRequest(input_value=\\\"test\\\", client_request_time=client_future_ms)\\n\\n        if inputs and inputs.client_request_time:\\n            client_start_seconds = inputs.client_request_time / 1000\\n            current_time_seconds = time.time()\\n            timedelta = current_time_seconds - client_start_seconds\\n\\n            # Duration would be negative due to clock skew\\n            assert timedelta < 0, \\\"Should detect clock skew\\\"\\n            # In real implementation, we might want to fallback to perf_counter\\n            # or show a warning, but this test just validates we detect the issue\\n\\n\\nclass TestEdgeCases:\\n    \\\"\\\"\\\"Test edge cases and boundary conditions.\\\"\\\"\\\"\\n\\n    def test_very_large_timestamp(self):\\n        \\\"\\\"\\\"Test handling of very large timestamp values.\\\"\\\"\\\"\\n        # Year 2050 timestamp\\n        large_timestamp = 2524608000000\\n        request = InputValueRequest(input_value=\\\"test\\\", client_request_time=large_timestamp)\\n        assert request.client_request_time == large_timestamp\\n\\n    def test_zero_timestamp(self):\\n        \\\"\\\"\\\"Test handling of zero timestamp (Unix epoch).\\\"\\\"\\\"\\n        request = InputValueRequest(input_value=\\\"test\\\", client_request_time=0)\\n        assert request.client_request_time == 0\\n\\n        # Zero should be treated as a valid timestamp, not as None/False\\n        if request and request.client_request_time is not None:\\n            # This should execute since 0 is a valid timestamp\\n            duration = time.time() - (request.client_request_time / 1000)\\n            assert duration > 0  # Current time should be after epoch\\n\\n    def test_timestamp_precision(self):\\n        \\\"\\\"\\\"Test that millisecond precision is maintained.\\\"\\\"\\\"\\n        timestamp_ms = 1234567890123  # Milliseconds with precision\\n        request = InputValueRequest(input_value=\\\"test\\\", client_request_time=timestamp_ms)\\n\\n        # Convert to seconds and back\\n        timestamp_seconds = request.client_request_time / 1000\\n        back_to_ms = int(timestamp_seconds * 1000)\\n\\n        assert back_to_ms == timestamp_ms, \\\"Millisecond precision should be maintained\\\"\\n\\n    def test_concurrent_requests_different_timestamps(self):\\n        \\\"\\\"\\\"Test that multiple concurrent requests maintain separate timestamps.\\\"\\\"\\\"\\n        ts1 = int(time.time() * 1000)\\n        time.sleep(0.01)  # Small delay\\n        ts2 = int(time.time() * 1000)\\n\\n        request1 = InputValueRequest(input_value=\\\"test1\\\", client_request_time=ts1)\\n        request2 = InputValueRequest(input_value=\\\"test2\\\", client_request_time=ts2)\\n\\n        assert request1.client_request_time < request2.client_request_time\\n        assert request2.client_request_time - request1.client_request_time >= 10  # At least 10ms apart\\n\\n\\nclass TestIntegrationScenarios:\\n    \\\"\\\"\\\"Test real-world integration scenarios.\\\"\\\"\\\"\\n\\n    def test_slow_network_scenario(self):\\n        \\\"\\\"\\\"Test scenario where network latency is significant.\\\"\\\"\\\"\\n        # Client initiates request\\n        client_start_ms = int(time.time() * 1000)\\n\\n        # Simulate slow network (300ms)\\n        time.sleep(0.3)\\n\\n        # Backend processing (50ms)\\n        backend_start = time.perf_counter()\\n        time.sleep(0.05)\\n        backend_duration = time.perf_counter() - backend_start\\n\\n        # Calculate with client timestamp\\n        inputs = InputValueRequest(input_value=\\\"test\\\", client_request_time=client_start_ms)\\n        client_duration = time.time() - (inputs.client_request_time / 1000)\\n\\n        # Client sees total time (350ms), backend sees processing time (50ms)\\n        assert client_duration > 0.3, f\\\"Client duration should include network: {client_duration}s\\\"\\n        assert backend_duration < 0.1, f\\\"Backend duration should be just processing: {backend_duration}s\\\"\\n        assert client_duration > backend_duration * 3, \\\"Client duration should be much larger\\\"\\n\\n    def test_queued_request_scenario(self):\\n        \\\"\\\"\\\"Test scenario where request is queued before processing.\\\"\\\"\\\"\\n        # Client sends request\\n        client_start_ms = int(time.time() * 1000)\\n\\n        # Request sits in queue (200ms)\\n        time.sleep(0.2)\\n\\n        # Processing starts\\n        backend_start = time.perf_counter()\\n        time.sleep(0.1)  # Actual processing (100ms)\\n        backend_duration = time.perf_counter() - backend_start\\n\\n        # With client timestamp, we capture queue time + processing\\n        inputs = InputValueRequest(input_value=\\\"test\\\", client_request_time=client_start_ms)\\n        total_duration = time.time() - (inputs.client_request_time / 1000)\\n\\n        assert total_duration > 0.25, f\\\"Should include queue + processing: {total_duration}s\\\"\\n        assert backend_duration < 0.15, f\\\"Backend only sees processing: {backend_duration}s\\\"\\n\\n    def test_fast_cached_response_scenario(self):\\n        \\\"\\\"\\\"Test scenario where response is very fast (cached).\\\"\\\"\\\"\\n        client_start_ms = int(time.time() * 1000)\\n\\n        # Very fast response (10ms)\\n        time.sleep(0.01)\\n\\n        inputs = InputValueRequest(input_value=\\\"test\\\", client_request_time=client_start_ms)\\n        duration = time.time() - (inputs.client_request_time / 1000)\\n\\n        # Should still work for very fast responses\\n        assert 0.005 < duration < 0.05, f\\\"Should capture fast response: {duration}s\\\"\\n\\n\\n@pytest.mark.asyncio\\nclass TestAsyncBuildOperations:\\n    \\\"\\\"\\\"Test async build operations with client_request_time.\\\"\\\"\\\"\\n\\n    async def test_async_build_with_client_timestamp(self):\\n        \\\"\\\"\\\"Test that async build operations correctly use client_request_time.\\\"\\\"\\\"\\n        client_start_ms = int(time.time() * 1000)\\n        inputs = InputValueRequest(input_value=\\\"test\\\", client_request_time=client_start_ms)\\n\\n        # Simulate async processing\\n        import asyncio\\n\\n        await asyncio.sleep(0.1)\\n\\n        # Calculate duration\\n        if inputs and inputs.client_request_time:\\n            duration = time.time() - (inputs.client_request_time / 1000)\\n            assert 0.09 < duration < 0.15\\n\\n    async def test_async_build_without_client_timestamp(self):\\n        \\\"\\\"\\\"Test that async build operations work without client_request_time.\\\"\\\"\\\"\\n        inputs = InputValueRequest(input_value=\\\"test\\\")\\n\\n        # Simulate async processing\\n        import asyncio\\n\\n        start = time.perf_counter()\\n        await asyncio.sleep(0.1)\\n        duration = time.perf_counter() - start\\n\\n        # Should use perf_counter\\n        if not (inputs and inputs.client_request_time):\\n            assert 0.09 < duration < 0.15\\n\\n\\nclass TestVertexDurationUsesOwnPerfCounter:\\n    \\\"\\\"\\\"Vertex duration must always reflect its own execution time via perf_counter.\\n\\n    client_request_time must NOT override individual vertex timings because that\\n    would make sequential vertices (e.g. Agent \u2192 Chat Output) report the same\\n    cumulative wall-clock time instead of their own execution duration.\\n    \\\"\\\"\\\"\\n\\n    def test_should_use_perf_counter_when_client_request_time_is_set(self):\\n        \\\"\\\"\\\"Even when client_request_time exists, vertex duration must come from perf_counter.\\\"\\\"\\\"\\n        # Arrange \u2014 client sent request 500ms ago\\n        client_start_ms = int((time.time() - 0.5) * 1000)\\n        inputs = InputValueRequest(input_value=\\\"test\\\", client_request_time=client_start_ms)\\n\\n        # Act \u2014 simulate vertex build taking ~50ms\\n        start_time = time.perf_counter()\\n        time.sleep(0.05)\\n        timedelta = time.perf_counter() - start_time\\n        # No client_request_time override \u2014 this is the new behavior\\n\\n        # Assert \u2014 duration reflects only the vertex's own execution, not cumulative wall-clock\\n        assert inputs.client_request_time is not None, \\\"Precondition: client_request_time is set\\\"\\n        assert 0.04 < timedelta < 0.1, f\\\"Expected ~50ms (own execution), got {timedelta}s\\\"\\n\\n    def test_should_not_show_same_duration_for_sequential_vertices(self):\\n        \\\"\\\"\\\"Two sequential vertices must report different durations reflecting their own work.\\\"\\\"\\\"\\n        # Act \u2014 first vertex (slow: ~100ms)\\n        start_1 = time.perf_counter()\\n        time.sleep(0.1)\\n        duration_1 = time.perf_counter() - start_1\\n\\n        # Act \u2014 second vertex (fast: ~20ms)\\n        start_2 = time.perf_counter()\\n        time.sleep(0.02)\\n        duration_2 = time.perf_counter() - start_2\\n\\n        # Assert \u2014 each vertex reports its own execution time\\n        assert 0.08 < duration_1 < 0.15, f\\\"First vertex expected ~100ms, got {duration_1}s\\\"\\n        assert 0.01 < duration_2 < 0.05, f\\\"Second vertex expected ~20ms, got {duration_2}s\\\"\\n        assert duration_1 > duration_2 * 2, \\\"Slow vertex must be significantly longer than fast vertex\\\"\\n\\n    def test_should_measure_only_vertex_execution_not_cumulative_time(self):\\n        \\\"\\\"\\\"Vertex duration must exclude time spent in prior vertices.\\\"\\\"\\\"\\n        # Arrange \u2014 simulate a pipeline: Vertex A (100ms) \u2192 Vertex B (20ms)\\n        pipeline_start = time.time()\\n\\n        # Vertex A\\n        start_a = time.perf_counter()\\n        time.sleep(0.1)\\n        duration_a = time.perf_counter() - start_a\\n\\n        # Vertex B\\n        start_b = time.perf_counter()\\n        time.sleep(0.02)\\n        duration_b = time.perf_counter() - start_b\\n\\n        cumulative = time.time() - pipeline_start\\n\\n        # Assert\\n        assert duration_b < cumulative / 2, (\\n            f\\\"Vertex B ({duration_b}s) must be much less than cumulative ({cumulative}s)\\\"\\n        )\\n        assert duration_b < duration_a, \\\"Fast vertex B must be shorter than slow vertex A\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_bundle_lfx_pin.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c47d547d036c13020cc6d68e7ba179c438b66a24bfdfe3df996e85365b400701\",\"content\":\"\\\"\\\"\\\"Tests for ``scripts/ci/sync_bundle_lfx_pin.py``.\\n\\nThe ``make patch`` target calls this script to keep every ``src/bundles/*``\\npackage's ``lfx`` runtime-dependency floor in step with the Langflow/LFX\\n``major.minor`` line. These tests exercise the real script module so a\\nregression in the floor format or the dependency regex is caught without\\nrunning ``make``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib.util\\nimport json\\nimport sys\\nfrom pathlib import Path\\n\\nimport pytest\\n\\ntry:\\n    import tomllib\\nexcept ModuleNotFoundError:  # Python 3.10: tomllib is stdlib only on 3.11+\\n    import tomli as tomllib\\n\\nREPO_ROOT = Path(__file__).resolve().parents[4]\\n_SCRIPT = REPO_ROOT / \\\"scripts\\\" / \\\"ci\\\" / \\\"sync_bundle_lfx_pin.py\\\"\\n\\n\\ndef _load_module():\\n    spec = importlib.util.spec_from_file_location(\\\"sync_bundle_lfx_pin\\\", _SCRIPT)\\n    module = importlib.util.module_from_spec(spec)\\n    sys.modules[\\\"sync_bundle_lfx_pin\\\"] = module\\n    spec.loader.exec_module(module)\\n    return module\\n\\n\\nmod = _load_module()\\n\\n\\n# ---------------------------------------------------------------------------\\n# lfx_floor_spec\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLfxFloorSpec:\\n    # The .dev0 floor is load-bearing: nightlies are canonical X.Y.0.devN\\n    # pre-releases, which PEP 440 sorts BELOW X.Y.0, so a plain >=X.Y.0\\n    # floor makes the branch's own nightly lfx unresolvable.\\n    @pytest.mark.parametrize(\\n        (\\\"version\\\", \\\"expected\\\"),\\n        [\\n            (\\\"1.10.0\\\", \\\"lfx>=1.10.0.dev0,<2.0.0\\\"),\\n            (\\\"1.10.3\\\", \\\"lfx>=1.10.0.dev0,<2.0.0\\\"),  # patch within a minor -> same floor\\n            (\\\"1.11.0\\\", \\\"lfx>=1.11.0.dev0,<2.0.0\\\"),\\n            (\\\"2.0.0\\\", \\\"lfx>=2.0.0.dev0,<3.0.0\\\"),\\n            (\\\"v1.10.0\\\", \\\"lfx>=1.10.0.dev0,<2.0.0\\\"),  # leading v tolerated\\n            (\\\"10.4.2\\\", \\\"lfx>=10.4.0.dev0,<11.0.0\\\"),  # multi-digit major\\n        ],\\n    )\\n    def test_floor(self, version, expected):\\n        assert mod.lfx_floor_spec(version) == expected\\n\\n    @pytest.mark.parametrize(\\\"bad\\\", [\\\"\\\", \\\"1.10\\\", \\\"abc\\\", \\\"1\\\", \\\"x.y.z\\\"])\\n    def test_rejects_unparseable(self, bad):\\n        with pytest.raises(ValueError, match=\\\"Unparseable version\\\"):\\n            mod.lfx_floor_spec(bad)\\n\\n\\n# ---------------------------------------------------------------------------\\n# rewrite_lfx_dep\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestRewriteLfxDep:\\n    FLOOR = \\\"lfx>=1.10.0.dev0,<2.0.0\\\"\\n\\n    def test_rewrites_bare_floor(self):\\n        assert mod.rewrite_lfx_dep('    \\\"lfx>=0.5.0\\\",', self.FLOOR) == f'    \\\"{self.FLOOR}\\\",'\\n\\n    def test_rewrites_existing_range(self):\\n        assert mod.rewrite_lfx_dep('    \\\"lfx>=1.9.0,<2.0.0\\\",', self.FLOOR) == f'    \\\"{self.FLOOR}\\\",'\\n\\n    def test_rewrites_compatible_release_and_equality(self):\\n        assert mod.rewrite_lfx_dep('\\\"lfx~=0.5.0\\\"', self.FLOOR) == f'\\\"{self.FLOOR}\\\"'\\n        assert mod.rewrite_lfx_dep('\\\"lfx==0.5.0\\\"', self.FLOOR) == f'\\\"{self.FLOOR}\\\"'\\n\\n    def test_idempotent(self):\\n        once = mod.rewrite_lfx_dep('\\\"lfx>=0.5.0\\\"', self.FLOOR)\\n        assert mod.rewrite_lfx_dep(once, self.FLOOR) == once\\n\\n    def test_leaves_self_reference_untouched(self):\\n        # docling's optional-deps self-ref must NOT be treated as the lfx dep.\\n        for self_ref in ('\\\"lfx-docling[local]\\\"', '\\\"lfx-docling[local,chunking,image-description]\\\"'):\\n            assert mod.rewrite_lfx_dep(self_ref, self.FLOOR) == self_ref\\n\\n    def test_leaves_nightly_form_untouched(self):\\n        # Legacy form from the retired nightly bundle-rename track (see\\n        # src/bundles/NIGHTLY.md); sync must not clobber it if encountered.\\n        assert mod.rewrite_lfx_dep('\\\"lfx-nightly==1.10.0.dev38\\\"', self.FLOOR) == '\\\"lfx-nightly==1.10.0.dev38\\\"'\\n\\n    def test_only_rewrites_runtime_dep_in_full_block(self):\\n        content = (\\n            \\\"dependencies = [\\\\n\\\"\\n            '    \\\"lfx>=0.5.0\\\",\\\\n'\\n            '    \\\"langchain-community>=0.4.1,<1.0.0\\\",\\\\n'\\n            \\\"]\\\\n\\\"\\n            \\\"[project.optional-dependencies]\\\\n\\\"\\n            \\\"all = [\\\\n\\\"\\n            '    \\\"lfx-docling[local,chunking,image-description]\\\",\\\\n'\\n            \\\"]\\\\n\\\"\\n        )\\n        out = mod.rewrite_lfx_dep(content, self.FLOOR)\\n        assert f'    \\\"{self.FLOOR}\\\",' in out\\n        assert '    \\\"langchain-community>=0.4.1,<1.0.0\\\",' in out  # untouched\\n        assert '    \\\"lfx-docling[local,chunking,image-description]\\\",' in out  # untouched\\n\\n\\n# ---------------------------------------------------------------------------\\n# sync_bundles (filesystem-level, on a temp tree)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestSyncBundles:\\n    def _make_bundle(self, bundles_dir: Path, name: str, lfx_line: str) -> Path:\\n        d = bundles_dir / name\\n        d.mkdir(parents=True)\\n        pyproject = d / \\\"pyproject.toml\\\"\\n        content = f'[project]\\\\nname = \\\"lfx-{name}\\\"\\\\ndependencies = [\\\\n    \\\"{lfx_line}\\\",\\\\n]\\\\n'\\n        pyproject.write_text(content, encoding=\\\"utf-8\\\")\\n        return pyproject\\n\\n    def test_sync_updates_and_reports(self, tmp_path):\\n        bundles = tmp_path / \\\"bundles\\\"\\n        self._make_bundle(bundles, \\\"arxiv\\\", \\\"lfx>=0.5.0\\\")\\n        self._make_bundle(bundles, \\\"ibm\\\", \\\"lfx>=1.10.0.dev0,<2.0.0\\\")  # already correct\\n\\n        results = dict(mod.sync_bundles(\\\"1.10.0\\\", bundles))\\n        assert results == {\\\"arxiv\\\": True, \\\"ibm\\\": False}  # arxiv changed, ibm no-op\\n        assert '\\\"lfx>=1.10.0.dev0,<2.0.0\\\"' in (bundles / \\\"arxiv\\\" / \\\"pyproject.toml\\\").read_text()\\n\\n    def test_sync_idempotent(self, tmp_path):\\n        bundles = tmp_path / \\\"bundles\\\"\\n        self._make_bundle(bundles, \\\"arxiv\\\", \\\"lfx>=0.5.0\\\")\\n        mod.sync_bundles(\\\"1.10.0\\\", bundles)\\n        second = dict(mod.sync_bundles(\\\"1.10.0\\\", bundles))\\n        assert second == {\\\"arxiv\\\": False}\\n\\n\\ndef test_bundle_manifests_match_distribution_versions():\\n    \\\"\\\"\\\"Keep published extension identity aligned with wheel metadata.\\\"\\\"\\\"\\n    for pyproject in sorted((REPO_ROOT / \\\"src\\\" / \\\"bundles\\\").glob(\\\"*/pyproject.toml\\\")):\\n        project_version = tomllib.loads(pyproject.read_text(encoding=\\\"utf-8\\\"))[\\\"project\\\"][\\\"version\\\"]\\n        manifests = sorted(pyproject.parent.glob(\\\"src/*/extension.json\\\"))\\n        if pyproject.parent.name != \\\"lfx-bundles\\\":\\n            assert manifests, f\\\"{pyproject.relative_to(REPO_ROOT)} is missing extension.json\\\"\\n        for manifest in manifests:\\n            manifest_version = json.loads(manifest.read_text(encoding=\\\"utf-8\\\"))[\\\"version\\\"]\\n            assert manifest_version == project_version, (\\n                f\\\"{manifest.relative_to(REPO_ROOT)} has version {manifest_version}, \\\"\\n                f\\\"but {pyproject.relative_to(REPO_ROOT)} has {project_version}\\\"\\n            )\\n\\n\\n# ---------------------------------------------------------------------------\\n# ratchet_spec -- sync must never WIDEN an existing pin\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestRatchetSpec:\\n    GEN_1_11 = \\\"lfx>=1.11.0.dev0,<2.0.0\\\"\\n    GEN_1_12 = \\\"lfx>=1.12.0.dev0,<2.0.0\\\"\\n\\n    def test_keeps_hand_tightened_maintenance_pin(self):\\n        # The regression this guards: `make patch v=1.11.7` on release-1.11.x\\n        # regenerating <2.0.0 would let a 1.11-line bundle satisfy a 1.12\\n        # install. The 1.11 bundle numbers sort higher, so the resolver would\\n        # prefer them and langflow 1.12 would silently get 1.11-line code.\\n        assert mod.ratchet_spec(\\\"lfx>=1.11.6,<1.12\\\", self.GEN_1_11) == \\\"lfx>=1.11.6,<1.12\\\"\\n\\n    def test_generated_pin_is_a_noop_on_itself(self):\\n        assert mod.ratchet_spec(self.GEN_1_12, self.GEN_1_12) == self.GEN_1_12\\n\\n    def test_stale_floor_is_still_raised(self):\\n        assert mod.ratchet_spec(\\\"lfx>=1.9.0,<2.0.0\\\", self.GEN_1_11) == self.GEN_1_11\\n\\n    def test_line_move_supersedes_rather_than_emptying(self):\\n        # Intersecting here would yield \\\">=1.12.0.dev0,<1.12\\\" -- unsatisfiable.\\n        assert mod.ratchet_spec(\\\"lfx>=1.11.6,<1.12\\\", self.GEN_1_12) == self.GEN_1_12\\n\\n    def test_cap_padding(self):\\n        # \\\"<1.12\\\" and \\\"<1.12.0\\\" are the same bound, so both are line moves.\\n        assert mod.ratchet_spec(\\\"lfx>=1.11.6,<1.12.0\\\", self.GEN_1_12) == self.GEN_1_12\\n\\n    @pytest.mark.parametrize(\\\"legacy\\\", [\\\"lfx>=0.5.0\\\", \\\"lfx~=0.5.0\\\", \\\"lfx==0.5.0\\\"])\\n    def test_legacy_forms_normalise_wholesale(self, legacy):\\n        assert mod.ratchet_spec(legacy, self.GEN_1_11) == self.GEN_1_11\\n\\n\\ndef test_sync_preserves_a_tightened_maintenance_pin(tmp_path):\\n    \\\"\\\"\\\"End-to-end: `make patch v=1.11.7` on a 1.11.x-shaped tree is a no-op.\\\"\\\"\\\"\\n    bundles = tmp_path / \\\"bundles\\\"\\n    (bundles / \\\"amazon\\\").mkdir(parents=True)\\n    pyproject = bundles / \\\"amazon\\\" / \\\"pyproject.toml\\\"\\n    pyproject.write_text(\\n        '[project]\\\\nname = \\\"lfx-amazon\\\"\\\\ndependencies = [\\\\n    \\\"lfx>=1.11.6,<1.12\\\",\\\\n]\\\\n',\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    assert dict(mod.sync_bundles(\\\"1.11.7\\\", bundles)) == {\\\"amazon\\\": False}\\n    assert '\\\"lfx>=1.11.6,<1.12\\\"' in pyproject.read_text(encoding=\\\"utf-8\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_chat_endpoint.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"43e4be174f5d509818b0d4cf99ca14e68b17783011c8118ba72370e4eddab262\",\"content\":\"import asyncio\\nimport contextlib\\nimport json\\nimport uuid\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock\\nfrom uuid import UUID\\n\\nimport pytest\\nfrom httpx import codes\\nfrom langflow.services.database.models.flow import FlowUpdate\\nfrom langflow.services.deps import get_settings_service\\nfrom langflow.services.job_queue.service import JobQueueService\\nfrom lfx.log.logger import logger\\nfrom lfx.memory import aget_messages\\n\\nfrom tests.unit.build_utils import build_flow, consume_and_assert_stream, create_flow, get_build_events\\n\\n\\n@pytest.fixture(autouse=True)\\ndef allow_custom_components_by_default(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS\\\", \\\"true\\\")\\n\\n\\n@pytest.mark.benchmark\\nasync def test_build_flow(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Test the build flow endpoint with the new two-step process.\\\"\\\"\\\"\\n    # First create the flow\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Start the build and get job_id\\n    build_response = await build_flow(client, flow_id, logged_in_headers)\\n    job_id = build_response[\\\"job_id\\\"]\\n    assert job_id is not None\\n\\n    # Get the events stream\\n    events_response = await get_build_events(client, job_id, logged_in_headers)\\n    assert events_response.status_code == codes.OK\\n\\n    # Consume and verify the events\\n    await consume_and_assert_stream(events_response, job_id)\\n\\n\\n@pytest.mark.benchmark\\nasync def test_build_flow_from_request_data(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Test building a flow from request data.\\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    response = await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)\\n    flow_data = response.json()\\n\\n    # Start the build and get job_id\\n    build_response = await build_flow(client, flow_id, logged_in_headers, json={\\\"data\\\": flow_data[\\\"data\\\"]})\\n    job_id = build_response[\\\"job_id\\\"]\\n\\n    # Get the events stream\\n    events_response = await get_build_events(client, job_id, logged_in_headers)\\n    assert events_response.status_code == codes.OK\\n\\n    # Consume and verify the events\\n    await consume_and_assert_stream(events_response, job_id)\\n    await check_messages(flow_id)\\n\\n\\nasync def test_build_flow_validates_request_data_instead_of_stale_db_flow(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"When request data is provided, preflight validation should use it instead of the saved flow.\\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    response = await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)\\n    flow_data = response.json()\\n    request_data = json.loads(json.dumps(flow_data[\\\"data\\\"]))\\n    request_data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"display_name\\\"] = \\\"Updated Request Flow\\\"\\n    saved_flow_validation_message = \\\"saved flow should not be validated when request data is provided\\\"\\n\\n    def fail_if_saved_flow_is_validated(target):\\n        if target == flow_data[\\\"data\\\"]:\\n            raise ValueError(saved_flow_validation_message)\\n\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.chat.validate_flow_for_current_settings\\\",\\n        fail_if_saved_flow_is_validated,\\n    )\\n\\n    response = await client.post(\\n        f\\\"api/v1/build/{flow_id}/flow\\\",\\n        json={\\\"data\\\": request_data},\\n        headers=logged_in_headers,\\n    )\\n\\n    assert response.status_code == codes.OK\\n    assert \\\"job_id\\\" in response.json()\\n\\n\\nasync def test_build_flow_enforces_current_catalog_policy_and_recovers_when_cleared(\\n    client, json_memory_chatbot_no_llm, logged_in_headers\\n):\\n    from lfx.services.deps import get_catalog_policy_service\\n\\n    catalog_policy_service = get_catalog_policy_service()\\n    await catalog_policy_service.replace_blocked_component_keys([], actor_user_id=None)\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    await catalog_policy_service.replace_blocked_component_keys([\\\"ChatInput\\\"], actor_user_id=None)\\n\\n    blocked_response = await client.post(\\n        f\\\"api/v1/build/{flow_id}/flow\\\",\\n        json={},\\n        headers=logged_in_headers,\\n    )\\n    await catalog_policy_service.replace_blocked_component_keys([], actor_user_id=None)\\n    allowed_response = await client.post(\\n        f\\\"api/v1/build/{flow_id}/flow\\\",\\n        json={},\\n        headers=logged_in_headers,\\n    )\\n\\n    assert blocked_response.status_code == codes.BAD_REQUEST\\n    assert blocked_response.json()[\\\"detail\\\"].endswith(\\\"ChatInput\\\")\\n    assert allowed_response.status_code == codes.OK\\n    assert \\\"job_id\\\" in allowed_response.json()\\n\\n\\nasync def test_build_flow_with_frozen_path(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Test building a flow with a frozen path.\\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    response = await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)\\n    flow_data = response.json()\\n    flow_data[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"frozen\\\"] = True\\n\\n    # Update the flow with frozen path\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json=FlowUpdate(name=\\\"Flow\\\", description=\\\"description\\\", data=flow_data[\\\"data\\\"]).model_dump(),\\n        headers=logged_in_headers,\\n    )\\n    response.raise_for_status()\\n\\n    # Start the build and get job_id\\n    build_response = await build_flow(client, flow_id, logged_in_headers)\\n    job_id = build_response[\\\"job_id\\\"]\\n\\n    # Get the events stream\\n    events_response = await get_build_events(client, job_id, logged_in_headers)\\n    assert events_response.status_code == codes.OK\\n\\n    # Consume and verify the events\\n    await consume_and_assert_stream(events_response, job_id)\\n    await check_messages(flow_id)\\n\\n\\nasync def check_messages(flow_id):\\n    if isinstance(flow_id, str):\\n        flow_id = UUID(flow_id)\\n    messages = await aget_messages(flow_id=flow_id, order=\\\"ASC\\\")\\n    flow_id_str = str(flow_id)\\n    assert len(messages) == 2\\n    assert messages[0].session_id == flow_id_str\\n    assert messages[0].sender == \\\"User\\\"\\n    assert messages[0].sender_name == \\\"User\\\"\\n    assert messages[0].text == \\\"\\\"\\n    assert messages[1].session_id == flow_id_str\\n    assert messages[1].sender == \\\"Machine\\\"\\n    assert messages[1].sender_name == \\\"AI\\\"\\n\\n\\n@pytest.mark.benchmark\\nasync def test_build_flow_invalid_job_id(client, logged_in_headers):\\n    \\\"\\\"\\\"Test getting events for an invalid job ID.\\\"\\\"\\\"\\n    invalid_job_id = str(uuid.uuid4())\\n    response = await get_build_events(client, invalid_job_id, logged_in_headers)\\n    assert response.status_code == codes.NOT_FOUND\\n    assert \\\"Job not found\\\" in response.json()[\\\"detail\\\"]\\n\\n\\n@pytest.mark.benchmark\\nasync def test_build_flow_invalid_flow_id(client, logged_in_headers):\\n    \\\"\\\"\\\"Test starting a build with an invalid flow ID.\\\"\\\"\\\"\\n    invalid_flow_id = uuid.uuid4()\\n    response = await client.post(f\\\"api/v1/build/{invalid_flow_id}/flow\\\", json={}, headers=logged_in_headers)\\n    assert response.status_code == codes.NOT_FOUND\\n\\n\\n@pytest.mark.benchmark\\nasync def test_build_flow_start_only(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Test only the build flow start endpoint.\\\"\\\"\\\"\\n    # First create the flow\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Start the build and get job_id\\n    build_response = await build_flow(client, flow_id, logged_in_headers)\\n\\n    # Assert response structure\\n    assert \\\"job_id\\\" in build_response\\n    assert isinstance(build_response[\\\"job_id\\\"], str)\\n    # Verify it's a valid UUID\\n    assert uuid.UUID(build_response[\\\"job_id\\\"])\\n\\n\\n@pytest.mark.benchmark\\nasync def test_build_flow_start_with_inputs(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Test the build flow start endpoint with input data.\\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Start build with some input data\\n    test_inputs = {\\\"inputs\\\": {\\\"session\\\": \\\"test_session\\\", \\\"input_value\\\": \\\"test message\\\"}}\\n\\n    build_response = await build_flow(client, flow_id, logged_in_headers, json=test_inputs)\\n\\n    assert \\\"job_id\\\" in build_response\\n    assert isinstance(build_response[\\\"job_id\\\"], str)\\n    assert uuid.UUID(build_response[\\\"job_id\\\"])\\n\\n\\n@pytest.mark.benchmark\\nasync def test_build_flow_polling(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Test the build flow endpoint with polling (non-streaming).\\\"\\\"\\\"\\n    # First create the flow\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Start the build and get job_id\\n    build_response = await build_flow(client, flow_id, logged_in_headers)\\n    assert \\\"job_id\\\" in build_response, f\\\"Expected job_id in build_response, got {build_response}\\\"\\n    job_id = build_response[\\\"job_id\\\"]\\n    assert job_id is not None\\n\\n    # Create a response object that mimics a streaming response but uses polling\\n    class PollingResponse:\\n        def __init__(self, client, job_id, headers):\\n            self.client = client\\n            self.job_id = job_id\\n            self.headers = headers\\n            self.status_code = codes.OK\\n            self.max_total_events = 50  # Limit to prevent infinite loops\\n            self.max_empty_polls = 10  # Maximum number of empty polls before giving up\\n            self.poll_timeout = 3.0  # Timeout for each polling request\\n            self._closed = False\\n\\n        async def aiter_lines(self):\\n            if self._closed:\\n                return\\n\\n            try:\\n                empty_polls = 0\\n                total_events = 0\\n                end_event_found = False\\n\\n                while (\\n                    empty_polls < self.max_empty_polls\\n                    and total_events < self.max_total_events\\n                    and not end_event_found\\n                    and not self._closed\\n                ):\\n                    # Add Accept header for NDJSON\\n                    headers = {**self.headers, \\\"Accept\\\": \\\"application/x-ndjson\\\"}\\n\\n                    try:\\n                        # Set a timeout for the request\\n                        response = await asyncio.wait_for(\\n                            self.client.get(\\n                                f\\\"api/v1/build/{self.job_id}/events?event_delivery=polling\\\",\\n                                headers=headers,\\n                            ),\\n                            timeout=self.poll_timeout,\\n                        )\\n\\n                        if response.status_code != codes.OK:\\n                            break\\n\\n                        # Get the NDJSON response as text\\n                        text = response.text\\n\\n                        # Skip if response is empty\\n                        if not text.strip():\\n                            empty_polls += 1\\n                            await asyncio.sleep(0.1)\\n                            continue\\n\\n                        # Reset empty polls counter since we got data\\n                        empty_polls = 0\\n\\n                        # Process each line as an individual JSON object\\n                        line_count = 0\\n                        for line in text.splitlines():\\n                            if not line.strip():\\n                                continue\\n\\n                            line_count += 1\\n                            total_events += 1\\n\\n                            # Check for end event with multiple possible formats\\n                            if '\\\"event\\\":\\\"end\\\"' in line or '\\\"event\\\": \\\"end\\\"' in line:\\n                                end_event_found = True\\n\\n                            # Validate it's proper JSON before yielding\\n                            try:\\n                                json.loads(line)  # Test parse to ensure it's valid JSON\\n                                yield line\\n                            except json.JSONDecodeError as e:\\n                                logger.debug(f\\\"WARNING: Skipping invalid JSON: {line}\\\")\\n                                logger.debug(f\\\"Error: {e}\\\")\\n                                # Don't yield invalid JSON, but continue processing other lines\\n\\n                        # If we had no events in this batch, count as empty poll\\n                        if line_count == 0:\\n                            empty_polls += 1\\n\\n                        # Add a small delay to prevent tight polling\\n                        await asyncio.sleep(0.1)\\n\\n                    except asyncio.TimeoutError:\\n                        logger.debug(f\\\"WARNING: Polling request timed out after {self.poll_timeout}s\\\")\\n                        empty_polls += 1\\n                        continue\\n\\n                # If we hit the limit without finding the end event, log a warning\\n                if total_events >= self.max_total_events:\\n                    logger.debug(\\n                        f\\\"WARNING: Reached maximum event limit ({self.max_total_events}) without finding end event\\\"\\n                    )\\n\\n                if empty_polls >= self.max_empty_polls and not end_event_found:\\n                    logger.debug(\\n                        f\\\"WARNING: Reached maximum empty polls ({self.max_empty_polls}) without finding end event\\\"\\n                    )\\n\\n            except Exception as e:\\n                logger.debug(f\\\"ERROR: Unexpected error during polling: {e!s}\\\")\\n                raise\\n            finally:\\n                self._closed = True\\n\\n        def close(self):\\n            self._closed = True\\n\\n    polling_response = PollingResponse(client, job_id, logged_in_headers)\\n\\n    # Use the same consume_and_assert_stream function to verify the events\\n    await consume_and_assert_stream(polling_response, job_id)\\n\\n\\n@pytest.mark.benchmark\\nasync def test_cancel_build_unexpected_error(client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Test handling of unexpected exceptions during flow build cancellation.\\\"\\\"\\\"\\n    # First create the flow\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Start the build and get job_id\\n    build_response = await build_flow(client, flow_id, logged_in_headers)\\n    job_id = build_response[\\\"job_id\\\"]\\n    assert job_id is not None\\n\\n    # Mock the cancel_flow_build function to raise an unexpected exception\\n    import langflow.api.v1.chat\\n\\n    original_cancel_flow_build = langflow.api.v1.chat.cancel_flow_build\\n\\n    async def mock_cancel_flow_build_with_error(*_args, **_kwargs):\\n        msg = \\\"Unexpected error during cancellation\\\"\\n        raise RuntimeError(msg)\\n\\n    monkeypatch.setattr(langflow.api.v1.chat, \\\"cancel_flow_build\\\", mock_cancel_flow_build_with_error)\\n\\n    try:\\n        # Try to cancel the build - should return 500 Internal Server Error\\n        cancel_response = await client.post(f\\\"api/v1/build/{job_id}/cancel\\\", headers=logged_in_headers)\\n        assert cancel_response.status_code == codes.INTERNAL_SERVER_ERROR\\n\\n        # Verify the error message\\n        response_data = cancel_response.json()\\n        assert \\\"detail\\\" in response_data\\n        assert \\\"Unexpected error during cancellation\\\" in response_data[\\\"detail\\\"]\\n    finally:\\n        # Restore the original function to avoid affecting other tests\\n        monkeypatch.setattr(langflow.api.v1.chat, \\\"cancel_flow_build\\\", original_cancel_flow_build)\\n\\n\\n@pytest.mark.benchmark\\nasync def test_cancel_build_success(client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Test successful cancellation of a flow build.\\\"\\\"\\\"\\n    # First create the flow\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Start the build and get job_id\\n    build_response = await build_flow(client, flow_id, logged_in_headers)\\n    job_id = build_response[\\\"job_id\\\"]\\n    assert job_id is not None\\n\\n    # Mock the cancel_flow_build function to simulate a successful cancellation\\n    import langflow.api.v1.chat\\n\\n    original_cancel_flow_build = langflow.api.v1.chat.cancel_flow_build\\n\\n    async def mock_successful_cancel_flow_build(*_args, **_kwargs):\\n        return True  # Return True to indicate successful cancellation\\n\\n    monkeypatch.setattr(langflow.api.v1.chat, \\\"cancel_flow_build\\\", mock_successful_cancel_flow_build)\\n\\n    try:\\n        # Try to cancel the build (should return success)\\n        cancel_response = await client.post(f\\\"api/v1/build/{job_id}/cancel\\\", headers=logged_in_headers)\\n        assert cancel_response.status_code == codes.OK\\n\\n        # Verify the response structure indicates success\\n        response_data = cancel_response.json()\\n        assert \\\"success\\\" in response_data\\n        assert \\\"message\\\" in response_data\\n        assert response_data[\\\"success\\\"] is True\\n        assert \\\"cancelled successfully\\\" in response_data[\\\"message\\\"].lower()\\n    finally:\\n        # Restore the original function to avoid affecting other tests\\n        monkeypatch.setattr(langflow.api.v1.chat, \\\"cancel_flow_build\\\", original_cancel_flow_build)\\n\\n\\n@pytest.mark.benchmark\\nasync def test_cancel_nonexistent_build(client, logged_in_headers):\\n    \\\"\\\"\\\"Test cancelling a non-existent flow build.\\\"\\\"\\\"\\n    # Generate a random job_id that doesn't exist\\n    invalid_job_id = str(uuid.uuid4())\\n\\n    # Try to cancel a non-existent build\\n    response = await client.post(f\\\"api/v1/build/{invalid_job_id}/cancel\\\", headers=logged_in_headers)\\n    assert response.status_code == codes.NOT_FOUND\\n    assert \\\"Job not found\\\" in response.json()[\\\"detail\\\"]\\n\\n\\n@pytest.mark.benchmark\\nasync def test_cancel_build_failure(client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Test handling of cancellation failure.\\\"\\\"\\\"\\n    # First create the flow\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Start the build and get job_id\\n    build_response = await build_flow(client, flow_id, logged_in_headers)\\n    job_id = build_response[\\\"job_id\\\"]\\n    assert job_id is not None\\n\\n    # Mock the cancel_flow_build function to simulate a failure\\n    # The import path in monkeypatch should match exactly how it's imported in the application\\n    import langflow.api.v1.chat\\n\\n    original_cancel_flow_build = langflow.api.v1.chat.cancel_flow_build\\n\\n    async def mock_cancel_flow_build(*_args, **_kwargs):\\n        return False  # Return False to indicate cancellation failure\\n\\n    monkeypatch.setattr(langflow.api.v1.chat, \\\"cancel_flow_build\\\", mock_cancel_flow_build)\\n\\n    try:\\n        # Try to cancel the build (should return failure but success=False)\\n        cancel_response = await client.post(f\\\"api/v1/build/{job_id}/cancel\\\", headers=logged_in_headers)\\n        assert cancel_response.status_code == codes.OK\\n\\n        # Verify the response structure indicates failure\\n        response_data = cancel_response.json()\\n        assert \\\"success\\\" in response_data\\n        assert \\\"message\\\" in response_data\\n        assert response_data[\\\"success\\\"] is False\\n        assert \\\"Failed to cancel\\\" in response_data[\\\"message\\\"]\\n    finally:\\n        # Restore the original function to avoid affecting other tests\\n        monkeypatch.setattr(langflow.api.v1.chat, \\\"cancel_flow_build\\\", original_cancel_flow_build)\\n\\n\\n@pytest.mark.benchmark\\nasync def test_cancel_build_with_cancelled_error(client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Test handling of CancelledError during cancellation (should be treated as failure).\\\"\\\"\\\"\\n    # First create the flow\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Start the build and get job_id\\n    build_response = await build_flow(client, flow_id, logged_in_headers)\\n    job_id = build_response[\\\"job_id\\\"]\\n    assert job_id is not None\\n\\n    # Mock the cancel_flow_build function to raise CancelledError\\n    import asyncio\\n\\n    import langflow.api.v1.chat\\n\\n    original_cancel_flow_build = langflow.api.v1.chat.cancel_flow_build\\n\\n    async def mock_cancel_flow_build_with_cancelled_error(*_args, **_kwargs):\\n        msg = \\\"Task cancellation failed\\\"\\n        raise asyncio.CancelledError(msg)\\n\\n    monkeypatch.setattr(langflow.api.v1.chat, \\\"cancel_flow_build\\\", mock_cancel_flow_build_with_cancelled_error)\\n\\n    try:\\n        # Try to cancel the build - should return failure when CancelledError is raised\\n        # since our implementation treats CancelledError as a failed cancellation\\n        cancel_response = await client.post(f\\\"api/v1/build/{job_id}/cancel\\\", headers=logged_in_headers)\\n        assert cancel_response.status_code == codes.OK\\n\\n        # Verify the response structure indicates failure\\n        response_data = cancel_response.json()\\n        assert \\\"success\\\" in response_data\\n        assert \\\"message\\\" in response_data\\n        assert response_data[\\\"success\\\"] is False\\n        assert \\\"failed to cancel\\\" in response_data[\\\"message\\\"].lower()\\n    finally:\\n        # Restore the original function to avoid affecting other tests\\n        monkeypatch.setattr(langflow.api.v1.chat, \\\"cancel_flow_build\\\", original_cancel_flow_build)\\n\\n\\nasync def test_cancel_build_public_propagates_task_cancellation(monkeypatch):\\n    \\\"\\\"\\\"The public cancellation route must not translate server task cancellation into HTTP 500.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat\\n\\n    queue_service = SimpleNamespace()\\n    monkeypatch.setattr(chat, \\\"_assert_public_job\\\", AsyncMock())\\n    monkeypatch.setattr(chat, \\\"cancel_flow_build\\\", AsyncMock(side_effect=asyncio.CancelledError))\\n\\n    with pytest.raises(asyncio.CancelledError):\\n        await chat.cancel_build_public(\\\"public-job\\\", queue_service)\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.usefixtures(\\\"logged_in_headers\\\")\\nasync def test_should_have_public_events_endpoint_accessible_without_auth(client):\\n    \\\"\\\"\\\"Test that public events endpoint exists and is accessible without authentication.\\n\\n    Bug: After sending a message in the Shareable Playground, the chat input resets\\n    but no response is rendered. The root cause is that the events endpoint\\n    (/build/{job_id}/events) requires authentication, which the unauthenticated\\n    shareable playground user does not have.\\n\\n    This test proves:\\n    1. The PUBLIC events endpoint exists and responds without auth (404 = route exists, job not found)\\n    2. The AUTHENTICATED events endpoint rejects unauthenticated requests (403)\\n    \\\"\\\"\\\"\\n    fake_job_id = str(uuid.uuid4())\\n\\n    # Assert 1 \u2014 the PUBLIC events endpoint is accessible without auth\\n    # Returns 404 \\\"Job not found\\\" (route exists, but job doesn't) \u2014 NOT 401/403\\n    events_response = await client.get(\\n        f\\\"api/v1/build_public_tmp/{fake_job_id}/events?event_delivery=polling\\\",\\n        headers={\\\"Accept\\\": \\\"application/x-ndjson\\\"},\\n    )\\n    assert events_response.status_code == codes.NOT_FOUND\\n\\n    # The key proof: the public endpoint responded with 404 (route exists, job not found)\\n    # rather than 401/403 (authentication required). Before the fix, this endpoint\\n    # didn't exist at all and would return 404 for the route, not the job.\\n    assert \\\"Job not found\\\" in events_response.json()[\\\"detail\\\"]\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.usefixtures(\\\"logged_in_headers\\\")\\nasync def test_should_have_public_cancel_endpoint_accessible_without_auth(client):\\n    \\\"\\\"\\\"Test that public cancel endpoint exists and is accessible without authentication.\\n\\n    Same root cause as the events bug: the cancel endpoint requires auth\\n    but the shareable playground user is unauthenticated.\\n    \\\"\\\"\\\"\\n    fake_job_id = str(uuid.uuid4())\\n\\n    # The PUBLIC cancel endpoint is accessible without auth\\n    # Returns 404 \\\"Job not found\\\" (route exists, but job doesn't) \u2014 NOT 401/403\\n    cancel_response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{fake_job_id}/cancel\\\",\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert cancel_response.status_code == codes.NOT_FOUND\\n    assert \\\"Job not found\\\" in cancel_response.json()[\\\"detail\\\"]\\n\\n\\n@pytest.mark.benchmark\\nasync def test_build_public_tmp_ignores_data_parameter(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Test that build_public_tmp endpoint silently ignores data parameter for security.\\n\\n    Security Test: Verifies that when a user attempts to provide custom flow data\\n    to the public flow endpoint, FastAPI silently ignores the extra parameter and\\n    the endpoint functions normally using the stored flow data from the database.\\n    \\\"\\\"\\\"\\n    # Create a flow\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Make the flow public\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == codes.OK\\n\\n    # Create malicious flow data with different structure\\n    malicious_data = {\\\"nodes\\\": [{\\\"id\\\": \\\"malicious\\\", \\\"data\\\": {\\\"type\\\": \\\"CustomComponent\\\"}}], \\\"edges\\\": []}\\n\\n    # Set a client_id cookie\\n    client.cookies.set(\\\"client_id\\\", \\\"test-security-client-123\\\")\\n\\n    # Attempt to build with malicious data - FastAPI will silently ignore it\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\n            \\\"inputs\\\": {\\\"session\\\": \\\"test_session\\\"},\\n            \\\"data\\\": malicious_data,  # This will be silently ignored by FastAPI\\n        },\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    # Verify the request succeeded - the data parameter is simply ignored\\n    assert response.status_code == codes.OK\\n    response_data = response.json()\\n    assert \\\"job_id\\\" in response_data\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_rate_limits_each_client_and_flow(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Anonymous builds are bounded without sharing counters across public flows.\\\"\\\"\\\"\\n\\n    async def create_public_flow():\\n        flow_data = json.loads(json_memory_chatbot_no_llm)\\n        flow_data[\\\"id\\\"] = str(uuid.uuid4())\\n        flow_id = await create_flow(client, json.dumps(flow_data), logged_in_headers)\\n        response = await client.patch(\\n            f\\\"api/v1/flows/{flow_id}\\\",\\n            json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == codes.OK\\n        return flow_id\\n\\n    first_flow_id = await create_public_flow()\\n    second_flow_id = await create_public_flow()\\n    started_source_flow_ids = []\\n\\n    async def fake_start_flow_build(**kwargs):\\n        started_source_flow_ids.append(kwargs[\\\"source_flow_id\\\"])\\n        return str(uuid.uuid4())\\n\\n    monkeypatch.setattr(\\\"langflow.api.v1.chat.start_flow_build\\\", fake_start_flow_build)\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"rate_limit_enabled\\\", True)\\n    monkeypatch.setattr(settings, \\\"public_flow_rate_limit_per_minute\\\", 2)\\n\\n    client.cookies.clear()\\n    client.cookies.set(\\\"client_id\\\", \\\"test-public-build-rate-limit-client\\\")\\n    request_kwargs = {\\n        \\\"json\\\": {\\\"inputs\\\": {\\\"session\\\": \\\"test_session\\\"}},\\n        \\\"headers\\\": {\\\"Content-Type\\\": \\\"application/json\\\"},\\n    }\\n\\n    for _ in range(2):\\n        response = await client.post(f\\\"api/v1/build_public_tmp/{first_flow_id}/flow\\\", **request_kwargs)\\n        assert response.status_code == codes.OK\\n\\n    limited_response = await client.post(f\\\"api/v1/build_public_tmp/{first_flow_id}/flow\\\", **request_kwargs)\\n    assert limited_response.status_code == codes.TOO_MANY_REQUESTS\\n    assert limited_response.headers[\\\"Retry-After\\\"] == \\\"60\\\"\\n\\n    other_flow_response = await client.post(f\\\"api/v1/build_public_tmp/{second_flow_id}/flow\\\", **request_kwargs)\\n    assert other_flow_response.status_code == codes.OK\\n    assert started_source_flow_ids == [first_flow_id, first_flow_id, second_flow_id]\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\n@pytest.mark.parametrize(\\n    \\\"malicious_files\\\",\\n    [\\n        [\\\"/etc/hosts\\\"],\\n        [\\\"/etc/passwd\\\"],\\n        [\\\"../../etc/passwd\\\"],\\n        [\\\"..\\\\\\\\..\\\\\\\\windows\\\\\\\\system32\\\\\\\\drivers\\\\\\\\etc\\\\\\\\hosts\\\"],\\n        [\\\"s3://other-bucket/secret.txt\\\"],\\n        [\\\"just_a_filename.txt\\\"],\\n        # foreign flow_id segment \u2014 looks well-formed but isn't this flow's namespace\\n        [\\\"00000000-0000-0000-0000-000000000000/file.png\\\"],\\n        # null byte smuggling\\n        [\\\"abc\\\\x00/file.png\\\"],\\n    ],\\n)\\nasync def test_build_public_tmp_rejects_malicious_files(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, malicious_files\\n):\\n    \\\"\\\"\\\"Regression for GHSA-rcjh-r59h-gq37 \u2014 unauth public build must not accept arbitrary file paths.\\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == codes.OK\\n\\n    client.cookies.set(\\\"client_id\\\", \\\"test-files-validation-client\\\")\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\n            \\\"inputs\\\": {\\\"session\\\": \\\"test_session\\\"},\\n            \\\"files\\\": malicious_files,\\n        },\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert response.status_code == codes.BAD_REQUEST\\n    assert \\\"file\\\" in response.json()[\\\"detail\\\"].lower()\\n\\n\\n@pytest.mark.benchmark\\nasync def test_build_public_tmp_accepts_files_in_own_namespace(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Files namespaced under the public flow's own UUID must still be accepted.\\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == codes.OK\\n\\n    client.cookies.set(\\\"client_id\\\", \\\"test-files-allowed-client\\\")\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\n            \\\"inputs\\\": {\\\"session\\\": \\\"test_session\\\"},\\n            \\\"files\\\": [f\\\"{flow_id}/example_attachment.png\\\"],\\n        },\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert response.status_code == codes.OK\\n\\n\\n@pytest.mark.benchmark\\nasync def test_build_public_tmp_checks_public_access_before_validation(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Private flows should fail at the public-access gate before any policy validation runs.\\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    client.cookies.set(\\\"client_id\\\", \\\"test-private-flow-client\\\")\\n    public_access_validation_message = \\\"validation should not run before public access checks\\\"\\n\\n    def fail_if_validation_runs(_target):\\n        raise ValueError(public_access_validation_message)\\n\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.chat.validate_catalog_policy_for_flow\\\",\\n        fail_if_validation_runs,\\n    )\\n\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": \\\"test_session\\\"}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert response.status_code == codes.NOT_FOUND\\n    assert response.json()[\\\"detail\\\"] == \\\"Flow not found\\\"\\n\\n\\nasync def test_build_public_tmp_enforces_current_catalog_policy_with_generic_error(\\n    client, json_memory_chatbot_no_llm, logged_in_headers\\n):\\n    from lfx.services.deps import get_catalog_policy_service\\n\\n    catalog_policy_service = get_catalog_policy_service()\\n    await catalog_policy_service.replace_blocked_component_keys([], actor_user_id=None)\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == codes.OK\\n    await catalog_policy_service.replace_blocked_component_keys([\\\"ChatInput\\\"], actor_user_id=None)\\n    client.cookies.set(\\\"client_id\\\", \\\"test-catalog-policy-client\\\")\\n\\n    blocked_response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    await catalog_policy_service.replace_blocked_component_keys([], actor_user_id=None)\\n    allowed_response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert blocked_response.status_code == codes.BAD_REQUEST\\n    assert blocked_response.json()[\\\"detail\\\"] == \\\"This flow cannot be executed.\\\"\\n    assert \\\"ChatInput\\\" not in blocked_response.text\\n    assert allowed_response.status_code == codes.OK\\n    assert \\\"job_id\\\" in allowed_response.json()\\n\\n\\nasync def test_build_public_tmp_sanitizes_catalog_identity_unavailable_response(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    from lfx.utils.flow_validation import (\\n        PUBLIC_CATALOG_POLICY_UNAVAILABLE_MESSAGE,\\n        CatalogPolicyIdentityUnavailableError,\\n    )\\n\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == codes.OK\\n    client.cookies.set(\\\"client_id\\\", \\\"test-catalog-identity-unavailable-client\\\")\\n    raw_message = \\\"Catalog identities unavailable: internal generation 42\\\"\\n\\n    def identities_unavailable(_target):\\n        raise CatalogPolicyIdentityUnavailableError(raw_message)\\n\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.chat.validate_catalog_policy_for_flow\\\",\\n        identities_unavailable,\\n    )\\n\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert response.status_code == codes.SERVICE_UNAVAILABLE\\n    assert response.json()[\\\"detail\\\"] == PUBLIC_CATALOG_POLICY_UNAVAILABLE_MESSAGE\\n    assert raw_message not in response.text\\n\\n\\n@pytest.mark.security\\nasync def test_build_public_tmp_sanitizes_unexpected_gate_value_error(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Anonymous validation failures never disclose stored flow internals.\\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == codes.OK\\n    client.cookies.set(\\\"client_id\\\", \\\"test-sanitized-value-error-client\\\")\\n    raw_message = \\\"invalid node SecretProvider-1 with credential super-secret\\\"\\n\\n    def invalid_stored_flow(_target):\\n        raise ValueError(raw_message)\\n\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.chat.validate_catalog_policy_for_flow\\\",\\n        invalid_stored_flow,\\n    )\\n\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert response.status_code == codes.BAD_REQUEST\\n    assert response.json()[\\\"detail\\\"] == \\\"This flow cannot be executed.\\\"\\n    assert raw_message not in response.text\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_rejects_code_execution_components(\\n    client, json_memory_chatbot_no_llm, logged_in_headers\\n):\\n    \\\"\\\"\\\"Report H1-3754930: unauthenticated public builds must reject code-execution components.\\n\\n    A public flow containing a Python interpreter/REPL (or the legacy Python Code\\n    Structured tool) would otherwise let any anonymous visitor trigger\\n    server-side code execution through /build_public_tmp.\\n    \\\"\\\"\\\"\\n    flow_dict = json.loads(json_memory_chatbot_no_llm)\\n    flow_dict[\\\"data\\\"][\\\"nodes\\\"].append(\\n        {\\n            \\\"id\\\": \\\"PythonREPLComponent-pub1\\\",\\n            \\\"type\\\": \\\"genericNode\\\",\\n            \\\"position\\\": {\\\"x\\\": 0, \\\"y\\\": 0},\\n            \\\"data\\\": {\\n                \\\"id\\\": \\\"PythonREPLComponent-pub1\\\",\\n                \\\"type\\\": \\\"PythonREPLComponent\\\",\\n                \\\"display_name\\\": \\\"Python Interpreter\\\",\\n                \\\"node\\\": {\\\"display_name\\\": \\\"Python Interpreter\\\", \\\"template\\\": {}},\\n            },\\n        }\\n    )\\n    flow_id = await create_flow(client, json.dumps(flow_dict), logged_in_headers)\\n\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == codes.OK\\n\\n    client.cookies.set(\\\"client_id\\\", \\\"test-code-exec-client\\\")\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": \\\"test_session\\\"}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert response.status_code == codes.BAD_REQUEST\\n    assert response.json()[\\\"detail\\\"] == \\\"This flow cannot be executed.\\\"\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_rejects_mcp_stdio_server_config(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Unauthenticated public builds must reject an MCP Tools node using the stdio transport.\\n\\n    The OS command lives in the ``mcp_server`` field VALUE, not in ``code``, so the\\n    trusted-code substitution performed for public builds does not neutralise it. Without\\n    an explicit check, triggering the public flow spawns that process as the server account.\\n    \\\"\\\"\\\"\\n    flow_dict = json.loads(json_memory_chatbot_no_llm)\\n    flow_dict[\\\"data\\\"][\\\"nodes\\\"].append(\\n        {\\n            \\\"id\\\": \\\"MCPTools-pub1\\\",\\n            \\\"type\\\": \\\"genericNode\\\",\\n            \\\"position\\\": {\\\"x\\\": 0, \\\"y\\\": 0},\\n            \\\"data\\\": {\\n                \\\"id\\\": \\\"MCPTools-pub1\\\",\\n                \\\"type\\\": \\\"MCPTools\\\",\\n                \\\"node\\\": {\\n                    \\\"display_name\\\": \\\"MCP Tools\\\",\\n                    \\\"template\\\": {\\n                        \\\"mcp_server\\\": {\\n                            \\\"type\\\": \\\"mcp\\\",\\n                            \\\"name\\\": \\\"mcp_server\\\",\\n                            \\\"value\\\": {\\n                                \\\"name\\\": \\\"local\\\",\\n                                \\\"config\\\": {\\\"command\\\": \\\"python\\\", \\\"args\\\": [\\\"-m\\\", \\\"some_module\\\"]},\\n                            },\\n                        }\\n                    },\\n                },\\n            },\\n        }\\n    )\\n    flow_id = await create_flow(client, json.dumps(flow_dict), logged_in_headers)\\n\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == codes.OK\\n\\n    # The shared client persists access-token cookies from ``logged_in_headers``; clearing\\n    # them is the only way to exercise the genuinely unauthenticated public path.\\n    client.cookies.clear()\\n    client.cookies.set(\\\"client_id\\\", \\\"test-mcp-stdio-client\\\")\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": \\\"test_session\\\"}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert response.status_code == codes.BAD_REQUEST\\n    assert response.json()[\\\"detail\\\"] == \\\"This flow cannot be executed.\\\"\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_rejects_flow_invoking_components(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Report H1-3754930 (transitive case): public builds must reject flow-invoking components.\\n\\n    A public wrapper flow with no directly-blocked nodes could otherwise embed a\\n    Run Flow / Sub Flow / Flow as Tool node that loads and executes another saved\\n    owner flow by id/name at runtime \u2014 a private flow which may itself contain a\\n    code-execution component that is never re-validated on the run path. Blocking\\n    the flow-invoking node type on the public path closes that indirection.\\n    \\\"\\\"\\\"\\n    flow_dict = json.loads(json_memory_chatbot_no_llm)\\n    flow_dict[\\\"data\\\"][\\\"nodes\\\"].append(\\n        {\\n            \\\"id\\\": \\\"RunFlow-pub1\\\",\\n            \\\"type\\\": \\\"genericNode\\\",\\n            \\\"position\\\": {\\\"x\\\": 0, \\\"y\\\": 0},\\n            \\\"data\\\": {\\n                \\\"id\\\": \\\"RunFlow-pub1\\\",\\n                \\\"type\\\": \\\"RunFlow\\\",\\n                \\\"display_name\\\": \\\"Run Flow\\\",\\n                \\\"node\\\": {\\n                    \\\"display_name\\\": \\\"Run Flow\\\",\\n                    \\\"template\\\": {\\\"flow_id_selected\\\": {\\\"value\\\": str(uuid.uuid4())}},\\n                },\\n            },\\n        }\\n    )\\n    flow_id = await create_flow(client, json.dumps(flow_dict), logged_in_headers)\\n\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == codes.OK\\n\\n    client.cookies.set(\\\"client_id\\\", \\\"test-flow-invoke-client\\\")\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": \\\"test_session\\\"}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert response.status_code == codes.BAD_REQUEST\\n    assert response.json()[\\\"detail\\\"] == \\\"This flow cannot be executed.\\\"\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_flow_cross_user_blocked(client, json_memory_chatbot_no_llm, logged_in_headers, user_two):\\n    \\\"\\\"\\\"Security (GHSA-qj98-rhf8-v93f): authenticated user cannot build another user's private flow.\\n\\n    Regression guard: verifies that the ownership check added to build_flow rejects\\n    requests where flow.user_id != current_user.id and the flow is not PUBLIC.\\n    \\\"\\\"\\\"\\n    victim_flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    login_data = {\\\"username\\\": user_two.username, \\\"password\\\": \\\"hashed_password\\\"}  # pragma: allowlist secret\\n    response = await client.post(\\\"api/v1/login\\\", data=login_data)\\n    assert response.status_code == 200\\n    attacker_headers = {\\\"Authorization\\\": f\\\"Bearer {response.json()['access_token']}\\\"}\\n\\n    response = await client.post(f\\\"api/v1/build/{victim_flow_id}/flow\\\", json={}, headers=attacker_headers)\\n    assert response.status_code == 404\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_flow_unauthenticated_blocked(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Unauthenticated request to build_flow must be rejected (4xx \u2014 no valid credentials).\\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    # Clear any cookies retained from previous tests to ensure a truly unauthenticated request.\\n    client.cookies.clear()\\n    response = await client.post(f\\\"api/v1/build/{flow_id}/flow\\\", json={})\\n    assert response.status_code == 403\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_flow_nonexistent_flow_returns_404(client, logged_in_headers):\\n    \\\"\\\"\\\"Non-existent flow UUID must return 404.\\\"\\\"\\\"\\n    nonexistent_id = uuid.uuid4()\\n    response = await client.post(f\\\"api/v1/build/{nonexistent_id}/flow\\\", json={}, headers=logged_in_headers)\\n    assert response.status_code == 404\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_events_cross_user_blocked(client, json_memory_chatbot_no_llm, logged_in_headers, user_two):\\n    \\\"\\\"\\\"Security (GHSA-qj98-rhf8-v93f): user cannot poll build events owned by another user.\\n\\n    Even if an attacker somehow obtains a valid job_id, the events endpoint independently\\n    enforces ownership via the _job_owners registry in JobQueueService.\\n    \\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    build_response = await build_flow(client, flow_id, logged_in_headers)\\n    job_id = build_response[\\\"job_id\\\"]\\n\\n    login_data = {\\\"username\\\": user_two.username, \\\"password\\\": \\\"hashed_password\\\"}  # pragma: allowlist secret\\n    response = await client.post(\\\"api/v1/login\\\", data=login_data)\\n    assert response.status_code == 200\\n    attacker_headers = {\\\"Authorization\\\": f\\\"Bearer {response.json()['access_token']}\\\"}\\n\\n    response = await get_build_events(client, job_id, attacker_headers)\\n    assert response.status_code == 404\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_flow_public_flow_accessible_by_other_user(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, user_two\\n):\\n    \\\"\\\"\\\"A PUBLIC flow can be built by any authenticated user, not only the owner.\\n\\n    Verifies that the ownership check correctly allows access_type == PUBLIC flows\\n    and does not over-restrict the multi-tenant sharing use case.\\n    \\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == 200\\n\\n    login_data = {\\\"username\\\": user_two.username, \\\"password\\\": \\\"hashed_password\\\"}  # pragma: allowlist secret\\n    response = await client.post(\\\"api/v1/login\\\", data=login_data)\\n    assert response.status_code == 200\\n    other_headers = {\\\"Authorization\\\": f\\\"Bearer {response.json()['access_token']}\\\"}\\n\\n    response = await client.post(f\\\"api/v1/build/{flow_id}/flow\\\", json={}, headers=other_headers)\\n    assert response.status_code == 200\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_cancel_build_cross_user_blocked(client, json_memory_chatbot_no_llm, logged_in_headers, user_two):\\n    \\\"\\\"\\\"Security: authenticated user cannot cancel a build job owned by another user.\\n\\n    cancel_build carries the same DoS risk as get_build_events \u2014 an attacker who\\n    obtains a job_id should not be able to abort the victim's running build.\\n    \\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    build_response = await build_flow(client, flow_id, logged_in_headers)\\n    job_id = build_response[\\\"job_id\\\"]\\n\\n    login_data = {\\\"username\\\": user_two.username, \\\"password\\\": \\\"hashed_password\\\"}  # pragma: allowlist secret\\n    response = await client.post(\\\"api/v1/login\\\", data=login_data)\\n    assert response.status_code == 200\\n    attacker_headers = {\\\"Authorization\\\": f\\\"Bearer {response.json()['access_token']}\\\"}\\n\\n    response = await client.post(f\\\"api/v1/build/{job_id}/cancel\\\", headers=attacker_headers)\\n    assert response.status_code == 404\\n\\n\\n@pytest.mark.benchmark\\nasync def test_build_public_tmp_without_data_parameter(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"Test that build_public_tmp endpoint works without data parameter.\\n\\n    Security Test: Verifies that when no data parameter is provided, the endpoint\\n    works normally and returns a job_id. This proves the data parameter is optional\\n    and the stored flow definition is always used.\\n    \\\"\\\"\\\"\\n    # Create a flow\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Make the flow public\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == codes.OK\\n\\n    # Set a client_id cookie\\n    client.cookies.set(\\\"client_id\\\", \\\"test-no-data-client\\\")\\n\\n    # Build without providing data parameter\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": \\\"test_session\\\"}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    # Verify the request succeeded\\n    assert response.status_code == codes.OK\\n    response_data = response.json()\\n    assert \\\"job_id\\\" in response_data\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_rejects_custom_component(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"H1-3754930 follow-up: an unrecognized custom component must be rejected on the public path.\\n\\n    Under the default allow_public_custom_components=False, the unauthenticated public build path\\n    runs only the server's trusted code for known component types and rejects custom/unknown\\n    component code, so an anonymous visitor cannot trigger arbitrary server-side code execution\\n    even when allow_custom_components is True (the default).\\n    \\\"\\\"\\\"\\n    flow_dict = json.loads(json_memory_chatbot_no_llm)\\n    flow_dict[\\\"data\\\"][\\\"nodes\\\"].append(\\n        {\\n            \\\"id\\\": \\\"EvilCustom-1\\\",\\n            \\\"type\\\": \\\"genericNode\\\",\\n            \\\"position\\\": {\\\"x\\\": 0, \\\"y\\\": 0},\\n            \\\"data\\\": {\\n                \\\"id\\\": \\\"EvilCustom-1\\\",\\n                \\\"type\\\": \\\"TotallyCustomEvilComponent\\\",\\n                \\\"node\\\": {\\n                    \\\"display_name\\\": \\\"Evil Custom\\\",\\n                    \\\"template\\\": {\\\"code\\\": {\\\"value\\\": \\\"import os\\\\nos.system('id')\\\\n\\\"}},\\n                },\\n            },\\n        }\\n    )\\n    flow_id = await create_flow(client, json.dumps(flow_dict), logged_in_headers)\\n\\n    response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == codes.OK\\n\\n    client.cookies.set(\\\"client_id\\\", \\\"test-custom-component-client\\\")\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": \\\"test_session\\\"}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert response.status_code == codes.BAD_REQUEST\\n    assert response.json()[\\\"detail\\\"] == \\\"This flow cannot be executed.\\\"\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_get_build_events_public_tmp_job_accessible_by_any_auth_user(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, user_two, monkeypatch\\n):\\n    \\\"\\\"\\\"A job started via build_public_tmp has no registered owner and is accessible to any authenticated user.\\n\\n    Verifies that get_build_events skips the ownership check when get_job_owner returns None.\\n    \\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == codes.OK\\n\\n    client.cookies.set(\\\"client_id\\\", \\\"test-public-tmp-events-client\\\")\\n    start_response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert start_response.status_code == codes.OK\\n    job_id = start_response.json()[\\\"job_id\\\"]\\n\\n    login_data = {\\\"username\\\": user_two.username, \\\"password\\\": \\\"hashed_password\\\"}  # pragma: allowlist secret\\n    login_response = await client.post(\\\"api/v1/login\\\", data=login_data)\\n    assert login_response.status_code == codes.OK\\n    other_headers = {\\\"Authorization\\\": f\\\"Bearer {login_response.json()['access_token']}\\\"}\\n\\n    import langflow.api.v1.chat\\n    from fastapi import Response\\n\\n    async def mock_get_flow_events_response(**_kwargs):\\n        return Response(content=\\\"\\\", media_type=\\\"application/x-ndjson\\\")\\n\\n    monkeypatch.setattr(langflow.api.v1.chat, \\\"get_flow_events_response\\\", mock_get_flow_events_response)\\n\\n    events_response = await get_build_events(client, job_id, other_headers)\\n    assert events_response.status_code == codes.OK\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_cancel_build_public_tmp_job_accessible_by_any_auth_user(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, user_two, monkeypatch\\n):\\n    \\\"\\\"\\\"A job started via build_public_tmp has no registered owner and can be cancelled by any authenticated user.\\n\\n    Verifies that cancel_build skips the ownership check when get_job_owner returns None.\\n    \\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == codes.OK\\n\\n    client.cookies.set(\\\"client_id\\\", \\\"test-public-tmp-cancel-client\\\")\\n    start_response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert start_response.status_code == codes.OK\\n    job_id = start_response.json()[\\\"job_id\\\"]\\n\\n    login_data = {\\\"username\\\": user_two.username, \\\"password\\\": \\\"hashed_password\\\"}  # pragma: allowlist secret\\n    login_response = await client.post(\\\"api/v1/login\\\", data=login_data)\\n    assert login_response.status_code == codes.OK\\n    other_headers = {\\\"Authorization\\\": f\\\"Bearer {login_response.json()['access_token']}\\\"}\\n\\n    import langflow.api.v1.chat\\n\\n    async def mock_cancel_flow_build(*_args, **_kwargs):\\n        return True\\n\\n    monkeypatch.setattr(langflow.api.v1.chat, \\\"cancel_flow_build\\\", mock_cancel_flow_build)\\n\\n    cancel_response = await client.post(f\\\"api/v1/build/{job_id}/cancel\\\", headers=other_headers)\\n    assert cancel_response.status_code == codes.OK\\n    assert cancel_response.json()[\\\"success\\\"] is True\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.security\\nasync def test_job_owner_cleaned_up_after_cleanup_job():\\n    \\\"\\\"\\\"JobQueueService.cleanup_job removes the _job_owners entry for the job.\\\"\\\"\\\"\\n    service = JobQueueService()\\n    service.start()\\n\\n    try:\\n        job_id = str(uuid.uuid4())\\n        user_id = uuid.uuid4()\\n\\n        service.create_queue(job_id)\\n\\n        async def _noop():\\n            await asyncio.sleep(0)\\n\\n        service.start_job(job_id, _noop())\\n        await asyncio.sleep(0.05)\\n        await service.register_job_owner(job_id, user_id)\\n\\n        assert await service.get_job_owner(job_id) == user_id\\n\\n        await service.cleanup_job(job_id)\\n\\n        assert await service.get_job_owner(job_id) is None\\n    finally:\\n        service._closed = True\\n        if service._cleanup_task:\\n            service._cleanup_task.cancel()\\n            with contextlib.suppress(asyncio.CancelledError, Exception):\\n                await service._cleanup_task\\n\\n\\n# ---------------------------------------------------------------------------\\n# CVE-2026-33017: session-id namespacing on build_public_tmp\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _stub_start_flow_build(monkeypatch, captured: dict) -> None:\\n    \\\"\\\"\\\"Capture the kwargs that would be dispatched to start_flow_build without running the build.\\\"\\\"\\\"\\n    import langflow.api.v1.chat as chat_module\\n\\n    async def _fake_start_flow_build(**kwargs):\\n        captured.update(kwargs)\\n        return \\\"00000000-0000-0000-0000-00000000ffff\\\"\\n\\n    monkeypatch.setattr(chat_module, \\\"start_flow_build\\\", _fake_start_flow_build)\\n\\n\\ndef _send_unauthenticated(client, client_id: str) -> None:\\n    \\\"\\\"\\\"Drop login cookies and set the public client_id cookie.\\n\\n    The shared AsyncClient persists access-token cookies from logged_in_headers\\n    that would otherwise let get_current_user_optional resolve a user and\\n    namespace under user_id -- not the unauthenticated shape the CVE targets.\\n    \\\"\\\"\\\"\\n    client.cookies.clear()\\n    client.cookies.set(\\\"client_id\\\", client_id)\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_strips_persisted_owner_secrets_before_dispatch(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"The public V1 build may execute trusted code, but never a secret embedded in the owner's graph.\\\"\\\"\\\"\\n    import langflow.api.v1.chat as chat_module\\n\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == codes.OK\\n\\n    prepared = json.loads(json_memory_chatbot_no_llm)[\\\"data\\\"]\\n    prepared[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"owner_api_key\\\"] = {\\n        \\\"name\\\": \\\"owner_api_key\\\",\\n        \\\"password\\\": True,\\n        \\\"value\\\": \\\"sk-owner-secret\\\",  # pragma: allowlist secret\\n    }\\n\\n    async def _prepare(_flow_data):\\n        return prepared\\n\\n    captured: dict = {}\\n    monkeypatch.setattr(chat_module, \\\"prepare_public_flow_build\\\", _prepare)\\n    _stub_start_flow_build(monkeypatch, captured)\\n    _send_unauthenticated(client, \\\"secret-isolation-client\\\")\\n\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": \\\"secret-isolation-session\\\"}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert response.status_code == codes.OK\\n    dispatched = captured[\\\"data\\\"]\\n    assert dispatched is not None\\n    assert dispatched.nodes[0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"owner_api_key\\\"][\\\"value\\\"] is None\\n    assert prepared[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"owner_api_key\\\"][\\\"value\\\"] == \\\"sk-owner-secret\\\"\\n    from langflow.services.authorization.public_access import PUBLIC_ANONYMOUS_ACTOR_ID\\n\\n    assert captured[\\\"current_user\\\"].id == PUBLIC_ANONYMOUS_ACTOR_ID\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_reauthorizes_reloaded_flow_after_grant_transition(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"A grant revoked between admission and reload cannot execute the later snapshot.\\\"\\\"\\\"\\n    import langflow.api.v1.chat as chat_module\\n    from langflow.api.utils.flow_utils import compute_virtual_flow_id\\n    from langflow.services.authorization.public_access import public_execution_user\\n    from langflow.services.database.models.flow.model import AccessTypeEnum, Flow\\n    from langflow.services.deps import session_scope\\n\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == codes.OK\\n\\n    client_id = \\\"v1-reload-revocation-client\\\"\\n\\n    async def _admit_first_snapshot_then_revoke(**_kwargs):\\n        async with session_scope() as session:\\n            flow = await session.get(Flow, flow_id)\\n            assert flow is not None\\n            flow.access_type = AccessTypeEnum.PRIVATE\\n            session.add(flow)\\n            await session.commit()\\n        return public_execution_user(), compute_virtual_flow_id(client_id, flow_id, principal_type=\\\"client\\\")\\n\\n    captured: dict = {}\\n    monkeypatch.setattr(chat_module, \\\"verify_public_flow_and_get_user\\\", _admit_first_snapshot_then_revoke)\\n    _stub_start_flow_build(monkeypatch, captured)\\n    _send_unauthenticated(client, client_id)\\n\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": \\\"transition\\\"}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    assert response.status_code == codes.NOT_FOUND\\n    assert response.json() == {\\\"detail\\\": \\\"Flow not found\\\"}\\n    assert captured == {}\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_namespaces_caller_session(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Caller-supplied session equal to the real flow UUID is wrapped under the namespace.\\n\\n    The threat: /api/v1/run hands out session_id == flow_id by default, and the\\n    flow UUID is visible in URLs. Without namespacing, an unauthenticated caller\\n    can pass that UUID as inputs.session and a Memory component reads its history.\\n    \\\"\\\"\\\"\\n    from langflow.api.utils.flow_utils import compute_virtual_flow_id\\n\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == codes.OK\\n\\n    captured: dict = {}\\n    _stub_start_flow_build(monkeypatch, captured)\\n\\n    client_id = \\\"ns-test-client\\\"\\n    _send_unauthenticated(client, client_id)\\n    victim_session = str(flow_id)\\n\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": victim_session}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert response.status_code == codes.OK\\n\\n    expected_namespace = str(compute_virtual_flow_id(client_id, flow_id, principal_type=\\\"client\\\"))\\n    sent_inputs = captured[\\\"inputs\\\"]\\n    assert sent_inputs is not None\\n    assert sent_inputs.session == f\\\"{expected_namespace}:{victim_session}\\\"\\n    assert sent_inputs.session != victim_session\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_session_already_namespaced_unchanged(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Idempotency: a value already in-namespace is forwarded as-is, not double-wrapped.\\\"\\\"\\\"\\n    from langflow.api.utils.flow_utils import compute_virtual_flow_id\\n\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == codes.OK\\n\\n    captured: dict = {}\\n    _stub_start_flow_build(monkeypatch, captured)\\n\\n    client_id = \\\"ns-passthrough-client\\\"\\n    _send_unauthenticated(client, client_id)\\n    namespace = str(compute_virtual_flow_id(client_id, flow_id, principal_type=\\\"client\\\"))\\n    already_scoped = f\\\"{namespace}:thread-1\\\"\\n\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": already_scoped}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert response.status_code == codes.OK\\n    assert captured[\\\"inputs\\\"].session == already_scoped\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_isolates_disjoint_clients(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Different client_ids submitting the same session string land in disjoint namespaces.\\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == codes.OK\\n\\n    captured: dict = {}\\n    _stub_start_flow_build(monkeypatch, captured)\\n\\n    shared_session = \\\"shared-session-name\\\"\\n\\n    _send_unauthenticated(client, \\\"client-A\\\")\\n    response_a = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": shared_session}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert response_a.status_code == codes.OK\\n    session_a = captured[\\\"inputs\\\"].session\\n\\n    captured.clear()\\n    _send_unauthenticated(client, \\\"client-B\\\")\\n    response_b = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": shared_session}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert response_b.status_code == codes.OK\\n    session_b = captured[\\\"inputs\\\"].session\\n\\n    assert session_a != session_b\\n    assert session_a.endswith(f\\\":{shared_session}\\\")\\n    assert session_b.endswith(f\\\":{shared_session}\\\")\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_no_session_passthrough(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"No inputs supplied: namespacing is skipped; downstream falls back to the virtual flow ID.\\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == codes.OK\\n\\n    captured: dict = {}\\n    _stub_start_flow_build(monkeypatch, captured)\\n\\n    _send_unauthenticated(client, \\\"ns-default-client\\\")\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": None},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert response.status_code == codes.OK\\n    assert captured[\\\"inputs\\\"] is None\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_empty_session_is_namespaced(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"An empty-string session is scoped, not forwarded as-is.\\n\\n    Empty string is currently *coincidentally* safe (downstream `or virtual_id`\\n    fallbacks save it), but a refactor of either branch would silently regress.\\n    Pin the contract here: empty becomes ``f\\\"{namespace}:\\\"``.\\n    \\\"\\\"\\\"\\n    from langflow.api.utils.flow_utils import compute_virtual_flow_id\\n\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == codes.OK\\n\\n    captured: dict = {}\\n    _stub_start_flow_build(monkeypatch, captured)\\n\\n    client_id = \\\"ns-empty-client\\\"\\n    _send_unauthenticated(client, client_id)\\n\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": \\\"\\\"}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert response.status_code == codes.OK\\n\\n    expected_namespace = str(compute_virtual_flow_id(client_id, flow_id, principal_type=\\\"client\\\"))\\n    sent_session = captured[\\\"inputs\\\"].session\\n    assert sent_session != \\\"\\\"\\n    assert sent_session == f\\\"{expected_namespace}:\\\"\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_authenticated_namespace_uses_user_id(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, active_user, monkeypatch\\n):\\n    \\\"\\\"\\\"AUTO_LOGIN=False (prod-like) + valid bearer: the namespace is derived from user.id.\\\"\\\"\\\"\\n    from langflow.api.utils.flow_utils import compute_virtual_flow_id\\n\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == codes.OK\\n\\n    captured: dict = {}\\n    _stub_start_flow_build(monkeypatch, captured)\\n\\n    client.cookies.set(\\\"client_id\\\", \\\"should-be-ignored\\\")\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": \\\"thread-A\\\"}},\\n        headers={**logged_in_headers, \\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert response.status_code == codes.OK\\n\\n    expected_namespace = str(compute_virtual_flow_id(active_user.id, flow_id, principal_type=\\\"user\\\"))\\n    assert captured[\\\"inputs\\\"].session == f\\\"{expected_namespace}:thread-A\\\"\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_build_public_tmp_namespacing_blocks_memory_query_collision(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"End-to-end proof that namespacing prevents Memory query collision.\\n\\n    A victim message stored under ``session_id == flow_id`` is unreachable via a\\n    Memory query keyed on the namespaced session that build_public_tmp forwards.\\n    This is the test that catches a regression in either the endpoint guard or\\n    the helper -- the shape-only tests above would still pass if the rewrite\\n    was applied but the downstream query stopped honoring it.\\n    \\\"\\\"\\\"\\n    from lfx.memory import aadd_messages, aget_messages\\n    from lfx.schema.message import Message\\n\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == codes.OK\\n\\n    victim_session = str(flow_id)\\n    await aadd_messages(\\n        Message(text=\\\"victim-secret\\\", sender=\\\"User\\\", sender_name=\\\"User\\\", session_id=victim_session),\\n        flow_id=flow_id,\\n    )\\n    seeded = await aget_messages(session_id=victim_session)\\n    assert any(m.text == \\\"victim-secret\\\" for m in seeded)\\n\\n    captured: dict = {}\\n    _stub_start_flow_build(monkeypatch, captured)\\n    _send_unauthenticated(client, \\\"leak-test-client\\\")\\n\\n    response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{flow_id}/flow\\\",\\n        json={\\\"inputs\\\": {\\\"session\\\": victim_session}},\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert response.status_code == codes.OK\\n\\n    namespaced_session = captured[\\\"inputs\\\"].session\\n    assert namespaced_session != victim_session\\n\\n    leaked = await aget_messages(session_id=namespaced_session)\\n    assert all(m.text != \\\"victim-secret\\\" for m in leaked)\\n\\n    still_seeded = await aget_messages(session_id=victim_session)\\n    assert any(m.text == \\\"victim-secret\\\" for m in still_seeded)\\n\\n\\ndef test_scope_session_to_namespace_helper():\\n    from langflow.api.utils import scope_session_to_namespace\\n\\n    ns = \\\"namespace-A\\\"\\n    assert scope_session_to_namespace(None, ns) is None\\n    assert scope_session_to_namespace(\\\"\\\", ns) == f\\\"{ns}:\\\"\\n    assert scope_session_to_namespace(ns, ns) == ns\\n    assert scope_session_to_namespace(f\\\"{ns}:thread-1\\\", ns) == f\\\"{ns}:thread-1\\\"\\n    assert scope_session_to_namespace(\\\"victim-session\\\", ns) == f\\\"{ns}:victim-session\\\"\\n    assert scope_session_to_namespace(\\\"victim-session\\\", \\\"namespace-B\\\") == \\\"namespace-B:victim-session\\\"\\n    # A foreign-namespace prefix is treated as out-of-namespace and gets re-wrapped.\\n    assert scope_session_to_namespace(\\\"namespace-B:victim\\\", \\\"namespace-A\\\") == \\\"namespace-A:namespace-B:victim\\\"\\n\\n\\n# \u2500\u2500 Public job registry unit tests \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n# CVE fix: unauthenticated callers must not access private-flow job streams\\n# by guessing or leaking a job_id from the authenticated build endpoint.\\n\\n\\nasync def test_job_queue_service_register_and_check_public_job():\\n    \\\"\\\"\\\"register_public_job marks a job as public; is_public_job reflects that.\\\"\\\"\\\"\\n    svc = JobQueueService()\\n    job_id = str(uuid.uuid4())\\n\\n    # Why: job not registered yet \u2014 must return False before registration\\n    assert svc.is_public_job(job_id) is False\\n\\n    await svc.register_public_job(job_id)\\n\\n    # Why: job registered \u2014 must return True after registration\\n    assert svc.is_public_job(job_id) is True\\n\\n\\ndef test_job_queue_service_unregistered_job_not_public():\\n    \\\"\\\"\\\"A job_id that was never registered is not considered public.\\\"\\\"\\\"\\n    svc = JobQueueService()\\n    assert svc.is_public_job(str(uuid.uuid4())) is False\\n\\n\\nasync def test_job_queue_service_is_public_job_async_base():\\n    \\\"\\\"\\\"is_public_job_async on base class delegates to in-memory is_public_job.\\\"\\\"\\\"\\n    svc = JobQueueService()\\n    job_id = str(uuid.uuid4())\\n\\n    # Why: async variant must mirror sync variant \u2014 False before, True after\\n    assert await svc.is_public_job_async(job_id) is False\\n    await svc.register_public_job(job_id)\\n    assert await svc.is_public_job_async(job_id) is True\\n\\n\\nasync def test_job_queue_service_cleanup_removes_public_registration():\\n    \\\"\\\"\\\"cleanup_job discards the public registration so the job_id cannot be reused.\\n\\n    Why: tests the actual cleanup_job contract \u2014 not the internal set.\\n    If cleanup_job stops calling discard, this test must catch it.\\n    \\\"\\\"\\\"\\n    svc = JobQueueService()\\n    job_id = str(uuid.uuid4())\\n    await svc.register_public_job(job_id)\\n    assert svc.is_public_job(job_id) is True\\n\\n    # Call the real cleanup path \u2014 not svc._public_jobs.discard directly.\\n    # cleanup_job early-returns when job_id is not in _queues, but the\\n    # _public_jobs.discard call is unconditional (after the early-return guard),\\n    # so we need to reach it. Seed a minimal queue entry first.\\n    svc._queues[job_id] = (asyncio.Queue(), None, None, None)  # type: ignore[arg-type]\\n    await svc.cleanup_job(job_id)\\n\\n    # Why: if cleanup_job ever drops the discard call, is_public_job still returns True here\\n    assert svc.is_public_job(job_id) is False\\n\\n\\n@pytest.mark.security\\nasync def test_public_events_failure_has_fixed_wire_detail_and_logs_original(client, monkeypatch):\\n    \\\"\\\"\\\"An internal public-events failure is logged server-side but never reflected to an anonymous caller.\\\"\\\"\\\"\\n    import langflow.api.v1.chat as chat_module\\n    from fastapi import HTTPException\\n    from langflow.services.deps import get_queue_service\\n\\n    job_id = str(uuid.uuid4())\\n    secret_detail = \\\"redis backend failed with credential=owner-secret\\\"  # noqa: S105  # pragma: allowlist secret\\n    queue_service = get_queue_service()\\n    await queue_service.register_public_job(job_id)\\n    log_error = AsyncMock()\\n\\n    async def fail_events(**_kwargs):\\n        raise HTTPException(status_code=500, detail=secret_detail)\\n\\n    monkeypatch.setattr(chat_module, \\\"get_flow_events_response\\\", fail_events)\\n    monkeypatch.setattr(chat_module, \\\"logger\\\", SimpleNamespace(aerror=log_error))\\n    try:\\n        response = await client.get(f\\\"api/v1/build_public_tmp/{job_id}/events?event_delivery=polling\\\")\\n    finally:\\n        queue_service._public_jobs.discard(job_id)\\n\\n    assert response.status_code == codes.INTERNAL_SERVER_ERROR\\n    assert response.json() == {\\\"detail\\\": \\\"Public flow events are unavailable.\\\"}\\n    assert secret_detail not in response.text\\n    assert secret_detail in str(log_error.await_args)\\n\\n\\n@pytest.mark.security\\n@pytest.mark.parametrize(\\n    (\\\"failure\\\", \\\"expected_status\\\", \\\"expected_detail\\\", \\\"log_method\\\"),\\n    [\\n        (ValueError(\\\"owner queue id leaked\\\"), codes.NOT_FOUND, \\\"Job not found\\\", \\\"awarning\\\"),\\n        (\\n            RuntimeError(\\\"redis credential owner-secret\\\"),  # pragma: allowlist secret\\n            codes.INTERNAL_SERVER_ERROR,\\n            \\\"Public flow cancellation failed.\\\",\\n            \\\"aexception\\\",\\n        ),\\n    ],\\n)\\nasync def test_public_cancel_failure_has_fixed_wire_detail_and_logs_original(\\n    client,\\n    monkeypatch,\\n    failure,\\n    expected_status,\\n    expected_detail,\\n    log_method,\\n):\\n    \\\"\\\"\\\"Public cancellation maps internal failures to fixed details while retaining diagnostics in logs.\\\"\\\"\\\"\\n    import langflow.api.v1.chat as chat_module\\n    from langflow.services.deps import get_queue_service\\n\\n    job_id = str(uuid.uuid4())\\n    queue_service = get_queue_service()\\n    await queue_service.register_public_job(job_id)\\n    log = AsyncMock()\\n    logger = SimpleNamespace(awarning=AsyncMock(), aexception=AsyncMock())\\n    setattr(logger, log_method, log)\\n\\n    async def fail_cancel(**_kwargs):\\n        raise failure\\n\\n    monkeypatch.setattr(chat_module, \\\"cancel_flow_build\\\", fail_cancel)\\n    monkeypatch.setattr(chat_module, \\\"logger\\\", logger)\\n    try:\\n        response = await client.post(f\\\"api/v1/build_public_tmp/{job_id}/cancel\\\")\\n    finally:\\n        queue_service._public_jobs.discard(job_id)\\n\\n    assert response.status_code == expected_status\\n    assert response.json() == {\\\"detail\\\": expected_detail}\\n    assert str(failure) not in response.text\\n    assert str(failure) in str(log.await_args)\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_private_job_id_blocked_on_public_events_endpoint(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"A job_id started via the authenticated build endpoint must be rejected by the public events endpoint.\\n\\n    Security proof: before the fix, any caller who knew or guessed a private job_id\\n    could read the live event stream (LLM output, API keys, tracebacks) without auth.\\n    After the fix, _assert_public_job returns HTTP 404 because the job was never\\n    registered via register_public_job.\\n\\n    Why 404 not 403: returning 403 would confirm the job exists under a different\\n    access tier, leaking information about private builds.\\n    \\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Start a PRIVATE (authenticated) build \u2014 job_id never passed through build_public_tmp\\n    private_start = await client.post(\\n        f\\\"api/v1/build/{flow_id}/flow\\\",\\n        json={},\\n        headers={**logged_in_headers, \\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert private_start.status_code == codes.OK\\n    private_job_id = private_start.json()[\\\"job_id\\\"]\\n\\n    # Why: the shared AsyncClient persists access-token cookies from logged_in_headers.\\n    # Without clearing them, get_current_user_optional could resolve a user on this\\n    # \\\"public\\\" request, which would not exercise the unauthenticated attack path.\\n    client.cookies.clear()\\n\\n    # Attempt to read the private job's events via the unauthenticated public endpoint\\n    # Why: this is the exact attack vector \u2014 attacker has job_id, tries public endpoint\\n    events_response = await client.get(\\n        f\\\"api/v1/build_public_tmp/{private_job_id}/events?event_delivery=polling\\\",\\n        headers={\\\"Accept\\\": \\\"application/x-ndjson\\\"},\\n    )\\n\\n    # Must be 404 \u2014 gate blocks private job from public endpoint\\n    assert events_response.status_code == codes.NOT_FOUND\\n    assert events_response.json()[\\\"detail\\\"] == \\\"Job not found\\\"\\n\\n\\n@pytest.mark.benchmark\\n@pytest.mark.security\\nasync def test_private_job_id_blocked_on_public_cancel_endpoint(client, json_memory_chatbot_no_llm, logged_in_headers):\\n    \\\"\\\"\\\"A job_id started via the authenticated build endpoint must be rejected by the public cancel endpoint.\\n\\n    Security proof: before the fix, an unauthenticated attacker could cancel any\\n    in-flight private build as a denial-of-service by supplying a known job_id.\\n    After the fix, _assert_public_job returns HTTP 404.\\n    \\\"\\\"\\\"\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    # Start a PRIVATE (authenticated) build\\n    private_start = await client.post(\\n        f\\\"api/v1/build/{flow_id}/flow\\\",\\n        json={},\\n        headers={**logged_in_headers, \\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert private_start.status_code == codes.OK\\n    private_job_id = private_start.json()[\\\"job_id\\\"]\\n\\n    # Why: the shared AsyncClient persists access-token cookies from logged_in_headers.\\n    # Without clearing them, get_current_user_optional could resolve a user on this\\n    # \\\"public\\\" request, which would not exercise the unauthenticated attack path.\\n    client.cookies.clear()\\n\\n    # Attempt to cancel the private job via the unauthenticated public endpoint\\n    cancel_response = await client.post(\\n        f\\\"api/v1/build_public_tmp/{private_job_id}/cancel\\\",\\n        headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n\\n    # Must be 404 \u2014 gate blocks private job from public cancel endpoint\\n    assert cancel_response.status_code == codes.NOT_FOUND\\n    assert cancel_response.json()[\\\"detail\\\"] == \\\"Job not found\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_cli.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b261b7e2631d772275ff87b5ab48324683758dc8e0035a9e6b569dc0b45f1f24\",\"content\":\"import socket\\nimport threading\\nimport time\\nfrom types import SimpleNamespace\\nfrom unittest.mock import patch\\n\\nimport pytest\\nimport typer\\nfrom langflow.__main__ import (\\n    DIRECT_UVICORN_PLATFORMS,\\n    MULTI_WORKER_BYPASS_ENV_VAR,\\n    _create_superuser,\\n    api_key_banner,\\n    app,\\n    build_direct_uvicorn_kwargs,\\n    clamp_uvicorn_workers,\\n    ensure_multi_worker_safe,\\n    get_number_of_workers,\\n    multi_worker_bypass_warning,\\n    use_direct_uvicorn,\\n)\\nfrom lfx.services import deps\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef default_settings():\\n    return [\\n        \\\"--backend-only\\\",\\n        \\\"--no-open-browser\\\",\\n    ]\\n\\n\\ndef get_free_port():\\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\\n        s.bind((\\\"\\\", 0))\\n        return s.getsockname()[1]\\n\\n\\ndef run_flow(runner, port, components_path, default_settings):\\n    args = [\\n        \\\"run\\\",\\n        \\\"--port\\\",\\n        str(port),\\n        \\\"--components-path\\\",\\n        str(components_path),\\n        *default_settings,\\n    ]\\n    result = runner.invoke(app, args)\\n    if result.exit_code != 0:\\n        msg = f\\\"CLI failed with exit code {result.exit_code}: {result.output}\\\"\\n        raise RuntimeError(msg)\\n\\n\\ndef test_components_path(runner, default_settings, tmp_path):\\n    # create a \\\"components\\\" folder\\n    temp_dir = tmp_path / \\\"components\\\"\\n    temp_dir.mkdir(exist_ok=True)\\n\\n    port = get_free_port()\\n\\n    thread = threading.Thread(\\n        target=run_flow,\\n        args=(runner, port, temp_dir, default_settings),\\n        daemon=True,\\n    )\\n    thread.start()\\n\\n    # Give the server some time to start\\n    time.sleep(5)\\n\\n    settings_service = deps.get_settings_service()\\n    assert str(temp_dir) in settings_service.settings.components_path\\n\\n\\n@pytest.mark.xdist_group(name=\\\"serial-superuser-tests\\\")\\nclass TestSuperuserCommand:\\n    \\\"\\\"\\\"Deterministic tests for the superuser CLI command.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_additional_superuser_requires_auth_production(self, client, active_super_user):  # noqa: ARG002\\n        \\\"\\\"\\\"Test additional superuser creation requires authentication in production.\\\"\\\"\\\"\\n        # We already have active_super_user from the fixture, so we're not in first setup\\n        with (\\n            patch(\\\"langflow.services.deps.get_settings_service\\\") as mock_settings,\\n            patch(\\\"langflow.__main__.get_settings_service\\\") as mock_settings2,\\n        ):\\n            # Configure settings for production mode (AUTO_LOGIN=False)\\n            mock_auth_settings = type(\\\"MockAuthSettings\\\", (), {\\\"AUTO_LOGIN\\\": False, \\\"ENABLE_SUPERUSER_CLI\\\": True})()\\n            mock_settings.return_value.auth_settings = mock_auth_settings\\n            mock_settings2.return_value.auth_settings = mock_auth_settings\\n\\n            # Try to create a superuser without auth - should fail\\n            with pytest.raises(typer.Exit) as exc_info:\\n                await _create_superuser(\\\"newuser\\\", \\\"newpass\\\", None)\\n\\n            assert exc_info.value.exit_code == 1\\n\\n    @pytest.mark.asyncio\\n    async def test_additional_superuser_blocked_in_auto_login_mode(self, client, active_super_user):  # noqa: ARG002\\n        \\\"\\\"\\\"Test additional superuser creation blocked when AUTO_LOGIN=true.\\\"\\\"\\\"\\n        # We already have active_super_user from the fixture, so we're not in first setup\\n        with (\\n            patch(\\\"langflow.services.deps.get_settings_service\\\") as mock_settings,\\n            patch(\\\"langflow.__main__.get_settings_service\\\") as mock_settings2,\\n        ):\\n            # Configure settings for AUTO_LOGIN mode\\n            mock_auth_settings = type(\\\"MockAuthSettings\\\", (), {\\\"AUTO_LOGIN\\\": True, \\\"ENABLE_SUPERUSER_CLI\\\": True})()\\n            mock_settings.return_value.auth_settings = mock_auth_settings\\n            mock_settings2.return_value.auth_settings = mock_auth_settings\\n\\n            # Try to create a superuser - should fail\\n            with pytest.raises(typer.Exit) as exc_info:\\n                await _create_superuser(\\\"newuser\\\", \\\"newpass\\\", None)\\n\\n            assert exc_info.value.exit_code == 1\\n\\n    @pytest.mark.asyncio\\n    async def test_cli_disabled_blocks_creation(self, client):  # noqa: ARG002\\n        \\\"\\\"\\\"Test ENABLE_SUPERUSER_CLI=false blocks superuser creation.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"langflow.services.deps.get_settings_service\\\") as mock_settings,\\n            patch(\\\"langflow.__main__.get_settings_service\\\") as mock_settings2,\\n        ):\\n            mock_auth_settings = type(\\\"MockAuthSettings\\\", (), {\\\"AUTO_LOGIN\\\": True, \\\"ENABLE_SUPERUSER_CLI\\\": False})()\\n            mock_settings.return_value.auth_settings = mock_auth_settings\\n            mock_settings2.return_value.auth_settings = mock_auth_settings\\n\\n            # Try to create a superuser - should fail\\n            with pytest.raises(typer.Exit) as exc_info:\\n                await _create_superuser(\\\"admin\\\", \\\"password\\\", None)\\n\\n            assert exc_info.value.exit_code == 1\\n\\n    @pytest.mark.skip(reason=\\\"Skip -- default superuser is created by initialize_services() function\\\")\\n    @pytest.mark.asyncio\\n    async def test_auto_login_uses_bootstrap_superuser(self, client):\\n        \\\"\\\"\\\"Test AUTO_LOGIN=true bootstraps the configured superuser.\\\"\\\"\\\"\\n        # Since client fixture already creates default user, we need to test in a clean DB scenario\\n        # But that's why this test is skipped - the behavior is already handled by initialize_services\\n\\n    @pytest.mark.asyncio\\n    async def test_failed_auth_token_validation(self, client, active_super_user):  # noqa: ARG002\\n        \\\"\\\"\\\"Test failed superuser creation with invalid auth token.\\\"\\\"\\\"\\n        # We already have active_super_user from the fixture, so we're not in first setup\\n        with (\\n            patch(\\\"langflow.services.deps.get_settings_service\\\") as mock_settings,\\n            patch(\\\"langflow.__main__.get_settings_service\\\") as mock_settings2,\\n            patch(\\\"langflow.__main__.get_current_user_from_access_token\\\", side_effect=Exception(\\\"Invalid token\\\")),\\n            patch(\\\"langflow.__main__.check_key\\\", return_value=None),\\n        ):\\n            # Configure settings for production mode (AUTO_LOGIN=False)\\n            mock_auth_settings = type(\\\"MockAuthSettings\\\", (), {\\\"AUTO_LOGIN\\\": False, \\\"ENABLE_SUPERUSER_CLI\\\": True})()\\n            mock_settings.return_value.auth_settings = mock_auth_settings\\n            mock_settings2.return_value.auth_settings = mock_auth_settings\\n\\n            # Try to create a superuser with invalid token - should fail\\n            with pytest.raises(typer.Exit) as exc_info:\\n                await _create_superuser(\\\"newuser\\\", \\\"newpass\\\", \\\"invalid-token\\\")\\n\\n            assert exc_info.value.exit_code == 1\\n\\n\\ndef test_get_number_of_workers():\\n    \\\"\\\"\\\"Test that get_number_of_workers uses cpu_count on Linux.\\\"\\\"\\\"\\n    with (\\n        patch(\\\"langflow.__main__.platform.system\\\", return_value=\\\"Linux\\\"),\\n        patch(\\\"langflow.__main__.cpu_count\\\", return_value=4),\\n    ):\\n        # Test default behavior (None)\\n        workers = get_number_of_workers(None)\\n        assert workers == (4 * 2) + 1  # 9 workers\\n\\n        # Test explicit value is respected\\n        workers = get_number_of_workers(2)\\n        assert workers == 2\\n\\n\\n# ---------------------------------------------------------------------------\\n# Platform routing for `langflow run` startup.\\n#\\n# These tests pin the policy that on Windows and macOS we bypass Gunicorn and\\n# run uvicorn directly against a pre-built app object, while on Linux we use\\n# Gunicorn (which forks workers). Also pins the worker-clamp behaviour, which\\n# exists because uvicorn refuses to spawn multiple workers from an app object\\n# (it requires an import string).\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"system\\\", \\\"expected\\\"),\\n    [\\n        (\\\"Darwin\\\", True),\\n        (\\\"Windows\\\", True),\\n        (\\\"Linux\\\", False),\\n        (\\\"FreeBSD\\\", False),\\n    ],\\n)\\ndef test_use_direct_uvicorn_routes_by_platform(system, expected):\\n    assert use_direct_uvicorn(system=system) is expected\\n\\n\\ndef test_direct_uvicorn_platforms_constant_is_stable():\\n    # Guards against accidental drift; the launch site relies on this exact set.\\n    assert DIRECT_UVICORN_PLATFORMS == (\\\"Windows\\\", \\\"Darwin\\\")\\n\\n\\n@pytest.mark.parametrize(\\\"system\\\", [\\\"Darwin\\\", \\\"Windows\\\"])\\ndef test_clamp_uvicorn_workers_caps_to_one_on_direct_uvicorn(system):\\n    \\\"\\\"\\\"Workers > 1 must be clamped to 1 with a warning on direct-uvicorn platforms.\\\"\\\"\\\"\\n    # langflow uses loguru, not stdlib logging \u2014 patch the logger method\\n    # directly rather than relying on caplog.\\n    with patch(\\\"langflow.__main__.logger\\\") as mock_logger:\\n        assert clamp_uvicorn_workers(4, system=system) == 1\\n    mock_logger.warning.assert_called_once()\\n    # The warning should mention what we clamped and why, so users can\\n    # diagnose `langflow run --workers N` regressing to a single worker.\\n    fmt, *args = mock_logger.warning.call_args.args\\n    assert \\\"workers > 1\\\" in fmt, f\\\"warning did not explain the clamp: {fmt!r}\\\"\\n    assert system in args, f\\\"warning did not mention platform={system}: args={args!r}\\\"\\n    assert 4 in args, f\\\"warning did not include the requested worker count: args={args!r}\\\"\\n\\n\\ndef test_clamp_uvicorn_workers_passes_through_on_linux():\\n    # Linux uses Gunicorn \u2014 no clamping should happen here.\\n    assert clamp_uvicorn_workers(4, system=\\\"Linux\\\") == 4\\n\\n\\n@pytest.mark.parametrize(\\\"system\\\", [\\\"Darwin\\\", \\\"Windows\\\", \\\"Linux\\\"])\\ndef test_clamp_uvicorn_workers_one_is_noop(system):\\n    assert clamp_uvicorn_workers(1, system=system) == 1\\n\\n\\n# ---------------------------------------------------------------------------\\n# Direct-uvicorn kwargs shape.\\n#\\n# These pin the option set passed to ``uvicorn.run(app, **kwargs)`` on the\\n# Windows/macOS path. They exist because the previous inline call silently\\n# dropped TLS cert/key options, regressing HTTPS startup. Treat any field\\n# omission as a behaviour change and update the test deliberately.\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _kwargs(**overrides):\\n    \\\"\\\"\\\"Build ``build_direct_uvicorn_kwargs`` arguments with sensible defaults.\\\"\\\"\\\"\\n    base = {\\n        \\\"host\\\": \\\"0.0.0.0\\\",  # noqa: S104\\n        \\\"port\\\": 7860,\\n        \\\"log_level\\\": \\\"info\\\",\\n        \\\"workers\\\": 1,\\n        \\\"loop\\\": \\\"asyncio\\\",\\n        \\\"ssl_cert_file_path\\\": None,\\n        \\\"ssl_key_file_path\\\": None,\\n        \\\"system\\\": \\\"Darwin\\\",\\n    }\\n    base.update(overrides)\\n    return base\\n\\n\\ndef test_build_direct_uvicorn_kwargs_forwards_tls_paths():\\n    \\\"\\\"\\\"TLS cert/key must reach uvicorn under uvicorn's ``ssl_certfile``/``ssl_keyfile`` names.\\\"\\\"\\\"\\n    result = build_direct_uvicorn_kwargs(\\n        **_kwargs(ssl_cert_file_path=\\\"/etc/cert.pem\\\", ssl_key_file_path=\\\"/etc/key.pem\\\")\\n    )\\n    assert result[\\\"ssl_certfile\\\"] == \\\"/etc/cert.pem\\\"\\n    assert result[\\\"ssl_keyfile\\\"] == \\\"/etc/key.pem\\\"\\n\\n\\ndef test_build_direct_uvicorn_kwargs_starts_each_request_task_from_a_clean_context():\\n    \\\"\\\"\\\"Direct-uvicorn startup must opt into uvicorn's per-request context reset.\\n\\n    Same reason as ``LangflowUvicornWorker.CONFIG_KWARGS`` on the Gunicorn path: a pipelined\\n    request is started from inside the finishing request's task, and the copied context\\n    otherwise carries that request's ended server span into the new one, which OpenTelemetry\\n    reports as nesting. Kept on both paths so platform parity does not drift.\\n\\n    Asserted through a real ``uvicorn.Config`` so a renamed or rejected option fails here.\\n    \\\"\\\"\\\"\\n    import uvicorn\\n\\n    config = uvicorn.Config(\\\"langflow.main:create_app\\\", **build_direct_uvicorn_kwargs(**_kwargs()))\\n\\n    assert config.reset_contextvars is True\\n\\n\\ndef test_build_direct_uvicorn_kwargs_forwards_none_when_no_tls():\\n    # Plain HTTP startup: cert/key remain None so uvicorn doesn't try to load anything.\\n    result = build_direct_uvicorn_kwargs(**_kwargs())\\n    assert result[\\\"ssl_certfile\\\"] is None\\n    assert result[\\\"ssl_keyfile\\\"] is None\\n\\n\\ndef test_build_direct_uvicorn_kwargs_clamps_workers_on_direct_platforms():\\n    result = build_direct_uvicorn_kwargs(**_kwargs(workers=4, system=\\\"Darwin\\\"))\\n    assert result[\\\"workers\\\"] == 1\\n\\n\\ndef test_build_direct_uvicorn_kwargs_does_not_clamp_on_linux():\\n    # Defensive: the helper is only called from the direct-uvicorn branch, but\\n    # if it ever gets reused on Linux the clamp must remain a no-op there.\\n    result = build_direct_uvicorn_kwargs(**_kwargs(workers=4, system=\\\"Linux\\\"))\\n    assert result[\\\"workers\\\"] == 4\\n\\n\\n# ---------------------------------------------------------------------------\\n# api_key_banner: clipboard must be best-effort.\\n#\\n# Regression guard for #12341: pyperclip raises in headless/Docker/SSH\\n# environments because no clipboard mechanism is available. The banner must\\n# still print the API key (the only time it's ever shown) instead of crashing.\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_api_key_banner_survives_pyperclip_failure(capsys):\\n    \\\"\\\"\\\"Clipboard failure must not crash the banner \u2014 the key is the user's only copy.\\\"\\\"\\\"\\n    api_key_obj = SimpleNamespace(api_key=\\\"lf-test-12341\\\")\\n\\n    with patch(\\\"pyperclip.copy\\\", side_effect=Exception(\\\"Pyperclip could not find a copy/paste mechanism\\\")):\\n        api_key_banner(api_key_obj)\\n\\n    output = capsys.readouterr().out\\n    assert \\\"lf-test-12341\\\" in output, \\\"API key must still be displayed when clipboard fails\\\"\\n    assert \\\"clipboard\\\" not in output.lower(), \\\"no clipboard hint should appear when copy failed\\\"\\n\\n\\ndef test_api_key_banner_shows_clipboard_hint_on_success(capsys):\\n    \\\"\\\"\\\"Happy path: when clipboard copy succeeds, the paste hint is shown.\\\"\\\"\\\"\\n    api_key_obj = SimpleNamespace(api_key=\\\"lf-test-ok\\\")\\n\\n    with patch(\\\"pyperclip.copy\\\") as mock_copy:\\n        api_key_banner(api_key_obj)\\n\\n    mock_copy.assert_called_once_with(\\\"lf-test-ok\\\")\\n    output = capsys.readouterr().out\\n    assert \\\"lf-test-ok\\\" in output\\n    assert \\\"clipboard\\\" in output.lower()\\n\\n\\ndef test_build_direct_uvicorn_kwargs_pins_full_shape():\\n    \\\"\\\"\\\"Drift guard: the exact key set passed to uvicorn.run must stay stable.\\\"\\\"\\\"\\n    result = build_direct_uvicorn_kwargs(**_kwargs())\\n    # If uvicorn options change deliberately, update this set explicitly so\\n    # reviewers see the diff.\\n    assert set(result.keys()) == {\\n        \\\"host\\\",\\n        \\\"port\\\",\\n        \\\"log_level\\\",\\n        \\\"reload\\\",\\n        \\\"workers\\\",\\n        \\\"loop\\\",\\n        \\\"ssl_certfile\\\",\\n        \\\"ssl_keyfile\\\",\\n        \\\"forwarded_allow_ips\\\",\\n        \\\"reset_contextvars\\\",\\n    }\\n    assert result[\\\"reload\\\"] is False\\n\\n\\n# ---------------------------------------------------------------------------\\n# ensure_multi_worker_safe: refuse to boot with the in-memory queue and N>1\\n# workers. The bug is silent: ~45-66% of build polls return \\\"Job not found\\\"\\n# because Gunicorn round-robins the POST and the follow-up GET across workers,\\n# but the queue is worker-local.\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_ensure_multi_worker_safe_allows_single_worker():\\n    \\\"\\\"\\\"Single worker means no cross-worker routing; must not raise.\\\"\\\"\\\"\\n    ensure_multi_worker_safe(num_workers=1)\\n\\n\\ndef _settings_service_with_queue(queue_type: str, *, bypass: bool = False) -> SimpleNamespace:\\n    return SimpleNamespace(\\n        settings=SimpleNamespace(\\n            job_queue_type=queue_type,\\n            dangerously_allow_multi_worker_without_shared_queue=bypass,\\n        )\\n    )\\n\\n\\ndef test_ensure_multi_worker_safe_refuses_multiple_workers():\\n    \\\"\\\"\\\"Default in-memory queue + workers > 1 must refuse to start.\\\"\\\"\\\"\\n    with (\\n        patch(\\\"langflow.__main__.get_settings_service\\\", return_value=_settings_service_with_queue(\\\"asyncio\\\")),\\n        pytest.raises(RuntimeError) as exc_info,\\n    ):\\n        ensure_multi_worker_safe(num_workers=3)\\n\\n    msg = str(exc_info.value)\\n    assert \\\"3 workers\\\" in msg\\n    assert \\\"in-memory job queue\\\" in msg\\n\\n\\ndef test_ensure_multi_worker_safe_error_lists_workarounds():\\n    \\\"\\\"\\\"Error must point operators at concrete fixes, not just describe the bug.\\\"\\\"\\\"\\n    with (\\n        patch(\\\"langflow.__main__.get_settings_service\\\", return_value=_settings_service_with_queue(\\\"asyncio\\\")),\\n        pytest.raises(RuntimeError) as exc_info,\\n    ):\\n        ensure_multi_worker_safe(num_workers=3)\\n\\n    msg = str(exc_info.value)\\n    # Shared queue is the proper fix for any event_delivery mode.\\n    assert \\\"LANGFLOW_JOB_QUEUE_TYPE=redis\\\" in msg\\n    # Single worker sidesteps cross-worker routing entirely.\\n    assert \\\"--workers 1\\\" in msg\\n    # event_delivery=direct works but cannot be enforced at startup, so it's a\\n    # note, not a \\\"pick one of\\\" option \u2014 call that out explicitly.\\n    assert \\\"event_delivery=direct\\\" in msg\\n\\n\\ndef test_ensure_multi_worker_safe_allows_redis_queue():\\n    \\\"\\\"\\\"Redis-backed job queue shares state across workers; multi-worker is safe.\\\"\\\"\\\"\\n    with patch(\\\"langflow.__main__.get_settings_service\\\", return_value=_settings_service_with_queue(\\\"redis\\\")):\\n        ensure_multi_worker_safe(num_workers=4)\\n\\n\\n# ---------------------------------------------------------------------------\\n# ensure_multi_worker_safe: LANGFLOW_DANGEROUSLY_ALLOW_MULTI_WORKER_WITHOUT_SHARED_QUEUE\\n# turns the refusal into a loud warning. The flag does not make multi-worker\\n# safe \u2014 it only lets a headless deployment that never touches the UI or MCP\\n# over SSE trade those features for worker throughput without standing up Redis.\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _capture_startup_warnings(monkeypatch) -> list[str]:\\n    \\\"\\\"\\\"Record ``logger.warning`` calls made by ``langflow.__main__``.\\n\\n    ``logger`` is a structlog BoundLogger that may be filtered out entirely at\\n    the configured level, so asserting on caplog would make the test depend on\\n    log configuration. Swapping the module-level symbol for a recorder captures\\n    exactly what the guard emits.\\n    \\\"\\\"\\\"\\n    captured: list[str] = []\\n\\n    class _Recorder:\\n        def warning(self, msg: str, *args: object, **_kwargs: object) -> None:\\n            captured.append(msg % args if args else msg)\\n\\n        def __getattr__(self, _name: str):  # pragma: no cover - swallow other levels\\n            return lambda *_a, **_k: None\\n\\n    import langflow.__main__ as langflow_main\\n\\n    monkeypatch.setattr(langflow_main, \\\"logger\\\", _Recorder())\\n    return captured\\n\\n\\ndef test_ensure_multi_worker_safe_bypass_allows_multiple_workers(monkeypatch):\\n    \\\"\\\"\\\"The opt-in flag must let the in-memory queue boot with workers > 1.\\\"\\\"\\\"\\n    _capture_startup_warnings(monkeypatch)\\n    with patch(\\n        \\\"langflow.__main__.get_settings_service\\\",\\n        return_value=_settings_service_with_queue(\\\"asyncio\\\", bypass=True),\\n    ):\\n        ensure_multi_worker_safe(num_workers=4)\\n\\n\\ndef test_ensure_multi_worker_safe_bypass_warns_about_ui_and_mcp_sse(monkeypatch):\\n    \\\"\\\"\\\"Booting under the bypass must name the two features it breaks outright.\\\"\\\"\\\"\\n    warnings = _capture_startup_warnings(monkeypatch)\\n    with patch(\\n        \\\"langflow.__main__.get_settings_service\\\",\\n        return_value=_settings_service_with_queue(\\\"asyncio\\\", bypass=True),\\n    ):\\n        ensure_multi_worker_safe(num_workers=4)\\n\\n    assert len(warnings) == 1\\n    msg = warnings[0]\\n    # The operator must be able to tie a broken editor/playground back to this flag.\\n    assert \\\"/build\\\" in msg\\n    assert \\\"playground\\\" in msg\\n    # MCP over SSE needs the stream and its POST endpoint in one process; the\\n    # warning has to point at the transport that does work.\\n    assert \\\"SSE\\\" in msg\\n    assert \\\"Streamable HTTP\\\" in msg\\n    # ...and it must still name the supported alternative.\\n    assert \\\"LANGFLOW_JOB_QUEUE_TYPE=redis\\\" in msg\\n    # The flag that caused this is named so the config is greppable.\\n    assert MULTI_WORKER_BYPASS_ENV_VAR in msg\\n\\n\\ndef test_multi_worker_bypass_warning_lists_the_degraded_subsystems():\\n    \\\"\\\"\\\"Every subsystem that silently degrades to per-worker must be spelled out.\\n\\n    These are not startup failures \u2014 they are behaviors that quietly change\\n    meaning under multiple workers, so the boot warning is the only place an\\n    operator learns about them.\\n    \\\"\\\"\\\"\\n    from langflow.services.background_execution.live_bus import _DURABLE_POLL_INTERVAL_S\\n\\n    msg = multi_worker_bypass_warning(num_workers=4)\\n\\n    # Reattach falls back to polling the durable log; quote the real interval so\\n    # the warning cannot drift from the constant the bus actually uses.\\n    assert str(_DURABLE_POLL_INTERVAL_S) in msg\\n    # Rate limits are counted per worker unless the storage URI is shared.\\n    assert \\\"LANGFLOW_RATE_LIMIT_STORAGE_URI\\\" in msg\\n    # The orphan-sweep lock is a file lock, so it is node-local, not cluster-wide.\\n    assert \\\"orphan-sweep\\\" in msg\\n    # Webhook UI feedback needs the browser and the request on the same worker.\\n    assert \\\"Webhook\\\" in msg\\n    assert \\\"4 workers\\\" in msg\\n\\n\\ndef test_ensure_multi_worker_safe_redis_never_warns_even_with_bypass_set(monkeypatch):\\n    \\\"\\\"\\\"A Redis queue is safe; a stale bypass flag must not produce scary output.\\n\\n    Redis short-circuits before the bypass is consulted, so a correctly\\n    configured deployment that leaves the flag set in its environment sees\\n    nothing at all.\\n    \\\"\\\"\\\"\\n    warnings = _capture_startup_warnings(monkeypatch)\\n    with patch(\\n        \\\"langflow.__main__.get_settings_service\\\",\\n        return_value=_settings_service_with_queue(\\\"redis\\\", bypass=True),\\n    ):\\n        ensure_multi_worker_safe(num_workers=4)\\n\\n    assert warnings == []\\n\\n\\ndef test_ensure_multi_worker_safe_bypass_off_still_refuses(monkeypatch):\\n    \\\"\\\"\\\"The flag is opt-in: the default must keep refusing to boot.\\\"\\\"\\\"\\n    warnings = _capture_startup_warnings(monkeypatch)\\n    with (\\n        patch(\\n            \\\"langflow.__main__.get_settings_service\\\",\\n            return_value=_settings_service_with_queue(\\\"asyncio\\\", bypass=False),\\n        ),\\n        pytest.raises(RuntimeError),\\n    ):\\n        ensure_multi_worker_safe(num_workers=4)\\n\\n    assert warnings == []\\n\\n\\ndef test_ensure_multi_worker_safe_error_points_at_the_bypass_flag():\\n    \\\"\\\"\\\"The refusal must tell headless operators the escape hatch exists.\\\"\\\"\\\"\\n    with (\\n        patch(\\\"langflow.__main__.get_settings_service\\\", return_value=_settings_service_with_queue(\\\"asyncio\\\")),\\n        pytest.raises(RuntimeError) as exc_info,\\n    ):\\n        ensure_multi_worker_safe(num_workers=3)\\n\\n    assert MULTI_WORKER_BYPASS_ENV_VAR in str(exc_info.value)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_cli_command_plugins.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4203f6d6615dd93333bb64fdd22573984caeffae8ae565313defdf15aaf27347\",\"content\":\"\\\"\\\"\\\"Integration coverage for CLI command plugins on the Langflow root app.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib\\nfrom dataclasses import dataclass\\nfrom typing import Any\\n\\nimport typer\\nfrom lfx.cli import command_plugins\\nfrom typer.testing import CliRunner\\n\\n\\n@dataclass\\nclass _FakeEntryPoint:\\n    name: str\\n    value: str\\n    target: Any\\n\\n    def load(self) -> Any:\\n        return self.target\\n\\n\\ndef test_langflow_root_app_registers_discovered_plugin_commands(monkeypatch):\\n    import langflow.__main__ as langflow_main\\n\\n    def register(app: typer.Typer) -> None:\\n        @app.command(name=\\\"fixture-plugin\\\")\\n        def fixture_plugin() -> None:\\n            typer.echo(\\\"langflow plugin\\\")\\n\\n    entry_point = _FakeEntryPoint(\\\"fixture\\\", \\\"plugins.fixture:register\\\", register)\\n\\n    with monkeypatch.context() as scoped_patch:\\n        scoped_patch.setattr(\\n            command_plugins.metadata,\\n            \\\"entry_points\\\",\\n            lambda *, group: [entry_point] if group == \\\"langflow.cli_commands\\\" else [],\\n        )\\n        reloaded_main = importlib.reload(langflow_main)\\n        result = CliRunner().invoke(reloaded_main.app, [\\\"fixture-plugin\\\"])\\n\\n    importlib.reload(langflow_main)\\n\\n    assert result.exit_code == 0\\n    assert result.output == \\\"langflow plugin\\\\n\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_cli_preflight.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ddaa5e7319377b84c2b93a46d46b9365f1098b3e10ba6cda7daa0ae89c467d24\",\"content\":\"\\\"\\\"\\\"Unit tests for the production deployment preflight checks.\\n\\nCovers the individual probes, the runner semantics (collect-all, severity\\ninvariant, abort decision), and the ``deployment_profile`` setting.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport os\\nimport tempfile\\n\\nimport pytest\\nfrom cryptography.fernet import Fernet\\nfrom langflow.cli import preflight\\nfrom langflow.cli.preflight import (\\n    PREFLIGHT_COMPLETED_ENV,\\n    CheckOutcome,\\n    CheckResult,\\n    PreflightAbortError,\\n    PreflightCheck,\\n    collect_outcomes,\\n    ensure_production_preflight,\\n    probe_cache,\\n    probe_database,\\n    probe_pgvector,\\n    probe_secret_key,\\n    probe_shared_queue,\\n    probe_storage,\\n    probe_telemetry,\\n    run_production_preflight,\\n    summarize,\\n)\\nfrom langflow.services.storage.service import StorageReadiness\\nfrom lfx.services.settings.groups.server import ServerSettings\\n\\n\\nclass _StubSettings:\\n    def __init__(self, **overrides):\\n        defaults = {\\n            # 127.0.0.1:1 refuses immediately -> a fast \\\"unreachable\\\" for DB tests.\\n            # URL built at runtime so secret-scanners do not flag a literal credential.\\n            \\\"database_url\\\": \\\"postgresql://user:{}@127.0.0.1:1/nope\\\".format(\\\"testpw\\\"),\\n            \\\"storage_type\\\": \\\"local\\\",\\n            \\\"object_storage_bucket_name\\\": \\\"bucket\\\",\\n            \\\"object_storage_prefix\\\": \\\"files\\\",\\n            \\\"object_storage_tags\\\": None,\\n            \\\"config_dir\\\": tempfile.gettempdir(),\\n            \\\"do_not_track\\\": False,\\n            \\\"cache_type\\\": \\\"async\\\",\\n            \\\"job_queue_type\\\": \\\"asyncio\\\",\\n            \\\"deployment_profile\\\": \\\"prod\\\",\\n        }\\n        defaults.update(overrides)\\n        for key, value in defaults.items():\\n            setattr(self, key, value)\\n\\n\\nclass _StubService:\\n    def __init__(self, **overrides):\\n        self.settings = _StubSettings(**overrides)\\n\\n\\n# ---------------------------------------------------------------------------\\n# deployment_profile setting\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_deployment_profile_default_is_dev():\\n    assert ServerSettings().deployment_profile == \\\"dev\\\"\\n\\n\\n@pytest.mark.parametrize((\\\"raw\\\", \\\"expected\\\"), [(\\\"prod\\\", \\\"prod\\\"), (\\\"PROD\\\", \\\"prod\\\"), (\\\"  Dev \\\", \\\"dev\\\")])\\ndef test_deployment_profile_normalized(raw, expected):\\n    assert ServerSettings(deployment_profile=raw).deployment_profile == expected\\n\\n\\ndef test_deployment_profile_rejects_invalid():\\n    with pytest.raises(ValueError, match=\\\"deployment_profile\\\"):\\n        ServerSettings(deployment_profile=\\\"staging\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Required checks\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"secret_key\\\",\\n    [\\n        pytest.param(\\\"a\\\" * 31, id=\\\"short-derived-key\\\"),\\n        pytest.param(Fernet.generate_key().decode(), id=\\\"fernet-key\\\"),\\n    ],\\n)\\nasync def test_secret_key_env_supplied_and_usable(monkeypatch, secret_key):\\n    monkeypatch.setenv(\\\"LANGFLOW_SECRET_KEY\\\", secret_key)\\n    result = await probe_secret_key(_StubService())\\n    assert result.status == \\\"ok\\\"\\n    assert \\\"operator-supplied\\\" in result.detail\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"secret_key\\\",\\n    [\\n        pytest.param(\\\"a\\\" * 32, id=\\\"invalid-32-characters\\\"),\\n        pytest.param(\\\"x\\\" * 40, id=\\\"invalid-40-characters\\\"),\\n    ],\\n)\\nasync def test_secret_key_env_supplied_but_unusable_fails(monkeypatch, secret_key):\\n    monkeypatch.setenv(\\\"LANGFLOW_SECRET_KEY\\\", secret_key)\\n    result = await probe_secret_key(_StubService())\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"Fernet key must be 32 url-safe base64-encoded bytes\\\" in result.detail\\n    assert \\\"Fernet.generate_key()\\\" in result.remediation\\n\\n\\nasync def test_secret_key_file_only_fails(monkeypatch, tmp_path):\\n    monkeypatch.delenv(\\\"LANGFLOW_SECRET_KEY\\\", raising=False)\\n    (tmp_path / \\\"secret_key\\\").write_text(\\\"persisted\\\")\\n    result = await probe_secret_key(_StubService(config_dir=str(tmp_path)))\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"node-local\\\" in result.detail\\n\\n\\nasync def test_secret_key_missing_fails(monkeypatch, tmp_path):\\n    monkeypatch.delenv(\\\"LANGFLOW_SECRET_KEY\\\", raising=False)\\n    result = await probe_secret_key(_StubService(config_dir=str(tmp_path)))\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"auto-generated\\\" in result.detail\\n\\n\\nasync def test_pgvector_unset_fails(monkeypatch):\\n    monkeypatch.delenv(\\\"PGVECTOR_CONNECTION_STRING\\\", raising=False)\\n    result = await probe_pgvector(_StubService())\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"PGVECTOR_CONNECTION_STRING\\\" in result.detail\\n\\n\\nasync def test_database_unreachable_fails():\\n    result = await probe_database(_StubService())\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"could not connect\\\" in result.detail\\n    # DSN password must never leak into the rendered detail.\\n    assert \\\"secret\\\" not in result.detail\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"database_url\\\",\\n    [\\n        \\\"sqlite:///./langflow.db\\\",\\n        \\\"sqlite+aiosqlite:///./langflow.db\\\",\\n    ],\\n)\\nasync def test_database_sqlite_rejected_in_prod(database_url):\\n    # SQLite must be rejected before any connection is attempted (fast, no network).\\n    result = await probe_database(_StubService(database_url=database_url))\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"PostgreSQL\\\" in result.detail\\n    # It is a pre-connection rejection, not a reachability failure.\\n    assert \\\"could not connect\\\" not in result.detail\\n\\n\\nasync def test_database_missing_url_fails():\\n    result = await probe_database(_StubService(database_url=\\\"\\\"))\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"no database configured\\\" in result.detail\\n\\n\\nasync def test_storage_local_fails_in_prod():\\n    result = await probe_storage(_StubService(storage_type=\\\"local\\\"))\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"local filesystem storage is not allowed\\\" in result.detail\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"storage_type\\\",\\n    [\\n        \\\"gcs\\\",  # unsupported backend\\n        \\\"s3 \\\",  # supported name with a stray trailing space\\n        \\\"S3\\\\t\\\",  # supported name with stray whitespace\\n        \\\"s33\\\",  # typo\\n    ],\\n)\\nasync def test_storage_unrecognized_type_fails_in_prod(storage_type):\\n    # The real StorageServiceFactory silently returns LocalStorageService for any\\n    # unrecognized type; the probe must fail loud instead of reporting the local\\n    # config_dir as a writable external store. No factory monkeypatch here \u2014 this\\n    # exercises the actual fallback path.\\n    result = await probe_storage(_StubService(storage_type=storage_type))\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"unsupported storage backend\\\" in result.detail\\n    assert storage_type in result.detail\\n\\n\\nasync def test_storage_external_ok_via_factory(monkeypatch):\\n    class _FakeStorage:\\n        async def check_readiness(self):\\n            return StorageReadiness(ok=True, backend=\\\"s3\\\", detail=\\\"bucket reachable (b)\\\")\\n\\n        async def teardown(self):\\n            return None\\n\\n    from langflow.services.storage.factory import StorageServiceFactory\\n\\n    monkeypatch.setattr(StorageServiceFactory, \\\"create\\\", lambda *_a, **_k: _FakeStorage())\\n    result = await probe_storage(_StubService(storage_type=\\\"s3\\\"))\\n    assert result.status == \\\"ok\\\"\\n    assert \\\"s3\\\" in result.detail\\n\\n\\nasync def test_storage_external_failure_maps_reason(monkeypatch):\\n    class _FakeStorage:\\n        async def check_readiness(self):\\n            return StorageReadiness(ok=False, backend=\\\"s3\\\", detail=\\\"no creds\\\", reason=\\\"no-credentials\\\")\\n\\n        async def teardown(self):\\n            return None\\n\\n    from langflow.services.storage.factory import StorageServiceFactory\\n\\n    monkeypatch.setattr(StorageServiceFactory, \\\"create\\\", lambda *_a, **_k: _FakeStorage())\\n    result = await probe_storage(_StubService(storage_type=\\\"s3\\\"))\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"credentials\\\" in result.remediation.lower()\\n\\n\\n# ---------------------------------------------------------------------------\\n# Degraded checks (warn only)\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_telemetry_enabled_ok():\\n    assert (await probe_telemetry(_StubService(do_not_track=False))).status == \\\"ok\\\"\\n\\n\\nasync def test_telemetry_disabled_warns():\\n    result = await probe_telemetry(_StubService(do_not_track=True))\\n    assert result.status == \\\"warn\\\"\\n\\n\\nasync def test_cache_in_memory_warns():\\n    result = await probe_cache(_StubService(cache_type=\\\"async\\\"))\\n    assert result.status == \\\"warn\\\"\\n    assert \\\"single-instance\\\" in result.detail\\n\\n\\nasync def test_shared_queue_asyncio_warns():\\n    result = await probe_shared_queue(_StubService(job_queue_type=\\\"asyncio\\\"))\\n    assert result.status == \\\"warn\\\"\\n    assert \\\"per-pod\\\" in result.detail\\n\\n\\n# ---------------------------------------------------------------------------\\n# External backend selected but unreachable -> hard fail (aborts boot)\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_cache_redis_unreachable_fails(monkeypatch):\\n    from langflow.services.cache.factory import CacheServiceFactory\\n    from langflow.services.cache.service import RedisCache\\n\\n    class _Client:\\n        async def ping(self):\\n            msg = \\\"no redis\\\"\\n            raise ConnectionError(msg)\\n\\n        async def aclose(self):\\n            return None\\n\\n    fake = RedisCache.__new__(RedisCache)\\n    fake._client = _Client()\\n    monkeypatch.setattr(CacheServiceFactory, \\\"create\\\", lambda *_a, **_k: fake)\\n\\n    result = await probe_cache(_StubService(cache_type=\\\"redis\\\"))\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"unset LANGFLOW_CACHE_TYPE\\\" in result.remediation\\n\\n\\nasync def test_cache_redis_reachable_ok(monkeypatch):\\n    from langflow.services.cache.factory import CacheServiceFactory\\n    from langflow.services.cache.service import RedisCache\\n\\n    class _Client:\\n        async def ping(self):\\n            return True\\n\\n        async def aclose(self):\\n            return None\\n\\n    fake = RedisCache.__new__(RedisCache)\\n    fake._client = _Client()\\n    monkeypatch.setattr(CacheServiceFactory, \\\"create\\\", lambda *_a, **_k: fake)\\n\\n    result = await probe_cache(_StubService(cache_type=\\\"redis\\\"))\\n    assert result.status == \\\"ok\\\"\\n\\n\\nasync def test_shared_queue_redis_unreachable_fails(monkeypatch):\\n    from langflow.services.job_queue.factory import JobQueueServiceFactory\\n    from langflow.services.job_queue.service import RedisJobQueueService\\n\\n    async def _not_connected(_self, *_a, **_k):\\n        return False\\n\\n    fake = RedisJobQueueService.__new__(RedisJobQueueService)\\n    monkeypatch.setattr(RedisJobQueueService, \\\"is_connected\\\", _not_connected)\\n    monkeypatch.setattr(RedisJobQueueService, \\\"connection_target\\\", property(lambda _self: \\\"localhost:6379 db=1\\\"))\\n    monkeypatch.setattr(JobQueueServiceFactory, \\\"create\\\", lambda *_a, **_k: fake)\\n\\n    result = await probe_shared_queue(_StubService(job_queue_type=\\\"redis\\\"))\\n    assert result.status == \\\"fail\\\"\\n    assert \\\"unset LANGFLOW_JOB_QUEUE_TYPE\\\" in result.remediation\\n\\n\\nasync def test_shared_queue_redis_reachable_ok(monkeypatch):\\n    from langflow.services.job_queue.factory import JobQueueServiceFactory\\n    from langflow.services.job_queue.service import RedisJobQueueService\\n\\n    async def _connected(_self, *_a, **_k):\\n        return True\\n\\n    fake = RedisJobQueueService.__new__(RedisJobQueueService)\\n    monkeypatch.setattr(RedisJobQueueService, \\\"is_connected\\\", _connected)\\n    monkeypatch.setattr(RedisJobQueueService, \\\"connection_target\\\", property(lambda _self: \\\"localhost:6379 db=1\\\"))\\n    monkeypatch.setattr(JobQueueServiceFactory, \\\"create\\\", lambda *_a, **_k: fake)\\n\\n    result = await probe_shared_queue(_StubService(job_queue_type=\\\"redis\\\"))\\n    assert result.status == \\\"ok\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Runner semantics\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_degraded_returned_fail_is_preserved():\\n    \\\"\\\"\\\"A deliberate fail from a degraded check aborts (not downgraded).\\\"\\\"\\\"\\n\\n    async def _failing(_settings):\\n        return CheckResult(\\\"fail\\\", \\\"backend unreachable\\\")\\n\\n    check = PreflightCheck(\\\"x\\\", \\\"X\\\", \\\"degraded\\\", _failing)\\n    outcome = (await collect_outcomes(_StubService(), checks=[check]))[0]\\n    assert outcome.result.status == \\\"fail\\\"\\n\\n\\nasync def test_degraded_exception_downgraded_to_warn():\\n    \\\"\\\"\\\"An unexpected crash in a degraded check is downgraded to a warning.\\\"\\\"\\\"\\n\\n    async def _raising(_settings):\\n        msg = \\\"internal bug\\\"\\n        raise RuntimeError(msg)\\n\\n    check = PreflightCheck(\\\"x\\\", \\\"X\\\", \\\"degraded\\\", _raising)\\n    outcome = (await collect_outcomes(_StubService(), checks=[check]))[0]\\n    assert outcome.result.status == \\\"warn\\\"\\n\\n\\nasync def test_probe_exception_becomes_required_fail():\\n    async def _raising(_settings):\\n        msg = \\\"kaboom\\\"\\n        raise RuntimeError(msg)\\n\\n    check = PreflightCheck(\\\"x\\\", \\\"X\\\", \\\"required\\\", _raising)\\n    outcome = (await collect_outcomes(_StubService(), checks=[check]))[0]\\n    assert outcome.result.status == \\\"fail\\\"\\n    assert \\\"kaboom\\\" in outcome.result.detail\\n\\n\\nasync def test_collect_outcomes_runs_every_check():\\n    outcomes = await collect_outcomes(_StubService(), checks=preflight.ALL_CHECKS)\\n    assert len(outcomes) == len(preflight.ALL_CHECKS)\\n\\n\\ndef _outcome(severity: str, status: str) -> CheckOutcome:\\n    check = PreflightCheck(\\\"k\\\", \\\"K\\\", severity, None)  # type: ignore[arg-type]\\n    return CheckOutcome(check, CheckResult(status, \\\"d\\\"))\\n\\n\\ndef test_summarize_true_when_required_pass():\\n    outcomes = [_outcome(\\\"required\\\", \\\"ok\\\"), _outcome(\\\"degraded\\\", \\\"warn\\\")]\\n    assert summarize(outcomes) is True\\n\\n\\ndef test_summarize_false_when_required_fails():\\n    outcomes = [_outcome(\\\"required\\\", \\\"fail\\\"), _outcome(\\\"degraded\\\", \\\"warn\\\")]\\n    assert summarize(outcomes) is False\\n\\n\\ndef test_summarize_false_when_degraded_fails():\\n    # A degraded check that hard-fails (external backend unreachable) aborts too.\\n    outcomes = [_outcome(\\\"required\\\", \\\"ok\\\"), _outcome(\\\"degraded\\\", \\\"fail\\\")]\\n    assert summarize(outcomes) is False\\n\\n\\n# ---------------------------------------------------------------------------\\n# ensure_production_preflight: gating, sentinel guard, abort\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _clear_preflight_sentinel():\\n    \\\"\\\"\\\"Isolate each test from the process-tree sentinel + secret-key env.\\n\\n    ``ensure_production_preflight`` writes the sentinel straight to ``os.environ``\\n    (not via ``monkeypatch``), so ``monkeypatch`` cannot roll it back and it would\\n    otherwise bleed into other modules under parallel ``make unit_tests`` and\\n    silently no-op any later preflight run. The teardown here pops it as a safety\\n    net and asserts no leak. The assertion is order-independent because every test\\n    that sets the sentinel clears it in its own ``try/finally`` (a test body always\\n    runs to completion before any fixture teardown); the assertion then catches any\\n    *future* test that forgets to.\\n    \\\"\\\"\\\"\\n    guarded = (\\\"LANGFLOW_SECRET_KEY\\\", \\\"PGVECTOR_CONNECTION_STRING\\\")\\n    saved = {key: os.environ.pop(key, None) for key in guarded}\\n    os.environ.pop(PREFLIGHT_COMPLETED_ENV, None)\\n    try:\\n        yield\\n    finally:\\n        leaked = os.environ.pop(PREFLIGHT_COMPLETED_ENV, None)\\n        # Restore the pre-test environment before asserting so a detected leak\\n        # does not also corrupt the next test.\\n        for key, value in saved.items():\\n            if value is None:\\n                os.environ.pop(key, None)\\n            else:\\n                os.environ[key] = value\\n        assert leaked is None, (\\n            f\\\"{PREFLIGHT_COMPLETED_ENV} leaked into os.environ; a test that runs the real preflight must \\\"\\n            \\\"clean it up in a try/finally (it is set via os.environ, not monkeypatch).\\\"\\n        )\\n\\n\\nasync def test_ensure_is_noop_in_dev(monkeypatch):\\n    called = False\\n\\n    async def _boom(_s):\\n        nonlocal called\\n        called = True\\n        return CheckResult(\\\"fail\\\", \\\"should not run\\\")\\n\\n    monkeypatch.setattr(preflight, \\\"REQUIRED_CHECKS\\\", [PreflightCheck(\\\"x\\\", \\\"X\\\", \\\"required\\\", _boom)])\\n    await ensure_production_preflight(_StubService(deployment_profile=\\\"dev\\\"))\\n    assert called is False\\n    assert PREFLIGHT_COMPLETED_ENV not in os.environ\\n\\n\\nasync def test_ensure_skips_when_sentinel_set(monkeypatch):\\n    called = False\\n\\n    async def _boom(_s):\\n        nonlocal called\\n        called = True\\n        return CheckResult(\\\"fail\\\", \\\"should not run\\\")\\n\\n    monkeypatch.setattr(preflight, \\\"REQUIRED_CHECKS\\\", [PreflightCheck(\\\"x\\\", \\\"X\\\", \\\"required\\\", _boom)])\\n    # Set the sentinel the same way production code does (a direct os.environ\\n    # write) and clear it in the test body's finally \u2014 which always runs before\\n    # any fixture teardown \u2014 so the leak-detection assertion stays order-independent.\\n    os.environ[PREFLIGHT_COMPLETED_ENV] = \\\"1\\\"\\n    try:\\n        # Would fail if it ran; sentinel must short-circuit it.\\n        await ensure_production_preflight(_StubService(deployment_profile=\\\"prod\\\"))\\n        assert called is False\\n    finally:\\n        os.environ.pop(PREFLIGHT_COMPLETED_ENV, None)\\n\\n\\nasync def test_ensure_raises_and_sets_sentinel_on_required_failure():\\n    try:\\n        with pytest.raises(PreflightAbortError):\\n            await ensure_production_preflight(_StubService(deployment_profile=\\\"prod\\\", storage_type=\\\"local\\\"))\\n        # Sentinel is set so forked workers do not repeat the (already-failed) run.\\n        assert os.environ.get(PREFLIGHT_COMPLETED_ENV) == \\\"1\\\"\\n    finally:\\n        # The sentinel is a real os.environ write, not a monkeypatch, so pop it\\n        # here or it leaks past this test into parallel workers' later modules.\\n        os.environ.pop(PREFLIGHT_COMPLETED_ENV, None)\\n\\n\\nasync def test_ensure_passes_when_required_ok(monkeypatch):\\n    async def _ok(_s):\\n        return CheckResult(\\\"ok\\\", \\\"fine\\\")\\n\\n    monkeypatch.setattr(preflight, \\\"REQUIRED_CHECKS\\\", [PreflightCheck(\\\"x\\\", \\\"X\\\", \\\"required\\\", _ok)])\\n    monkeypatch.setattr(preflight, \\\"DEGRADED_CHECKS\\\", [])\\n    try:\\n        # Should not raise.\\n        await ensure_production_preflight(_StubService(deployment_profile=\\\"prod\\\"))\\n        # The pass path also writes the sentinel so forked workers skip the rerun.\\n        assert os.environ.get(PREFLIGHT_COMPLETED_ENV) == \\\"1\\\"\\n    finally:\\n        # Written straight to os.environ (not monkeypatch), so pop it or it leaks.\\n        os.environ.pop(PREFLIGHT_COMPLETED_ENV, None)\\n\\n\\ndef test_run_production_preflight_returns_false_on_abort():\\n    try:\\n        assert run_production_preflight(_StubService(deployment_profile=\\\"prod\\\", storage_type=\\\"local\\\")) is False\\n    finally:\\n        # ensure_production_preflight (run under the hood) writes the sentinel to\\n        # os.environ directly; pop it so it does not leak into parallel workers.\\n        os.environ.pop(PREFLIGHT_COMPLETED_ENV, None)\\n\\n\\ndef test_run_production_preflight_noop_true_in_dev():\\n    assert run_production_preflight(_StubService(deployment_profile=\\\"dev\\\")) is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_code_hash.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cf3ad8bdc6baf7526b43dd7e5cdbd7d7f7bd7f966cdbac6fd7ccd53c1752c6f1\",\"content\":\"\\\"\\\"\\\"Test code hash and module metadata functionality.\\\"\\\"\\\"\\n\\nimport pytest\\nfrom langflow.interface.components import import_langflow_components\\n\\n\\n@pytest.mark.asyncio\\nasync def test_component_metadata_has_code_hash():\\n    \\\"\\\"\\\"Test that built-in components have valid module and code_hash metadata.\\\"\\\"\\\"\\n    result = await import_langflow_components()\\n    assert result is not None\\n    assert \\\"components\\\" in result\\n    assert len(result[\\\"components\\\"]) > 0\\n\\n    # Find first component to test\\n    sample_category = None\\n    sample_component = None\\n    for category, components in result[\\\"components\\\"].items():\\n        if components:\\n            sample_category = category\\n            sample_component = next(iter(components.values()))\\n            break\\n    assert sample_component is not None, \\\"No components found to test\\\"\\n\\n    # Test metadata presence - metadata should be in the 'metadata' sub-field\\n    assert \\\"metadata\\\" in sample_component, f\\\"Metadata field missing from component in {sample_category}\\\"\\n    # metadata = sample_component[\\\"metadata\\\"]\\n\\n    # assert \\\"module\\\" in metadata, f\\\"Module metadata missing from component in {sample_category}\\\"\\n    # assert \\\"code_hash\\\" in metadata, f\\\"Code hash metadata missing from component in {sample_category}\\\"\\n\\n    # Test that values are valid\\n    # module_name = metadata[\\\"module\\\"]\\n    # code_hash = metadata[\\\"code_hash\\\"]\\n    # assert isinstance(module_name, str), f\\\"Invalid module name type: {type(module_name)}\\\"\\n    # assert module_name, f\\\"Invalid module name: {module_name}\\\"\\n    # assert isinstance(code_hash, str), f\\\"Invalid code hash type: {type(code_hash)}\\\"\\n    # assert len(code_hash) == 12, f\\\"Invalid code hash: {code_hash} (should be 12 chars)\\\"\\n\\n\\n@pytest.mark.skip(reason=\\\"Skipping while metadata is not added\\\")\\nasync def test_code_hash_uniqueness():\\n    \\\"\\\"\\\"Test that different built-in components have different code hashes.\\\"\\\"\\\"\\n    result = await import_langflow_components()\\n    all_hashes = []\\n    for components in result[\\\"components\\\"].values():\\n        for comp in components.values():\\n            metadata = comp.get(\\\"metadata\\\", {})\\n            if metadata.get(\\\"code_hash\\\"):\\n                all_hashes.append(metadata[\\\"code_hash\\\"])\\n\\n    # Check that we have some components with metadata\\n    assert len(all_hashes) > 0, \\\"No components with code hashes found\\\"\\n    # Check that we have reasonable uniqueness in hashes\\n    unique_hashes = len(set(all_hashes))\\n    total_hashes = len(all_hashes)\\n    uniqueness_ratio = unique_hashes / total_hashes\\n    # Should have high uniqueness (most components have different code)\\n    # Adjusted threshold to 90% to account for legitimate code sharing between similar components\\n    assert uniqueness_ratio > 0.90, f\\\"Hash uniqueness too low: {uniqueness_ratio:.1%}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_credential_resolution.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"abb3381096536557883d7092f1b8c971783527ce4be19f6f1c53f1f132920898\",\"content\":\"\\\"\\\"\\\"Tests for credential resolution in the unified models system.\\n\\nBug: Desktop Global Variable OPENAI_API_KEY not injected at runtime.\\nWhen api_key parameter is None (Agent component default), get_api_key_for_provider\\nattempts a DB lookup before falling back to os.getenv(). A missing DB variable\\nmust use that fallback, while unexpected lookup failures must propagate instead\\nof silently downgrading to an environment credential.\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import patch\\nfrom uuid import uuid4\\n\\nfrom pydantic import SecretStr\\n\\n\\nclass TestGetApiKeyForProviderDbFallback:\\n    \\\"\\\"\\\"Tests for get_api_key_for_provider when api_key param is None (second path).\\\"\\\"\\\"\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.get_model_provider_variable_mapping\\\")\\n    @patch(\\\"lfx.base.models.unified_models.credentials.run_until_complete\\\")\\n    def test_should_fallback_to_env_when_db_lookup_finds_no_variable(self, mock_run, mock_mapping, monkeypatch):\\n        \\\"\\\"\\\"When the async database lookup finds no variable.\\n\\n        get_api_key_for_provider should fall back to os.getenv() instead of returning None.\\n        \\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        user_id = str(uuid4())\\n        mock_mapping.return_value = {\\\"OpenAI\\\": \\\"OPENAI_API_KEY\\\"}\\n        mock_run.return_value = None\\n\\n        monkeypatch.setenv(\\\"OPENAI_API_KEY\\\", \\\"sk-test-env-key\\\")\\n\\n        result = get_api_key_for_provider(user_id, \\\"OpenAI\\\", None)\\n\\n        assert result == \\\"sk-test-env-key\\\"\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.get_model_provider_variable_mapping\\\")\\n    @patch(\\\"lfx.base.models.unified_models.credentials.run_until_complete\\\")\\n    def test_should_fallback_to_env_when_db_lookup_returns_empty_string(self, mock_run, mock_mapping, monkeypatch):\\n        \\\"\\\"\\\"When decryption fails, get_variable returns empty string.\\n\\n        get_api_key_for_provider should fall back to os.getenv().\\n        \\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        user_id = str(uuid4())\\n        mock_mapping.return_value = {\\\"OpenAI\\\": \\\"OPENAI_API_KEY\\\"}\\n        mock_run.return_value = \\\"\\\"\\n\\n        monkeypatch.setenv(\\\"OPENAI_API_KEY\\\", \\\"sk-test-env-key\\\")\\n\\n        result = get_api_key_for_provider(user_id, \\\"OpenAI\\\", None)\\n\\n        assert result == \\\"sk-test-env-key\\\"\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.get_model_provider_variable_mapping\\\")\\n    @patch(\\\"lfx.base.models.unified_models.credentials.run_until_complete\\\")\\n    def test_should_fallback_to_env_when_variable_service_is_none(self, mock_run, mock_mapping, monkeypatch):\\n        \\\"\\\"\\\"When variable_service is None (service not available in thread context).\\n\\n        get_api_key_for_provider should fall back to os.getenv().\\n        \\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        user_id = str(uuid4())\\n        mock_mapping.return_value = {\\\"OpenAI\\\": \\\"OPENAI_API_KEY\\\"}\\n        mock_run.return_value = None\\n\\n        monkeypatch.setenv(\\\"OPENAI_API_KEY\\\", \\\"sk-test-env-key\\\")\\n\\n        result = get_api_key_for_provider(user_id, \\\"OpenAI\\\", None)\\n\\n        assert result == \\\"sk-test-env-key\\\"\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.get_model_provider_variable_mapping\\\")\\n    @patch(\\\"lfx.base.models.unified_models.credentials.run_until_complete\\\")\\n    def test_should_return_none_when_both_db_and_env_unavailable(self, mock_run, mock_mapping, monkeypatch):\\n        \\\"\\\"\\\"When both DB lookup and env var are unavailable, should return None.\\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        user_id = str(uuid4())\\n        mock_mapping.return_value = {\\\"OpenAI\\\": \\\"OPENAI_API_KEY\\\"}\\n        mock_run.return_value = None\\n\\n        monkeypatch.delenv(\\\"OPENAI_API_KEY\\\", raising=False)\\n\\n        result = get_api_key_for_provider(user_id, \\\"OpenAI\\\", None)\\n\\n        assert result is None\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.get_model_provider_variable_mapping\\\")\\n    @patch(\\\"lfx.base.models.unified_models.credentials.run_until_complete\\\")\\n    def test_should_return_db_value_when_db_lookup_succeeds(self, mock_run, mock_mapping):\\n        \\\"\\\"\\\"When DB lookup succeeds, should return the DB value (no env fallback needed).\\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        user_id = str(uuid4())\\n        mock_mapping.return_value = {\\\"OpenAI\\\": \\\"OPENAI_API_KEY\\\"}\\n        mock_run.return_value = \\\"sk-from-database\\\"\\n\\n        result = get_api_key_for_provider(user_id, \\\"OpenAI\\\", None)\\n\\n        assert result == \\\"sk-from-database\\\"\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.get_model_provider_variable_mapping\\\")\\n    @patch(\\\"lfx.base.models.unified_models.credentials.run_until_complete\\\")\\n    def test_should_unwrap_secretstr_from_db_lookup(self, mock_run, mock_mapping):\\n        \\\"\\\"\\\"DB credential variables are SecretStr and must be unwrapped before provider use.\\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        user_id = str(uuid4())\\n        mock_mapping.return_value = {\\\"OpenAI\\\": \\\"OPENAI_API_KEY\\\"}\\n        mock_run.return_value = SecretStr(\\\"sk-from-database\\\")\\n\\n        result = get_api_key_for_provider(user_id, \\\"OpenAI\\\", None)\\n\\n        assert result == \\\"sk-from-database\\\"\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.run_until_complete\\\")\\n    def test_should_unwrap_secretstr_from_explicit_variable_name_lookup(self, mock_run, monkeypatch):\\n        \\\"\\\"\\\"Explicit var-name inputs should resolve to the raw secret, not SecretStr's mask.\\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        user_id = str(uuid4())\\n        mock_run.return_value = SecretStr(\\\"sk-from-database\\\")\\n        monkeypatch.delenv(\\\"OPENAI_API_KEY\\\", raising=False)\\n\\n        result = get_api_key_for_provider(user_id, \\\"OpenAI\\\", \\\"OPENAI_API_KEY\\\")\\n\\n        assert result == \\\"sk-from-database\\\"\\n\\n    def test_should_unwrap_secretstr_literal_api_key(self):\\n        \\\"\\\"\\\"SecretStr inputs should be passed to provider clients as raw strings.\\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        result = get_api_key_for_provider(None, \\\"OpenAI\\\", SecretStr(\\\"sk-direct\\\"))\\n\\n        assert result == \\\"sk-direct\\\"\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.get_model_provider_variable_mapping\\\")\\n    def test_should_fallback_to_env_when_user_id_is_none(self, mock_mapping, monkeypatch):\\n        \\\"\\\"\\\"No user_id (lfx run) must still resolve credentials from os.environ.\\n\\n        Reproducer: a flow exported with empty api_key + load_from_db=False is executed\\n        via `lfx run`. user_id is None, api_key is empty/None \u2014 the function should still\\n        try the canonical env var (e.g. WATSONX_APIKEY) before giving up.\\n        \\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        mock_mapping.return_value = {\\\"IBM WatsonX\\\": \\\"WATSONX_APIKEY\\\"}\\n        monkeypatch.setenv(\\\"WATSONX_APIKEY\\\", \\\"shell-exported-key\\\")\\n\\n        result = get_api_key_for_provider(None, \\\"IBM WatsonX\\\", None)\\n\\n        assert result == \\\"shell-exported-key\\\"\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.get_model_provider_variable_mapping\\\")\\n    def test_should_return_none_when_user_id_none_and_env_unset(self, mock_mapping, monkeypatch):\\n        \\\"\\\"\\\"No user_id and no env var: nothing to return.\\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        mock_mapping.return_value = {\\\"IBM WatsonX\\\": \\\"WATSONX_APIKEY\\\"}\\n        monkeypatch.delenv(\\\"WATSONX_APIKEY\\\", raising=False)\\n\\n        result = get_api_key_for_provider(None, \\\"IBM WatsonX\\\", None)\\n\\n        assert result is None\\n\\n\\nclass TestExplicitVarNameDbPrecedence:\\n    \\\"\\\"\\\"A var-name api_key must resolve the user's DB global variable before env.\\n\\n    Production bug (P2): .env held an old/revoked OPENAI_API_KEY; the user added\\n    a valid key as a DB global variable via Settings \u2192 Global Variables. A flow's\\n    Agent (which resolves via load_from_db) used the valid DB key, but the\\n    Assistant resolved the api_key NAME env-first and authenticated with the\\n    revoked .env key \u2192 401. Global variables are per-user and encrypted; the\\n    env read silently bypassed that boundary.\\n    \\\"\\\"\\\"\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.run_until_complete\\\")\\n    def test_should_prefer_db_global_variable_over_env_for_explicit_var_name(self, mock_run, monkeypatch):\\n        user_id = str(uuid4())\\n        # The user's valid key, stored as a DB global variable (SecretStr).\\n        mock_run.return_value = SecretStr(\\\"sk-db-valid\\\")\\n        # The stale/revoked key in .env that must NOT win.\\n        monkeypatch.setenv(\\\"OPENAI_API_KEY\\\", \\\"sk-env-revoked\\\")\\n\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        result = get_api_key_for_provider(user_id, \\\"OpenAI\\\", \\\"OPENAI_API_KEY\\\")\\n\\n        assert result == \\\"sk-db-valid\\\"\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.run_until_complete\\\")\\n    def test_should_fallback_to_env_for_var_name_when_db_has_no_value(self, mock_run, monkeypatch):\\n        # Regression guard: DB-first must still fall back to env when the user\\n        # has no such DB variable (the value the .env provides is the only one).\\n        user_id = str(uuid4())\\n        mock_run.return_value = None\\n        monkeypatch.setenv(\\\"OPENAI_API_KEY\\\", \\\"sk-env-fallback\\\")\\n\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        result = get_api_key_for_provider(user_id, \\\"OpenAI\\\", \\\"OPENAI_API_KEY\\\")\\n\\n        assert result == \\\"sk-env-fallback\\\"\\n\\n    def test_should_use_env_for_var_name_when_no_user_id(self, monkeypatch):\\n        # lfx run (no user): no DB to consult, so the env var is the source.\\n        monkeypatch.setenv(\\\"OPENAI_API_KEY\\\", \\\"sk-env-only\\\")\\n\\n        from lfx.base.models.unified_models.credentials import get_api_key_for_provider\\n\\n        result = get_api_key_for_provider(None, \\\"OpenAI\\\", \\\"OPENAI_API_KEY\\\")\\n\\n        assert result == \\\"sk-env-only\\\"\\n\\n\\nclass TestGetAllVariablesForProviderDbFallback:\\n    \\\"\\\"\\\"Tests for get_all_variables_for_provider when DB lookup yields nothing.\\n\\n    Bug: Langflow Assistant rejects requests with\\n    `400 Missing required configuration for OpenAI: OPENAI_API_KEY` even when\\n    the env var is set, whenever a Variable row exists in the DB but its\\n    ciphertext was encrypted with a different SECRET_KEY (Fernet\\n    `InvalidToken`). `decrypt_api_key` swallows the exception and returns \\\"\\\".\\n    The current `_get_all_variables` only falls back to `os.environ` inside\\n    its `except` branch, so the empty-string return slips through and the\\n    required key is missing from the resulting dict.\\n    \\\"\\\"\\\"\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.get_provider_all_variables\\\")\\n    @patch(\\\"lfx.base.models.unified_models.credentials.run_until_complete\\\")\\n    def test_should_fallback_to_env_when_db_lookup_returns_empty_for_required_key(\\n        self, mock_run, mock_provider_vars, monkeypatch\\n    ):\\n        \\\"\\\"\\\"DB returned no usable value for OPENAI_API_KEY \u2192 env value must populate result.\\n\\n        The inner async function returns an empty dict when every\\n        `variable_service.get_variable(...)` call yields an empty value\\n        (decryption failed). The outer helper must then consult\\n        `os.environ` for the missing required keys, exactly mirroring the\\n        post-async env fallback used by `get_api_key_for_provider`.\\n        \\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_all_variables_for_provider\\n\\n        user_id = str(uuid4())\\n        mock_provider_vars.return_value = [{\\\"variable_key\\\": \\\"OPENAI_API_KEY\\\"}]\\n        # Decryption silently failed \u2192 inner loop produced an empty dict.\\n        mock_run.return_value = {}\\n\\n        monkeypatch.setenv(\\\"OPENAI_API_KEY\\\", \\\"sk-test-env-key\\\")\\n\\n        result = get_all_variables_for_provider(user_id, \\\"OpenAI\\\")\\n\\n        assert result == {\\\"OPENAI_API_KEY\\\": \\\"sk-test-env-key\\\"}\\n\\n    @patch(\\\"lfx.base.models.unified_models.credentials.get_provider_all_variables\\\")\\n    @patch(\\\"lfx.base.models.unified_models.credentials.run_until_complete\\\")\\n    def test_should_fallback_to_env_only_for_keys_missing_from_db(self, mock_run, mock_provider_vars, monkeypatch):\\n        \\\"\\\"\\\"Keys returned by DB win; env only fills the gaps for missing keys.\\n\\n        Guards against an over-broad fix that lets env values overwrite\\n        successfully decrypted DB values.\\n        \\\"\\\"\\\"\\n        from lfx.base.models.unified_models.credentials import get_all_variables_for_provider\\n\\n        user_id = str(uuid4())\\n        mock_provider_vars.return_value = [\\n            {\\\"variable_key\\\": \\\"OPENAI_API_KEY\\\"},\\n            {\\\"variable_key\\\": \\\"OPENAI_ORG_ID\\\"},\\n        ]\\n        mock_run.return_value = {\\\"OPENAI_API_KEY\\\": \\\"sk-from-db\\\"}\\n\\n        monkeypatch.setenv(\\\"OPENAI_API_KEY\\\", \\\"sk-from-env-should-not-win\\\")\\n        monkeypatch.setenv(\\\"OPENAI_ORG_ID\\\", \\\"org-from-env\\\")\\n\\n        result = get_all_variables_for_provider(user_id, \\\"OpenAI\\\")\\n\\n        assert result == {\\n            \\\"OPENAI_API_KEY\\\": \\\"sk-from-db\\\",\\n            \\\"OPENAI_ORG_ID\\\": \\\"org-from-env\\\",\\n        }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_credential_variable_leakage.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c78f1afdb2685e951cde49bfe8c9c4b5a8b0585683cd9054a18d67c2259113ef\",\"content\":\"\\\"\\\"\\\"Regression tests for https://github.com/langflow-ai/langflow/pull/12908.\\n\\nOriginal repro: a CREDENTIAL-typed global variable routed into a non-password\\ninput field (e.g. TextInputComponent.input_value, a MultilineInput) leaked the\\nraw value into the Component Output panel, traces, and logs.\\n\\nThese tests exercise the full chain that the bug touches:\\n  * `VariableService.get_variable` returns `pydantic.SecretStr` for CREDENTIAL\\n    variables (mocked here so the tests don't need a live DB).\\n  * `update_params_with_load_from_db_fields` propagates the SecretStr through\\n    variable resolution.\\n  * Field validators on text/numeric inputs reject SecretStr in non-password\\n    fields with an actionable error.\\n  * Component-level `_wrap_if_secret` keeps password-bound attributes wrapped\\n    so any stringification path (Message.text, status, traces, logs) renders\\n    `'**********'` instead of the secret.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport uuid\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom lfx.components.input_output import TextInputComponent\\nfrom lfx.custom import Component\\nfrom lfx.inputs.inputs import IntInput, SecretStrInput, StrInput\\nfrom lfx.interface.initialize.loading import update_params_with_load_from_db_fields\\nfrom lfx.io import Output\\nfrom lfx.schema.message import Message\\nfrom pydantic import SecretStr, ValidationError\\n\\n# Sentinel used as a stand-in for a \\\"real\\\" CREDENTIAL global variable's value.\\n# Tests assert this string never appears in error messages, attributes, or\\n# stringified output of any object derived from it.\\n_LEAKY_SECRET = \\\"super-secret-value-XYZ\\\"  # noqa: S105 \u2014 fixture sentinel.  # pragma: allowlist secret\\n\\n\\ndef _patch_resolution(get_variable_return):\\n    \\\"\\\"\\\"Wire up the minimum scaffolding around `update_params_with_load_from_db_fields`.\\n\\n    Returns a context-manager-ish tuple of (session_scope_patcher, settings_patcher,\\n    get_variable_async_mock). The settings patch ensures the loading module takes\\n    the DB path (not the noop env-var path).\\n    \\\"\\\"\\\"\\n    mock_session = MagicMock()\\n    mock_session.__aenter__ = AsyncMock(return_value=mock_session)\\n    mock_session.__aexit__ = AsyncMock(return_value=None)\\n\\n    session_patcher = patch(\\\"lfx.interface.initialize.loading.session_scope\\\")\\n    settings_patcher = patch(\\\"lfx.services.deps.get_settings_service\\\")\\n    get_variable_mock = AsyncMock(return_value=get_variable_return)\\n    return session_patcher, settings_patcher, mock_session, get_variable_mock\\n\\n\\nasync def _resolve(component, params, load_from_db_fields, get_variable_return):\\n    session_patcher, settings_patcher, mock_session, get_variable_mock = _patch_resolution(get_variable_return)\\n    component.get_variable = get_variable_mock\\n    with session_patcher as mock_session_scope, settings_patcher as mock_get_settings:\\n        mock_session_scope.return_value = mock_session\\n        mock_settings_service = MagicMock()\\n        mock_settings_service.settings.use_noop_database = False\\n        mock_get_settings.return_value = mock_settings_service\\n        return await update_params_with_load_from_db_fields(\\n            component, params, load_from_db_fields, fallback_to_env_vars=False\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_credential_variable_does_not_leak_into_text_input_output():\\n    \\\"\\\"\\\"A CREDENTIAL variable must not leak into text input output.\\n\\n    * keep the value wrapped as SecretStr through variable resolution\\n    * never surface the raw value via str()/repr()\\n    * fail Pydantic validation when assigned to the non-password field, with a\\n      clear error message that itself does not contain the secret\\n    \\\"\\\"\\\"\\n    component = TextInputComponent(_user_id=str(uuid.uuid4()))\\n\\n    resolved = await _resolve(\\n        component,\\n        params={\\\"input_value\\\": \\\"MY_SECRET_VAR\\\"},\\n        load_from_db_fields=[\\\"input_value\\\"],\\n        get_variable_return=SecretStr(_LEAKY_SECRET),\\n    )\\n\\n    # Variable resolution must preserve the SecretStr wrapper end-to-end.\\n    resolved_value = resolved[\\\"input_value\\\"]\\n    assert isinstance(resolved_value, SecretStr)\\n    assert resolved_value.get_secret_value() == _LEAKY_SECRET\\n    assert str(resolved_value) == \\\"**********\\\"\\n    assert _LEAKY_SECRET not in str(resolved_value)\\n    assert _LEAKY_SECRET not in repr(resolved_value)\\n\\n    # set_attributes routes through input validation; the non-password field rejects.\\n    with pytest.raises(ValidationError) as excinfo:\\n        component.set_attributes(resolved)\\n\\n    error_text = str(excinfo.value)\\n    assert \\\"Credential-typed global variable\\\" in error_text\\n    assert \\\"input_value\\\" in error_text\\n    # The error message itself must not echo the underlying secret.\\n    assert _LEAKY_SECRET not in error_text\\n\\n\\n@pytest.mark.asyncio\\nasync def test_credential_variable_in_password_field_preserves_runtime_string_contract():\\n    \\\"\\\"\\\"A CREDENTIAL variable in a password field remains usable as a string.\\n\\n    A CREDENTIAL global variable routed into a password (SecretStrInput) field\\n    is accepted. The runtime component attribute is unwrapped for compatibility\\n    with existing provider-client code, while component output/log boundaries\\n    still sanitize the recorded secret value.\\n    \\\"\\\"\\\"\\n\\n    class _PasswordFieldComponent(Component):\\n        display_name = \\\"PasswordFieldTest\\\"\\n        name = \\\"PasswordFieldTest\\\"\\n        inputs = [SecretStrInput(name=\\\"api_key\\\", display_name=\\\"API Key\\\")]\\n        outputs = [Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"build_output\\\")]\\n\\n        def build_output(self) -> Message:\\n            self.log(self.api_key)\\n            self.status = self.api_key\\n            return Message(text=self.api_key)\\n\\n    component = _PasswordFieldComponent(_user_id=str(uuid.uuid4()))\\n\\n    resolved = await _resolve(\\n        component,\\n        params={\\\"api_key\\\": \\\"MY_SECRET_VAR\\\"},  # pragma: allowlist secret\\n        load_from_db_fields=[\\\"api_key\\\"],\\n        get_variable_return=SecretStr(_LEAKY_SECRET),\\n    )\\n\\n    component.set_attributes(resolved)\\n    api_key_attr = component._attributes[\\\"api_key\\\"]\\n\\n    assert api_key_attr == _LEAKY_SECRET\\n    assert component.api_key == _LEAKY_SECRET\\n\\n    results, artifacts = await component._build_results()\\n\\n    assert results[\\\"output\\\"].text == \\\"**********\\\"\\n    assert results[\\\"output\\\"].data[\\\"text\\\"] == \\\"**********\\\"\\n    assert artifacts[\\\"output\\\"][\\\"raw\\\"] == \\\"**********\\\"\\n    assert \\\"**********\\\" in artifacts[\\\"output\\\"][\\\"repr\\\"]\\n    assert _LEAKY_SECRET not in artifacts[\\\"output\\\"][\\\"repr\\\"]\\n    assert component._output_logs[\\\"output\\\"][0].message == \\\"**********\\\"\\n    assert component.status == \\\"**********\\\"\\n    assert component.repr_value == \\\"**********\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_secret_inputs_are_redacted_at_tracing_boundary_by_field_metadata():\\n    \\\"\\\"\\\"Secret input metadata, not field-name guesses, controls trace redaction.\\\"\\\"\\\"\\n\\n    class _TraceSecretsComponent(Component):\\n        display_name = \\\"TraceSecretsTest\\\"\\n        name = \\\"TraceSecretsTest\\\"\\n        inputs = [\\n            SecretStrInput(name=\\\"aws_secret_access_key\\\", display_name=\\\"AWS Secret Access Key\\\"),\\n            SecretStrInput(name=\\\"access_token\\\", display_name=\\\"Access Token\\\"),\\n            IntInput(name=\\\"token_budget\\\", display_name=\\\"Token Budget\\\"),\\n            StrInput(name=\\\"region\\\", display_name=\\\"Region\\\"),\\n        ]\\n        outputs = [Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"build_output\\\")]\\n\\n        def build_output(self) -> str:\\n            return self.region\\n\\n    # This test exercises trace redaction, not provider credential discovery.\\n    # Keep construction from starting the synchronous provider-variable bridge\\n    # while pytest's event loop is already running.\\n    with patch(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\", return_value={}):\\n        component = _TraceSecretsComponent(_user_id=str(uuid.uuid4()))\\n        component.set_attributes(\\n            {\\n                \\\"aws_secret_access_key\\\": \\\"aws-secret-sentinel\\\",  # pragma: allowlist secret\\n                \\\"access_token\\\": \\\"token-secret-sentinel\\\",  # pragma: allowlist secret\\n                \\\"token_budget\\\": 4096,\\n                \\\"region\\\": \\\"us-west-2\\\",\\n            }\\n        )\\n\\n    tracing_service = MagicMock()\\n    trace_context = MagicMock()\\n    trace_context.__aenter__ = AsyncMock(return_value=tracing_service)\\n    trace_context.__aexit__ = AsyncMock(return_value=None)\\n    tracing_service.trace_component.return_value = trace_context\\n    component._tracing_service = tracing_service\\n\\n    await component._build_with_tracing()\\n\\n    traced_inputs = tracing_service.trace_component.call_args.args[2]\\n    assert traced_inputs == {\\n        \\\"aws_secret_access_key\\\": \\\"**********\\\",\\n        \\\"access_token\\\": \\\"**********\\\",\\n        \\\"token_budget\\\": 4096,\\n        \\\"region\\\": \\\"us-west-2\\\",\\n    }\\n\\n\\n@pytest.mark.asyncio\\nasync def test_generic_variable_still_flows_into_text_input():\\n    \\\"\\\"\\\"GENERIC-typed variables must still flow into text input.\\n\\n    Variables returned as plain str by VariableService must continue to work in\\n    non-password fields. Only CREDENTIAL-typed (SecretStr) values are blocked.\\n    \\\"\\\"\\\"\\n    plain_value = \\\"non-sensitive-display-name\\\"\\n    component = TextInputComponent(_user_id=str(uuid.uuid4()))\\n\\n    resolved = await _resolve(\\n        component,\\n        params={\\\"input_value\\\": \\\"MY_GENERIC_VAR\\\"},\\n        load_from_db_fields=[\\\"input_value\\\"],\\n        get_variable_return=plain_value,\\n    )\\n\\n    component.set_attributes(resolved)\\n    assert component._attributes[\\\"input_value\\\"] == plain_value\\n\\n\\n@pytest.mark.asyncio\\nasync def test_credential_variable_accepted_when_use_global_variable_toggled_on():\\n    \\\"\\\"\\\"Credential variable is accepted when 'Use Global Variable' toggle is on.\\n\\n    Toggling on TextInput re-types `input_value` via `update_build_config` to\\n    `password=True, multiline=False`. A CREDENTIAL-typed variable must then be\\n    accepted by validation, since the field is now a secret field. The original\\n    bug: validation rejected it regardless of `password`, because\\n    `MultilineInput` declares `password` after the inherited `value` field, so\\n    the field-level check on `value` ran before `password` was populated in\\n    `info.data`.\\n    \\\"\\\"\\\"\\n    from lfx.inputs.inputs import MultilineInput\\n\\n    field = MultilineInput(name=\\\"input_value\\\", value=SecretStr(_LEAKY_SECRET), password=True)\\n    assert isinstance(field.value, SecretStr)\\n    assert field.value.get_secret_value() == _LEAKY_SECRET\\n\\n    # And: with password=False (default), the same value is rejected.\\n    with pytest.raises(ValidationError) as excinfo:\\n        MultilineInput(name=\\\"input_value\\\", value=SecretStr(_LEAKY_SECRET))\\n    assert \\\"Credential-typed global variable\\\" in str(excinfo.value)\\n    assert \\\"input_value\\\" in str(excinfo.value)\\n    assert _LEAKY_SECRET not in str(excinfo.value)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_custom_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a959faea0dacdb841f2a3ff4aa1accbe7ba810aa274e62e643735bb60907a641\",\"content\":\"import ast\\nimport types\\nfrom pathlib import Path\\nfrom textwrap import dedent\\n\\nimport pytest\\nfrom langchain_core.documents import Document\\nfrom lfx.custom import Component, CustomComponent\\nfrom lfx.custom.code_parser.code_parser import CodeParser, CodeSyntaxError\\nfrom lfx.custom.custom_component.base_component import BaseComponent, ComponentCodeNullError\\nfrom lfx.custom.utils import build_custom_component_template\\n\\n\\n@pytest.fixture\\ndef code_component_with_multiple_outputs():\\n    path = Path(__file__).parent.parent / \\\"data\\\" / \\\"component_multiple_outputs.py\\\"\\n    code = path.read_text(encoding=\\\"utf-8\\\")\\n    return Component(_code=code)\\n\\n\\ncode_default = \\\"\\\"\\\"\\nfrom langflow.custom import CustomComponent\\n\\nfrom lfx.field_typing import BaseLanguageModel\\nfrom langchain_classic.chains import LLMChain\\nfrom langchain_core.prompts import PromptTemplate\\nfrom langchain_core.documents import Document\\n\\nimport requests\\n\\nclass YourComponent(CustomComponent):\\n    display_name: str = \\\"Your Component\\\"\\n    description: str = \\\"Your description\\\"\\n    field_config = { \\\"url\\\": { \\\"multiline\\\": True, \\\"required\\\": True } }\\n\\n    def build(self, url: str, llm: BaseLanguageModel) -> Document:\\n        return Document(page_content=\\\"Hello World\\\")\\n\\\"\\\"\\\"\\n\\n\\ndef test_code_parser_init():\\n    \\\"\\\"\\\"Test the initialization of the CodeParser class.\\\"\\\"\\\"\\n    parser = CodeParser(code_default)\\n    assert parser.code == code_default\\n\\n\\ndef test_code_parser_get_tree():\\n    \\\"\\\"\\\"Test the __get_tree method of the CodeParser class.\\\"\\\"\\\"\\n    parser = CodeParser(code_default)\\n    tree = parser.get_tree()\\n    assert isinstance(tree, ast.AST)\\n\\n\\ndef test_code_parser_syntax_error():\\n    \\\"\\\"\\\"Test the __get_tree method raises the CodeSyntaxError when given incorrect syntax.\\\"\\\"\\\"\\n    code_syntax_error = \\\"zzz import os\\\"\\n\\n    parser = CodeParser(code_syntax_error)\\n    with pytest.raises(CodeSyntaxError):\\n        parser.get_tree()\\n\\n\\ndef test_component_init():\\n    \\\"\\\"\\\"Test the initialization of the Component class.\\\"\\\"\\\"\\n    component = BaseComponent(_code=code_default, _function_entrypoint_name=\\\"build\\\")\\n    assert component._code == code_default\\n    assert component._function_entrypoint_name == \\\"build\\\"\\n\\n\\ndef test_component_get_code_tree():\\n    \\\"\\\"\\\"Test the get_code_tree method of the Component class.\\\"\\\"\\\"\\n    component = BaseComponent(_code=code_default, _function_entrypoint_name=\\\"build\\\")\\n    tree = component.get_code_tree(component._code)\\n    assert \\\"imports\\\" in tree\\n\\n\\ndef test_component_code_null_error():\\n    \\\"\\\"\\\"Test the get_function method raises the ComponentCodeNullError when the code is empty.\\\"\\\"\\\"\\n    component = BaseComponent(_code=\\\"\\\", _function_entrypoint_name=\\\"\\\")\\n    with pytest.raises(ComponentCodeNullError):\\n        component.get_function()\\n\\n\\ndef test_custom_component_init():\\n    \\\"\\\"\\\"Test the initialization of the CustomComponent class.\\\"\\\"\\\"\\n    function_entrypoint_name = \\\"build\\\"\\n\\n    custom_component = CustomComponent(_code=code_default, _function_entrypoint_name=function_entrypoint_name)\\n    assert custom_component._code == code_default\\n    assert custom_component._function_entrypoint_name == function_entrypoint_name\\n\\n\\ndef test_custom_component_build_template_config():\\n    \\\"\\\"\\\"Test the build_template_config property of the CustomComponent class.\\\"\\\"\\\"\\n    custom_component = CustomComponent(_code=code_default, _function_entrypoint_name=\\\"build\\\")\\n    config = custom_component.build_template_config()\\n    assert isinstance(config, dict)\\n\\n\\ndef test_custom_component_get_function():\\n    \\\"\\\"\\\"Test the get_function property of the CustomComponent class.\\\"\\\"\\\"\\n    custom_component = CustomComponent(_code=\\\"def build(): pass\\\", _function_entrypoint_name=\\\"build\\\")\\n    my_function = custom_component.get_function()\\n    assert isinstance(my_function, types.FunctionType)\\n\\n\\ndef test_code_parser_parse_imports_import():\\n    \\\"\\\"\\\"Test the parse_imports method of the CodeParser class with an import statement.\\\"\\\"\\\"\\n    parser = CodeParser(code_default)\\n    tree = parser.get_tree()\\n    for node in ast.walk(tree):\\n        if isinstance(node, ast.Import):\\n            parser.parse_imports(node)\\n    assert \\\"requests\\\" in parser.data[\\\"imports\\\"]\\n\\n\\ndef test_code_parser_parse_imports_importfrom():\\n    \\\"\\\"\\\"Test the parse_imports method of the CodeParser class with an import from statement.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"from os import path\\\")\\n    tree = parser.get_tree()\\n    for node in ast.walk(tree):\\n        if isinstance(node, ast.ImportFrom):\\n            parser.parse_imports(node)\\n    assert (\\\"os\\\", \\\"path\\\") in parser.data[\\\"imports\\\"]\\n\\n\\ndef test_code_parser_parse_functions():\\n    \\\"\\\"\\\"Test the parse_functions method of the CodeParser class.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"def test(): pass\\\")\\n    tree = parser.get_tree()\\n    for node in ast.walk(tree):\\n        if isinstance(node, ast.FunctionDef):\\n            parser.parse_functions(node)\\n    assert len(parser.data[\\\"functions\\\"]) == 1\\n    assert parser.data[\\\"functions\\\"][0][\\\"name\\\"] == \\\"test\\\"\\n\\n\\ndef test_code_parser_parse_classes():\\n    \\\"\\\"\\\"Test the parse_classes method of the CodeParser class.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"from langflow.custom import Component\\\\n\\\\nclass Test(Component): pass\\\")\\n    tree = parser.get_tree()\\n    for node in ast.walk(tree):\\n        if isinstance(node, ast.ClassDef):\\n            parser.parse_classes(node)\\n    assert len(parser.data[\\\"classes\\\"]) == 1\\n    assert parser.data[\\\"classes\\\"][0][\\\"name\\\"] == \\\"Test\\\"\\n\\n\\ndef test_code_parser_parse_classes_raises():\\n    \\\"\\\"\\\"Test the parse_classes method of the CodeParser class.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"class Test: pass\\\")\\n    tree = parser.get_tree()\\n    for node in ast.walk(tree):\\n        if isinstance(node, ast.ClassDef):\\n            with pytest.raises(TypeError):\\n                parser.parse_classes(node)\\n\\n\\ndef test_code_parser_parse_global_vars():\\n    \\\"\\\"\\\"Test the parse_global_vars method of the CodeParser class.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"x = 1\\\")\\n    tree = parser.get_tree()\\n    for node in ast.walk(tree):\\n        if isinstance(node, ast.Assign):\\n            parser.parse_global_vars(node)\\n    assert len(parser.data[\\\"global_vars\\\"]) == 1\\n    assert parser.data[\\\"global_vars\\\"][0][\\\"targets\\\"] == [\\\"x\\\"]\\n\\n\\ndef test_component_get_function_valid():\\n    \\\"\\\"\\\"Test the get_function method of the Component class with valid code and function_entrypoint_name.\\\"\\\"\\\"\\n    component = BaseComponent(_code=\\\"def build(): pass\\\", _function_entrypoint_name=\\\"build\\\")\\n    my_function = component.get_function()\\n    assert callable(my_function)\\n\\n\\ndef test_custom_component_get_function_entrypoint_args():\\n    \\\"\\\"\\\"Test the get_function_entrypoint_args property of the CustomComponent class.\\\"\\\"\\\"\\n    custom_component = CustomComponent(_code=code_default, _function_entrypoint_name=\\\"build\\\")\\n    args = custom_component.get_function_entrypoint_args\\n    assert len(args) == 3\\n    assert args[0][\\\"name\\\"] == \\\"self\\\"\\n    assert args[1][\\\"name\\\"] == \\\"url\\\"\\n    assert args[2][\\\"name\\\"] == \\\"llm\\\"\\n\\n\\ndef test_custom_component_get_function_entrypoint_return_type():\\n    \\\"\\\"\\\"Test the get_function_entrypoint_return_type property of the CustomComponent class.\\\"\\\"\\\"\\n    custom_component = CustomComponent(_code=code_default, _function_entrypoint_name=\\\"build\\\")\\n    return_type = custom_component._get_function_entrypoint_return_type\\n    assert return_type == [Document]\\n\\n\\ndef test_custom_component_get_main_class_name():\\n    \\\"\\\"\\\"Test the get_main_class_name property of the CustomComponent class.\\\"\\\"\\\"\\n    custom_component = CustomComponent(_code=code_default, _function_entrypoint_name=\\\"build\\\")\\n    class_name = custom_component.get_main_class_name\\n    assert class_name == \\\"YourComponent\\\"\\n\\n\\ndef test_custom_component_get_function_valid():\\n    \\\"\\\"\\\"Test the get_function property of the CustomComponent class with valid code and function_entrypoint_name.\\\"\\\"\\\"\\n    custom_component = CustomComponent(_code=\\\"def build(): pass\\\", _function_entrypoint_name=\\\"build\\\")\\n    my_function = custom_component.get_function\\n    assert callable(my_function)\\n\\n\\ndef test_code_parser_parse_arg_no_annotation():\\n    \\\"\\\"\\\"Test the parse_arg method of the CodeParser class without an annotation.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"\\\")\\n    arg = ast.arg(arg=\\\"x\\\", annotation=None)\\n    result = parser.parse_arg(arg, None)\\n    assert result[\\\"name\\\"] == \\\"x\\\"\\n    assert \\\"type\\\" not in result\\n\\n\\ndef test_code_parser_parse_arg_with_annotation():\\n    \\\"\\\"\\\"Test the parse_arg method of the CodeParser class with an annotation.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"\\\")\\n    arg = ast.arg(arg=\\\"x\\\", annotation=ast.Name(id=\\\"int\\\", ctx=ast.Load()))\\n    result = parser.parse_arg(arg, None)\\n    assert result[\\\"name\\\"] == \\\"x\\\"\\n    assert result[\\\"type\\\"] == \\\"int\\\"\\n\\n\\ndef test_code_parser_parse_callable_details_no_args():\\n    \\\"\\\"\\\"Test the parse_callable_details method of the CodeParser class with a function with no arguments.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"\\\")\\n    node = ast.FunctionDef(\\n        name=\\\"test\\\",\\n        args=ast.arguments(args=[], vararg=None, kwonlyargs=[], kw_defaults=[], kwarg=None, defaults=[]),\\n        body=[],\\n        decorator_list=[],\\n        returns=None,\\n    )\\n    result = parser.parse_callable_details(node)\\n    assert result[\\\"name\\\"] == \\\"test\\\"\\n    assert len(result[\\\"args\\\"]) == 0\\n\\n\\ndef test_code_parser_parse_assign():\\n    \\\"\\\"\\\"Test the parse_assign method of the CodeParser class.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"\\\")\\n    stmt = ast.Assign(targets=[ast.Name(id=\\\"x\\\", ctx=ast.Store())], value=ast.Constant(value=1))\\n    result = parser.parse_assign(stmt)\\n    assert result[\\\"name\\\"] == \\\"x\\\"\\n    assert result[\\\"value\\\"] == \\\"1\\\"\\n\\n\\ndef test_code_parser_parse_ann_assign():\\n    \\\"\\\"\\\"Test the parse_ann_assign method of the CodeParser class.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"\\\")\\n    stmt = ast.AnnAssign(\\n        target=ast.Name(id=\\\"x\\\", ctx=ast.Store()),\\n        annotation=ast.Name(id=\\\"int\\\", ctx=ast.Load()),\\n        value=ast.Constant(value=1),\\n        simple=1,\\n    )\\n    result = parser.parse_ann_assign(stmt)\\n    assert result[\\\"name\\\"] == \\\"x\\\"\\n    assert result[\\\"value\\\"] == \\\"1\\\"\\n    assert result[\\\"annotation\\\"] == \\\"int\\\"\\n\\n\\ndef test_code_parser_parse_function_def_not_init():\\n    \\\"\\\"\\\"Test the parse_function_def method of the CodeParser class with a function that is not __init__.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"\\\")\\n    stmt = ast.FunctionDef(\\n        name=\\\"test\\\",\\n        args=ast.arguments(args=[], vararg=None, kwonlyargs=[], kw_defaults=[], kwarg=None, defaults=[]),\\n        body=[],\\n        decorator_list=[],\\n        returns=None,\\n    )\\n    result, is_init = parser.parse_function_def(stmt)\\n    assert result[\\\"name\\\"] == \\\"test\\\"\\n    assert not is_init\\n\\n\\ndef test_code_parser_parse_function_def_init():\\n    \\\"\\\"\\\"Test the parse_function_def method of the CodeParser class with an __init__ function.\\\"\\\"\\\"\\n    parser = CodeParser(\\\"\\\")\\n    stmt = ast.FunctionDef(\\n        name=\\\"__init__\\\",\\n        args=ast.arguments(args=[], vararg=None, kwonlyargs=[], kw_defaults=[], kwarg=None, defaults=[]),\\n        body=[],\\n        decorator_list=[],\\n        returns=None,\\n    )\\n    result, is_init = parser.parse_function_def(stmt)\\n    assert result[\\\"name\\\"] == \\\"__init__\\\"\\n    assert is_init\\n\\n\\ndef test_component_get_code_tree_syntax_error():\\n    \\\"\\\"\\\"Test the get_code_tree method of the Component class raises the CodeSyntaxError when given incorrect syntax.\\\"\\\"\\\"\\n    component = BaseComponent(_code=\\\"import os as\\\", _function_entrypoint_name=\\\"build\\\")\\n    with pytest.raises(CodeSyntaxError):\\n        component.get_code_tree(component._code)\\n\\n\\ndef test_custom_component_class_template_validation_no_code():\\n    \\\"\\\"\\\"Test CustomComponent._class_template_validation raises the HTTPException when the code is None.\\\"\\\"\\\"\\n    custom_component = CustomComponent(_code=None, _function_entrypoint_name=\\\"build\\\")\\n    with pytest.raises(TypeError):\\n        custom_component.get_function()\\n\\n\\ndef test_custom_component_get_code_tree_syntax_error():\\n    \\\"\\\"\\\"Test CustomComponent.get_code_tree raises the CodeSyntaxError when given incorrect syntax.\\\"\\\"\\\"\\n    custom_component = CustomComponent(_code=\\\"import os as\\\", _function_entrypoint_name=\\\"build\\\")\\n    with pytest.raises(CodeSyntaxError):\\n        custom_component.get_code_tree(custom_component._code)\\n\\n\\ndef test_custom_component_get_function_entrypoint_args_no_args():\\n    \\\"\\\"\\\"Test CustomComponent.get_function_entrypoint_args with a build method with no arguments.\\\"\\\"\\\"\\n    my_code = \\\"\\\"\\\"\\nfrom langflow.custom import CustomComponent\\nclass MyMainClass(CustomComponent):\\n    def build():\\n        pass\\\"\\\"\\\"\\n\\n    custom_component = CustomComponent(_code=my_code, _function_entrypoint_name=\\\"build\\\")\\n    args = custom_component.get_function_entrypoint_args\\n    assert len(args) == 0\\n\\n\\ndef test_custom_component_get_function_entrypoint_return_type_no_return_type():\\n    \\\"\\\"\\\"Test CustomComponent.get_function_entrypoint_return_type with a build method with no return type.\\\"\\\"\\\"\\n    my_code = \\\"\\\"\\\"\\nfrom langflow.custom import CustomComponent\\nclass MyClass(CustomComponent):\\n    def build():\\n        pass\\\"\\\"\\\"\\n\\n    custom_component = CustomComponent(_code=my_code, _function_entrypoint_name=\\\"build\\\")\\n    return_type = custom_component._get_function_entrypoint_return_type\\n    assert return_type == []\\n\\n\\ndef test_custom_component_get_main_class_name_no_main_class():\\n    \\\"\\\"\\\"Test the get_main_class_name property of the CustomComponent class when there is no main class.\\\"\\\"\\\"\\n    my_code = \\\"\\\"\\\"\\ndef build():\\n    pass\\\"\\\"\\\"\\n\\n    custom_component = CustomComponent(_code=my_code, _function_entrypoint_name=\\\"build\\\")\\n    class_name = custom_component.get_main_class_name\\n    assert class_name == \\\"\\\"\\n\\n\\ndef test_custom_component_build_not_implemented():\\n    \\\"\\\"\\\"Test the build method of the CustomComponent class raises the NotImplementedError.\\\"\\\"\\\"\\n    custom_component = CustomComponent(_code=\\\"def build(): pass\\\", _function_entrypoint_name=\\\"build\\\")\\n    with pytest.raises(NotImplementedError):\\n        custom_component.build()\\n\\n\\ndef test_build_config_no_code():\\n    component = CustomComponent(_code=None)\\n\\n    assert component.get_function_entrypoint_args == []\\n    assert component._get_function_entrypoint_return_type == []\\n\\n\\n@pytest.fixture\\ndef component():\\n    return CustomComponent(\\n        field_config={\\n            \\\"fields\\\": {\\n                \\\"llm\\\": {\\\"type\\\": \\\"str\\\"},\\n                \\\"url\\\": {\\\"type\\\": \\\"str\\\"},\\n                \\\"year\\\": {\\\"type\\\": \\\"int\\\"},\\n            }\\n        },\\n    )\\n\\n\\ndef test_build_config_return_type(component):\\n    config = component.build_config()\\n    assert isinstance(config, dict)\\n\\n\\ndef test_build_config_has_fields(component):\\n    config = component.build_config()\\n    assert \\\"fields\\\" in config\\n\\n\\ndef test_build_config_fields_dict(component):\\n    config = component.build_config()\\n    assert isinstance(config[\\\"fields\\\"], dict)\\n\\n\\ndef test_build_config_field_keys(component):\\n    config = component.build_config()\\n    assert all(isinstance(key, str) for key in config[\\\"fields\\\"])\\n\\n\\ndef test_build_config_field_values_dict(component):\\n    config = component.build_config()\\n    assert all(isinstance(value, dict) for value in config[\\\"fields\\\"].values())\\n\\n\\ndef test_build_config_field_value_keys(component):\\n    config = component.build_config()\\n    field_values = config[\\\"fields\\\"].values()\\n    assert all(\\\"type\\\" in value for value in field_values)\\n\\n\\ndef test_custom_component_multiple_outputs(code_component_with_multiple_outputs):\\n    frontnd_node_dict, _ = build_custom_component_template(code_component_with_multiple_outputs)\\n    assert frontnd_node_dict[\\\"outputs\\\"][0][\\\"types\\\"] == [\\\"Text\\\"]\\n\\n\\ndef test_custom_component_subclass_from_lctoolcomponent():\\n    # Import LCToolComponent and create a subclass\\n    code = dedent(\\\"\\\"\\\"\\n    from lfx.base.langchain_utilities.model import LCToolComponent\\n    from langchain_core.tools import Tool\\n    class MyComponent(LCToolComponent):\\n        name: str = \\\"MyComponent\\\"\\n        description: str = \\\"MyComponent\\\"\\n\\n        def build_tool(self) -> Tool:\\n            return Tool(name=\\\"MyTool\\\", description=\\\"MyTool\\\")\\n\\n        def run_model(self)-> Data:\\n            return Data(data=\\\"Hello World\\\")\\n    \\\"\\\"\\\")\\n    component = Component(_code=code)\\n    frontend_node, _ = build_custom_component_template(component)\\n    assert \\\"outputs\\\" in frontend_node\\n    assert frontend_node[\\\"outputs\\\"][0][\\\"types\\\"] != []\\n    assert frontend_node[\\\"outputs\\\"][1][\\\"types\\\"] != []\\n\\n\\ndef test_build_custom_component_template_includes_metadata_with_module():\\n    \\\"\\\"\\\"Test that build_custom_component_template includes metadata when module_name is provided.\\\"\\\"\\\"\\n    code = dedent(\\\"\\\"\\\"\\n    from lfx.custom import Component\\n    from lfx.inputs import MessageTextInput\\n    from lfx.template.field.base import Output\\n\\n    class TestMetadataComponent(Component):\\n        display_name = \\\"Test Metadata Component\\\"\\n        description = \\\"Test component for metadata\\\"\\n\\n        inputs = [\\n            MessageTextInput(display_name=\\\"Input\\\", name=\\\"input_value\\\"),\\n        ]\\n        outputs = [\\n            Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"process_input\\\"),\\n        ]\\n\\n        def process_input(self) -> str:\\n            return f\\\"Processed: {self.input_value}\\\"\\n    \\\"\\\"\\\")\\n\\n    component = Component(_code=code)\\n    frontend_node, _ = build_custom_component_template(component, module_name=\\\"test.module\\\")\\n\\n    # Verify metadata is present\\n    assert \\\"metadata\\\" in frontend_node\\n    # metadata = frontend_node[\\\"metadata\\\"]\\n\\n    # Verify metadata contains required fields\\n    # assert \\\"module\\\" in metadata\\n    # assert \\\"code_hash\\\" in metadata\\n\\n    # Verify metadata values\\n    # assert metadata[\\\"module\\\"] == \\\"test.module\\\"\\n    # assert isinstance(metadata[\\\"code_hash\\\"], str)\\n    # assert len(metadata[\\\"code_hash\\\"]) == 12\\n    # assert all(c in \\\"0123456789abcdef\\\" for c in metadata[\\\"code_hash\\\"])\\n\\n\\ndef test_build_custom_component_template_always_has_metadata():\\n    \\\"\\\"\\\"Test that build_custom_component_template always generates metadata, even when module_name is None.\\\"\\\"\\\"\\n    code = dedent(\\\"\\\"\\\"\\n    from lfx.custom import Component\\n    from lfx.template.field.base import Output\\n\\n    class TestAlwaysMetadata(Component):\\n        display_name = \\\"Test Always Metadata\\\"\\n\\n        outputs = [\\n            Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"get_result\\\"),\\n        ]\\n\\n        def get_result(self) -> str:\\n            return \\\"test\\\"\\n    \\\"\\\"\\\")\\n\\n    component = Component(_code=code)\\n    frontend_node, _ = build_custom_component_template(component, module_name=None)\\n\\n    # Metadata should ALWAYS be present\\n    assert \\\"metadata\\\" in frontend_node\\n    # metadata = frontend_node[\\\"metadata\\\"]\\n\\n    # TODO: Temporarily skip metadata checks\\n    # assert \\\"module\\\" in metadata\\n    # assert \\\"code_hash\\\" in metadata\\n\\n    # # Should generate default module name from display_name\\n    # assert metadata[\\\"module\\\"] == \\\"custom_components.test_always_metadata\\\"\\n    # assert len(metadata[\\\"code_hash\\\"]) == 12\\n\\n\\ndef test_build_custom_component_template_metadata_hash_changes():\\n    \\\"\\\"\\\"Test that code hash changes when component code changes.\\\"\\\"\\\"\\n    code_v1 = dedent(\\\"\\\"\\\"\\n    from lfx.custom import Component\\n    from lfx.template.field.base import Output\\n\\n    class VersionComponent(Component):\\n        display_name = \\\"Version Component\\\"\\n        version = \\\"1.0\\\"\\n\\n        outputs = [\\n            Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"get_version\\\"),\\n        ]\\n\\n        def get_version(self) -> str:\\n            return \\\"version 1.0\\\"\\n    \\\"\\\"\\\")\\n\\n    code_v2 = dedent(\\\"\\\"\\\"\\n    from lfx.custom import Component\\n    from lfx.template.field.base import Output\\n\\n    class VersionComponent(Component):\\n        display_name = \\\"Version Component\\\"\\n        version = \\\"2.0\\\"\\n\\n        outputs = [\\n            Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"get_version\\\"),\\n        ]\\n\\n        def get_version(self) -> str:\\n            return \\\"version 2.0\\\"\\n    \\\"\\\"\\\")\\n\\n    component_v1 = Component(_code=code_v1)\\n    component_v2 = Component(_code=code_v2)\\n\\n    frontend_node_v1, _ = build_custom_component_template(component_v1, module_name=\\\"test.version\\\")\\n    frontend_node_v2, _ = build_custom_component_template(component_v2, module_name=\\\"test.version\\\")\\n\\n    metadata_v1 = frontend_node_v1[\\\"metadata\\\"]\\n    metadata_v2 = frontend_node_v2[\\\"metadata\\\"]\\n    assert metadata_v1 is not None\\n    assert metadata_v2 is not None\\n\\n    # Same module name\\n    # assert metadata_v1[\\\"module\\\"] == metadata_v2[\\\"module\\\"]\\n\\n    # Different code hashes\\n    # assert metadata_v1[\\\"code_hash\\\"] != metadata_v2[\\\"code_hash\\\"]\\n\\n\\ndef test_build_custom_component_template_metadata_unicode():\\n    \\\"\\\"\\\"Test that metadata generation works with unicode characters in code.\\\"\\\"\\\"\\n    code = dedent(\\\"\\\"\\\"\\n    from lfx.custom import Component\\n    from lfx.template.field.base import Output\\n\\n    class UnicodeComponent(Component):\\n        display_name = \\\"Unicode Test \ud83c\udf1f\\\"\\n        description = \\\"\u6d4b\u8bd5\u7ec4\u4ef6 with \u00e9mojis\\\"\\n\\n        outputs = [\\n            Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"get_unicode\\\"),\\n        ]\\n\\n        def get_unicode(self) -> str:\\n            # Comment with unicode: \u4f60\u597d\u4e16\u754c \ud83d\ude80\\n            return \\\"Hello \u4e16\u754c!\\\"\\n    \\\"\\\"\\\")\\n\\n    component = Component(_code=code)\\n    frontend_node, _ = build_custom_component_template(component, module_name=\\\"unicode.test\\\")\\n\\n    # Verify metadata is present and valid\\n    metadata = frontend_node[\\\"metadata\\\"]\\n    assert metadata is not None\\n    # assert \\\"module\\\" in metadata\\n    # assert \\\"code_hash\\\" in metadata\\n\\n    # Verify hash is valid hexadecimal\\n    # code_hash = metadata[\\\"code_hash\\\"]\\n    # assert len(code_hash) == 12\\n    # assert all(c in \\\"0123456789abcdef\\\" for c in code_hash)\\n\\n\\ndef test_build_custom_component_template_component_always_has_metadata():\\n    \\\"\\\"\\\"Test that build_custom_component_template always returns metadata for Component path.\\\"\\\"\\\"\\n    code = dedent(\\\"\\\"\\\"\\n    from lfx.custom import Component\\n    from lfx.inputs import MessageTextInput\\n    from lfx.template.field.base import Output\\n\\n    class TestComponentMetadata(Component):\\n        display_name = \\\"Test Component Metadata\\\"\\n\\n        inputs = [\\n            MessageTextInput(display_name=\\\"Input\\\", name=\\\"input_value\\\"),\\n        ]\\n        outputs = [\\n            Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"process_input\\\"),\\n        ]\\n\\n        def process_input(self) -> str:\\n            return f\\\"Processed: {self.input_value}\\\"\\n    \\\"\\\"\\\")\\n\\n    component = Component(_code=code)\\n    frontend_node, _ = build_custom_component_template(component, module_name=None)\\n\\n    # Metadata should ALWAYS be present, even for Component without module_name\\n    assert \\\"metadata\\\" in frontend_node\\n    # metadata = frontend_node[\\\"metadata\\\"]\\n\\n    # assert \\\"module\\\" in metadata\\n    # assert \\\"code_hash\\\" in metadata\\n\\n    # Should generate default module name from display_name\\n    # assert metadata[\\\"module\\\"] == \\\"custom_components.test_component_metadata\\\"\\n    # assert len(metadata[\\\"code_hash\\\"]) == 12\\n\\n\\ndef test_metadata_always_returned_comprehensive():\\n    \\\"\\\"\\\"Comprehensive test to verify metadata is ALWAYS returned in all scenarios.\\\"\\\"\\\"\\n    # Test scenario 1: Component with module_name provided\\n    code1 = dedent(\\\"\\\"\\\"\\n    from lfx.custom import Component\\n    from lfx.template.field.base import Output\\n\\n    class TestWithModule(Component):\\n        display_name = \\\"Test With Module\\\"\\n\\n        outputs = [\\n            Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"get_result\\\"),\\n        ]\\n\\n        def get_result(self) -> str:\\n            return \\\"with module\\\"\\n    \\\"\\\"\\\")\\n\\n    component1 = Component(_code=code1)\\n    frontend_node1, _ = build_custom_component_template(component1, module_name=\\\"explicit.module\\\")\\n\\n    assert \\\"metadata\\\" in frontend_node1\\n    # assert frontend_node1[\\\"metadata\\\"][\\\"module\\\"] == \\\"explicit.module\\\"\\n    # assert \\\"code_hash\\\" in frontend_node1[\\\"metadata\\\"]\\n    # assert len(frontend_node1[\\\"metadata\\\"][\\\"code_hash\\\"]) == 12\\n\\n    # Test scenario 2: Component without module_name (should generate default)\\n    component2 = Component(_code=code1)\\n    frontend_node2, _ = build_custom_component_template(component2, module_name=None)\\n\\n    assert \\\"metadata\\\" in frontend_node2\\n    # assert frontend_node2[\\\"metadata\\\"][\\\"module\\\"] == \\\"custom_components.test_with_module\\\"\\n    # assert \\\"code_hash\\\" in frontend_node2[\\\"metadata\\\"]\\n    # assert len(frontend_node2[\\\"metadata\\\"][\\\"code_hash\\\"]) == 12\\n\\n    # Test scenario 3: Component with inputs and outputs\\n    code3 = dedent(\\\"\\\"\\\"\\n    from lfx.custom import Component\\n    from lfx.inputs import MessageTextInput\\n    from lfx.template.field.base import Output\\n\\n    class TestWithInputs(Component):\\n        display_name = \\\"Test With Inputs\\\"\\n\\n        inputs = [\\n            MessageTextInput(display_name=\\\"Input\\\", name=\\\"input_value\\\"),\\n        ]\\n        outputs = [\\n            Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"process_input\\\"),\\n        ]\\n\\n        def process_input(self) -> str:\\n            return f\\\"Processed: {self.input_value}\\\"\\n    \\\"\\\"\\\")\\n\\n    component3 = Component(_code=code3)\\n    frontend_node3, _ = build_custom_component_template(component3, module_name=\\\"custom.explicit\\\")\\n\\n    assert \\\"metadata\\\" in frontend_node3\\n    # assert frontend_node3[\\\"metadata\\\"][\\\"module\\\"] == \\\"custom.explicit\\\"\\n    # assert \\\"code_hash\\\" in frontend_node3[\\\"metadata\\\"]\\n    # assert len(frontend_node3[\\\"metadata\\\"][\\\"code_hash\\\"]) == 12\\n\\n    # Test scenario 4: Component without module_name (should generate default)\\n    component4 = Component(_code=code3)\\n    frontend_node4, _ = build_custom_component_template(component4, module_name=None)\\n\\n    assert \\\"metadata\\\" in frontend_node4\\n    # assert frontend_node4[\\\"metadata\\\"][\\\"module\\\"] == \\\"custom_components.test_with_inputs\\\"\\n    # assert \\\"code_hash\\\" in frontend_node4[\\\"metadata\\\"]\\n    # assert len(frontend_node4[\\\"metadata\\\"][\\\"code_hash\\\"]) == 12\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_custom_component_with_client.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"efe653095d7958901d0b4df644f31be4514a5ff71289de2b17f344bc2c23ddef\",\"content\":\"import pytest\\nfrom langflow.custom.custom_component.custom_component import CustomComponent\\nfrom lfx.field_typing.constants import Data\\n\\n\\n@pytest.fixture\\ndef component(\\n    client,  # noqa: ARG001\\n    active_user,\\n):\\n    return CustomComponent(\\n        user_id=active_user.id,\\n        field_config={\\n            \\\"fields\\\": {\\n                \\\"llm\\\": {\\\"type\\\": \\\"str\\\"},\\n                \\\"url\\\": {\\\"type\\\": \\\"str\\\"},\\n                \\\"year\\\": {\\\"type\\\": \\\"int\\\"},\\n            }\\n        },\\n    )\\n\\n\\nasync def test_list_flows_flow_objects(component):\\n    flows = await component.alist_flows()\\n    are_flows = [isinstance(flow, Data) for flow in flows]\\n    flow_types = [type(flow) for flow in flows]\\n    assert all(are_flows), f\\\"Expected all flows to be Data objects, got {flow_types}\\\"\\n\\n\\nasync def test_list_flows_return_type(component):\\n    flows = await component.alist_flows()\\n    assert isinstance(flows, list)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_database.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5ebdba9914eda9c215b999ccfab4d36fce2a71b5bea264f72c0133705525b584\",\"content\":\"import io\\nimport json\\nimport zipfile\\nfrom datetime import datetime, timezone\\nfrom typing import NamedTuple\\nfrom uuid import UUID, uuid4\\n\\nimport orjson\\nimport pytest\\nfrom httpx import AsyncClient\\nfrom langflow.api.v1.schemas import FlowListCreate, ResultDataResponse\\nfrom langflow.initial_setup.setup import filter_starter_projects_by_available_components, load_starter_projects\\nfrom langflow.interface.components import get_and_cache_all_types_dict\\nfrom langflow.services.database.models.base import orjson_dumps\\nfrom langflow.services.database.models.flow import Flow, FlowCreate, FlowUpdate\\nfrom langflow.services.database.models.folder.model import FolderCreate\\nfrom langflow.services.database.utils import session_getter\\nfrom langflow.services.deps import get_db_service, get_settings_service\\nfrom lfx.graph.utils import log_transaction, log_vertex_build\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef json_style():\\n    # class FlowStyleBase(SQLModel):\\n    # color: str = Field(index=True)\\n    # emoji: str = Field(index=False)\\n    # flow_id: UUID = Field(default=None, foreign_key=\\\"flow.id\\\")\\n    return orjson_dumps(\\n        {\\n            \\\"color\\\": \\\"red\\\",\\n            \\\"emoji\\\": \\\"\ud83d\udc4d\\\",\\n        }\\n    )\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_create_flow(client: AsyncClient, json_flow: str, logged_in_headers):\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n    flow = FlowCreate(name=str(uuid4()), description=\\\"description\\\", data=data)\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201\\n    assert response.json()[\\\"name\\\"] == flow.name\\n    assert response.json()[\\\"data\\\"] == flow.data\\n    # flow is optional so we can create a flow without a flow\\n    flow = FlowCreate(name=str(uuid4()))\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(exclude_unset=True), headers=logged_in_headers)\\n    assert response.status_code == 201\\n    assert response.json()[\\\"name\\\"] == flow.name\\n    assert response.json()[\\\"data\\\"] == flow.data\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_read_flows(client: AsyncClient, json_flow: str, logged_in_headers):\\n    flow_data = orjson.loads(json_flow)\\n    data = flow_data[\\\"data\\\"]\\n    flow = FlowCreate(name=str(uuid4()), description=\\\"description\\\", data=data)\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201\\n    assert response.json()[\\\"name\\\"] == flow.name\\n    assert response.json()[\\\"data\\\"] == flow.data\\n\\n    flow = FlowCreate(name=str(uuid4()), description=\\\"description\\\", data=data)\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201\\n    assert response.json()[\\\"name\\\"] == flow.name\\n    assert response.json()[\\\"data\\\"] == flow.data\\n\\n    response = await client.get(\\\"api/v1/flows/\\\", headers=logged_in_headers)\\n    assert response.status_code == 200\\n    assert len(response.json()) > 0\\n\\n\\nasync def test_read_flows_pagination_with_params(client: AsyncClient, logged_in_headers):\\n    response = await client.get(\\n        \\\"api/v1/flows/\\\", headers=logged_in_headers, params={\\\"page\\\": 3, \\\"size\\\": 10, \\\"get_all\\\": False}\\n    )\\n    assert response.status_code == 200\\n    assert response.json()[\\\"page\\\"] == 3\\n    assert response.json()[\\\"size\\\"] == 10\\n    assert response.json()[\\\"pages\\\"] == 0\\n    assert response.json()[\\\"total\\\"] == 0\\n    assert len(response.json()[\\\"items\\\"]) == 0\\n\\n\\nasync def test_read_flows_pagination_with_flows(client: AsyncClient, logged_in_headers):\\n    number_of_flows = 30\\n    flows = [FlowCreate(name=f\\\"Flow {i}\\\", description=\\\"description\\\", data={}) for i in range(number_of_flows)]\\n    flow_ids = []\\n    for flow in flows:\\n        response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n        assert response.status_code == 201\\n        flow_ids.append(response.json()[\\\"id\\\"])\\n\\n    response = await client.get(\\n        \\\"api/v1/flows/\\\", headers=logged_in_headers, params={\\\"page\\\": 3, \\\"size\\\": 10, \\\"get_all\\\": False}\\n    )\\n    assert response.status_code == 200\\n    assert response.json()[\\\"page\\\"] == 3\\n    assert response.json()[\\\"size\\\"] == 10\\n    assert response.json()[\\\"pages\\\"] == 3\\n    assert response.json()[\\\"total\\\"] == number_of_flows\\n    assert len(response.json()[\\\"items\\\"]) == 10\\n\\n    response = await client.get(\\n        \\\"api/v1/flows/\\\", headers=logged_in_headers, params={\\\"page\\\": 4, \\\"size\\\": 10, \\\"get_all\\\": False}\\n    )\\n    assert response.status_code == 200\\n    assert response.json()[\\\"page\\\"] == 4\\n    assert response.json()[\\\"size\\\"] == 10\\n    assert response.json()[\\\"pages\\\"] == 3\\n    assert response.json()[\\\"total\\\"] == number_of_flows\\n    assert len(response.json()[\\\"items\\\"]) == 0\\n\\n\\nasync def test_read_flows_custom_page_size(client: AsyncClient, logged_in_headers):\\n    number_of_flows = 30\\n    flows = [FlowCreate(name=f\\\"Flow {i}\\\", description=\\\"description\\\", data={}) for i in range(number_of_flows)]\\n    for flow in flows:\\n        response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n        assert response.status_code == 201\\n\\n    response = await client.get(\\n        \\\"api/v1/flows/\\\", headers=logged_in_headers, params={\\\"page\\\": 1, \\\"size\\\": 15, \\\"get_all\\\": False}\\n    )\\n    assert response.status_code == 200\\n    assert response.json()[\\\"page\\\"] == 1\\n    assert response.json()[\\\"size\\\"] == 15\\n    assert response.json()[\\\"pages\\\"] == 2\\n    assert response.json()[\\\"total\\\"] == number_of_flows\\n    assert len(response.json()[\\\"items\\\"]) == 15\\n\\n\\nasync def test_read_flows_invalid_page(client: AsyncClient, logged_in_headers):\\n    number_of_flows = 30\\n    flows = [FlowCreate(name=f\\\"Flow {i}\\\", description=\\\"description\\\", data={}) for i in range(number_of_flows)]\\n    flow_ids = []\\n    for flow in flows:\\n        response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n        assert response.status_code == 201\\n        flow_ids.append(response.json()[\\\"id\\\"])\\n\\n    response = await client.get(\\n        \\\"api/v1/flows/\\\", headers=logged_in_headers, params={\\\"page\\\": 0, \\\"size\\\": 10, \\\"get_all\\\": False}\\n    )\\n    assert response.status_code == 422  # Assuming 422 is the status code for invalid input\\n\\n\\nasync def test_read_flows_invalid_size(client: AsyncClient, logged_in_headers):\\n    number_of_flows = 30\\n    flows = [FlowCreate(name=f\\\"Flow {i}\\\", description=\\\"description\\\", data={}) for i in range(number_of_flows)]\\n    flow_ids = []\\n    for flow in flows:\\n        response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n        assert response.status_code == 201\\n        flow_ids.append(response.json()[\\\"id\\\"])\\n\\n    response = await client.get(\\n        \\\"api/v1/flows/\\\", headers=logged_in_headers, params={\\\"page\\\": 1, \\\"size\\\": 0, \\\"get_all\\\": False}\\n    )\\n    assert response.status_code == 422  # Assuming 422 is the status code for invalid input\\n\\n\\nasync def test_read_flows_no_pagination_params(client: AsyncClient, logged_in_headers):\\n    number_of_flows = 30\\n    flows = [FlowCreate(name=f\\\"Flow {i}\\\", description=\\\"description\\\", data={}) for i in range(number_of_flows)]\\n    for flow in flows:\\n        response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n        assert response.status_code == 201\\n\\n    response = await client.get(\\\"api/v1/flows/\\\", headers=logged_in_headers, params={\\\"get_all\\\": False})\\n    assert response.status_code == 200\\n    # Assert default pagination values, adjust these according to your API's default behavior\\n    assert response.json()[\\\"page\\\"] == 1\\n    assert response.json()[\\\"size\\\"] == 50\\n    assert response.json()[\\\"pages\\\"] == 1\\n    assert response.json()[\\\"total\\\"] == number_of_flows\\n    assert len(response.json()[\\\"items\\\"]) == number_of_flows\\n\\n\\nasync def test_read_flows_components_only_paginated(client: AsyncClient, logged_in_headers):\\n    number_of_flows = 10\\n    flows = [\\n        FlowCreate(name=f\\\"Flow {i}\\\", description=\\\"description\\\", data={}, is_component=True)\\n        for i in range(number_of_flows)\\n    ]\\n\\n    for flow in flows:\\n        response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n        assert response.status_code == 201\\n\\n    response = await client.get(\\n        \\\"api/v1/flows/\\\", headers=logged_in_headers, params={\\\"components_only\\\": True, \\\"get_all\\\": False}\\n    )\\n\\n    assert response.status_code == 200\\n    response_json = response.json()\\n    assert response_json[\\\"total\\\"] == 10\\n    assert response_json[\\\"pages\\\"] == 1\\n    assert response_json[\\\"page\\\"] == 1\\n    assert response_json[\\\"size\\\"] == 50\\n    assert all(flow[\\\"is_component\\\"] is True for flow in response_json[\\\"items\\\"])\\n\\n\\nasync def test_read_flows_components_only(client: AsyncClient, logged_in_headers):\\n    number_of_flows = 10\\n    flows = [\\n        FlowCreate(name=f\\\"Flow {i}\\\", description=\\\"description\\\", data={}, is_component=True)\\n        for i in range(number_of_flows)\\n    ]\\n    for flow in flows:\\n        response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n        assert response.status_code == 201\\n    response = await client.get(\\\"api/v1/flows/\\\", headers=logged_in_headers, params={\\\"components_only\\\": True})\\n    assert response.status_code == 200\\n    response_json = response.json()\\n    assert all(flow[\\\"is_component\\\"] is True for flow in response_json)\\n\\n\\nasync def test_read_flow(client: AsyncClient, json_flow: str, logged_in_headers):\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n    unique_name = str(uuid4())\\n    flow = FlowCreate(name=unique_name, description=\\\"description\\\", data=data)\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n    flow_id = response.json()[\\\"id\\\"]  # flow_id should be a UUID but is a string\\n    # turn it into a UUID\\n    flow_id = UUID(flow_id)\\n\\n    response = await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)\\n    assert response.status_code == 200\\n    assert response.json()[\\\"name\\\"] == flow.name\\n    assert response.json()[\\\"data\\\"] == flow.data\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_update_flow(client: AsyncClient, json_flow: str, logged_in_headers):\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n\\n    flow = FlowCreate(name=\\\"Test Flow\\\", description=\\\"description\\\", data=data)\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n\\n    flow_id = response.json()[\\\"id\\\"]\\n    updated_flow = FlowUpdate(\\n        name=\\\"Updated Flow\\\",\\n        description=\\\"updated description\\\",\\n        data=data,\\n    )\\n    response = await client.patch(f\\\"api/v1/flows/{flow_id}\\\", json=updated_flow.model_dump(), headers=logged_in_headers)\\n\\n    assert response.status_code == 200\\n    assert response.json()[\\\"name\\\"] == updated_flow.name\\n    assert response.json()[\\\"description\\\"] == updated_flow.description\\n    # assert response.json()[\\\"data\\\"] == updated_flow.data\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync d";
